window.EXPL={"공인노2017_26-51-1":{"f":"소송사건에 증인으로서 증언에 대한 대가를 약정하였더라도 그 대가가 통상 용인될 수 있는 수준(일당·여비 등)을 넘지 않으면 무효가 아니다.","w":"증인에게 일당·여비·숙박료 같은 실비 정도를 주기로 한 약정은 유효하다. 대가가 통상 용인되는 수준을 넘을 때에 한해 반사회질서 행위로 무효가 된다.","c":"중","v":1},"공인노2017_26-51-2":{"f":"반사회질서 법률행위에 해당되는 매매계약을 원인으로 한 소유권이전등기명의자의 물권적 청구권 행사에 대하여 상대방은 법률행위의 무효를 주장할 수 있다.","w":"반사회질서 법률행위는 절대적 무효라서 그 계약을 원인으로 등기를 넘겨받은 사람이 물권적 청구권을 행사해도 상대방은 무효를 주장해 막을 수 있다(제103조).","c":"중","v":1},"공인노2017_26-51-4":{"f":"경매 목적물이 시가에 비해 현저하게 낮은 가격으로 매각된 경우에도 불공정한 법률행위로 무효가 될 수 없다.","w":"경매에는 불공정한 법률행위에 관한 제104조가 적용되지 않는다. 시가보다 아주 낮게 낙찰되어도 이를 이유로 무효가 되지 않는다.","c":"상","v":1},"공인노2017_26-51-5":{"f":"민사사건에 관한 변호사의 성공보수약정은 선량한 풍속 기타 사회질서에 위배되지 않아 유효하다.","w":"민사사건의 성공보수약정은 원칙적으로 유효하다. 무효로 본 대법원 전원합의체 판결(2015년)은 형사사건 성공보수약정에 관한 것이다.","c":"상","v":1},"공인노2017_26-52-1":{"f":"甲이 乙로 하여금 금융기관에 대해 乙을 주채무자로 하는 금전소비대차계약을 체결하도록 하고 甲이 그 원리금을 상환하기로 한 경우, 특별한 사정이 없는 한 위 소비대차계약은 통정허위표시가 아니다.","w":"통정허위표시는 상대방과 짜고 하는 허위 의사표시다. 금융기관이 乙을 차주로 알고 대출했다면 소비대차는 유효하고 乙이 주채무자로 책임을 진다.","c":"중","v":1},"공인노2017_26-54-1":{"f":"예금명의자의 위임에 의하여 자금출연자가 대리인으로 예금계약을 체결한 경우, 예금계약의 반환청구권자는 예금명의자이다.","w":"예금명의자가 위임해서 대리인이 계약한 경우 예금계약의 당사자는 본인인 예금명의자이므로 반환청구권도 예금명의자에게 있다.","c":"상","v":1},"공인노2017_26-54-2":{"f":"불법행위로 인한 손해배상에 관하여 가해자와 피해자 사이에 피해자가 일정한 금액을 지급받고 그 나머지의 청구를 포기하기로 약정한 때에는 모든 후발손해에 대해서도 배상청구권을 포기한 것으로 해석하여서는 안 된다.","w":"합의 당시 예상하지 못한 후발손해까지 포기한 것으로 보지 않는다. 포기의 범위는 당사자가 합의 당시 예상할 수 있었던 손해로 한정해 해석한다.","c":"상","v":1},"공인노2017_26-54-3":{"f":"본인이 대리인을 통하여 계약을 체결하는 것에 대하여 상대방이 그러한 사정을 알고 대리인과 계약을 체결하였는데 대리권이 존재하지 않은 경우, 계약의 당사자는 본인과 상대방이 된다.","w":"상대방이 본인을 위한 계약임을 알고 있었다면 당사자는 본인과 상대방이다. 대리권이 없으니 무권대리가 되어 본인의 추인 여부에 따라 효력이 정해진다.","c":"상","v":1},"공인노2017_26-54-4":{"f":"甲이 乙의 행세를 하여 乙 명의로 丙과 부동산을 매수하는 계약을 체결한 후 丙으로부터 인도받아 거주하고 있고, 丙이 甲을 매수인으로 알고 있는 경우 부동산 매매계약의 당사자는 甲과 丙이다.","w":"행위자와 상대방이 모두 행위자 자신(甲)을 매수인으로 이해했으므로 이 일치된 이해대로 甲이 당사자가 된다. 명의로 쓴 乙이 당사자가 되는 것이 아니다.","c":"상","v":1},"공인노2017_26-57-4":{"f":"대리인이 대리권 소멸 후 선임한 복대리인과 상대방 사이의 법률행위에는 대리권소멸 후 표현대리가 성립할 수 있다.","w":"대리권이 소멸한 뒤 대리인이 선임한 복대리인이 대리행위를 한 경우에도 제129조의 대리권소멸 후 표현대리가 성립할 수 있다는 것이 판례다.","c":"중","v":1},"공인노2017_26-58-1":{"f":"무권대리행위가 제3자의 기망이나 문서위조 등 위법행위로 야기된 경우에도 무권대리인의 상대방에 대한 책임은 부정되지 않는다.","w":"제135조의 무권대리인 책임은 무과실책임이다. 무권대리가 제3자의 기망이나 문서위조로 생긴 경우에도 책임이 면제되지 않는다.","c":"상","v":1},"공인노2017_26-58-2":{"f":"상대방이 무권대리인과 계약을 체결할 때 무권대리임을 알고 있는 경우에도, 상대방은 본인에게 추인 여부를 최고할 수 있다.","w":"제131조의 최고권은 상대방의 선의·악의를 가리지 않는다. 무권대리임을 알고 계약했어도 본인에게 추인 여부를 최고할 수 있다.","c":"상","v":1},"공인노2017_26-58-3":{"f":"무권대리행위가 범죄가 되는 경우에 본인이 그 사실을 알고도 장기간 형사고소를 하지 아니하였더라도 무권대리행위를 추인한 것이라고 할 수 없다.","w":"추인은 본인이 무권대리행위의 효과를 자기에게 귀속시키겠다는 의사를 보여야 성립한다. 형사고소를 하지 않았다는 사정만으로는 묵시적 추인으로 보지 않는다.","c":"상","v":1},"공인노2017_26-58-5":{"f":"무권대리인이 본인을 단독상속한 경우, 무권대리행위의 추인을 거절하는 것은 신의칙에 반한다.","w":"무권대리인이 본인을 단독상속해도 추인을 거절할 수 없다. 거절하면 신의칙에 반하므로 대리행위는 유효가 된다.","c":"상","v":1},"공인노2017_26-60-1":{"f":"가분적 법률행위의 일부분에만 취소사유가 있는 경우 나머지 부분이라도 이를 유지하려는 당사자의 가정적 의사가 인정되면 그 일부만의 취소도 가능하다.","w":"가분적 법률행위에서는 일부 취소가 가능하다. 나머지 부분을 유지하려는 당사자의 가정적 의사가 인정될 때 그 일부만 취소할 수 있다는 것이 판례다.","c":"상","v":1},"공인노2017_26-61-4":{"f":"당사자의 특약이 없거나 법률행위의 성질상 분명하지 않으면 기한의 이익은 채무자에게 있는 것으로 추정된다.","w":"기한의 이익은 채무자를 위한 것으로 추정한다(제153조 제1항).","c":"상","v":1},"공인노2019_28-56-5":{"f":"丙이 선의인 경우에도, 甲은 乙에게 X토지의 진정명의회복을 위한 소유권이전등기를 청구할 수 있다.","w":"丙이 취득한 것은 저당권일 뿐이고, 가장매매가 무효이므로 X토지의 소유권은 여전히 甲에게 있다. 丙이 선의이면 甲은 저당권의 부담은 안아야 하지만 乙에게 진정명의회복을 위한 소유권이전등기는 청구할 수 있다.","c":"중","v":1},"공인노2019_28-57-1":{"f":"매도인의 담보책임이 성립하는 경우에도, 매수인은 매매계약 내용의 중요부분에 착오가 있으면 이를 취소할 수 있다.","w":"하자담보책임과 착오 취소는 요건과 효과가 달라 경합한다. 담보책임이 성립해도 착오를 이유로 취소할 수 있다는 것이 판례다.","c":"상","v":1},"공인노2019_28-57-2":{"f":"소송행위에는 특별한 사정이 없는 한 착오를 이유로 하는 취소가 허용되지 않는다.","w":"소송행위는 절차의 안정이 중요해서 민법의 착오 취소 규정이 적용되지 않는다.","c":"상","v":1},"공인노2019_28-57-4":{"f":"표의자에게 중대한 과실이 있다는 사실은 의사표시의 취소를 막으려는 상대방이 증명하여야 한다.","w":"중대한 과실은 취소를 막으려는 상대방이 증명한다. 취소하려는 표의자가 자기 과실이 중대하지 않음을 증명하는 것이 아니다.","c":"상","v":1},"공인노2019_28-57-5":{"f":"매도인이 매수인의 채무불이행을 이유로 매매계약을 적법하게 해제한 경우에도 매수인은 착오를 이유로 그 매매계약을 취소할 수 있다.","w":"해제로 계약의 효력이 소멸한 뒤에도 매수인은 착오를 이유로 취소해 해제의 효과(손해배상 등)를 다툴 수 있다는 것이 판례다.","c":"상","v":1},"공인노2019_28-58-2":{"f":"대리인이 수인인 때에는 법률 또는 수권행위에서 달리 정한 바가 없으면 각자 본인을 대리한다.","w":"대리인이 여러 명이면 각자대리가 원칙이다(제119조). 공동으로 대리하려면 법률이나 수권행위에 정해야 한다.","c":"상","v":1},"공인노2019_28-59-5":{"f":"丙은 甲이 매매계약을 추인한 사실을 안 경우에는 무권대리임을 이유로 乙과 체결한 매매계약을 철회할 수 없다.","w":"상대방의 철회권은 본인의 추인이 있을 때까지만 있다(제134조 본문). 추인을 무권대리인 乙에게 했더라도 丙이 그 사실을 알았다면 甲은 추인으로 丙에게 대항할 수 있으므로(제132조 단서) 丙은 철회하지 못한다.","c":"상","v":1},"공인노2019_28-60-2":{"f":"취소권자가 이의의 보류 없이 상대방으로부터 일부의 이행을 수령한 경우에는 법정추인이 된다.","w":"취소할 수 있는 법률행위에서 취소권자가 이의를 보류하지 않고 상대방의 이행을 전부나 일부 받으면 법정추인이 된다(제145조).","c":"상","v":1},"공인노2019_28-60-3":{"f":"불공정한 법률행위는 법정추인에 의해 유효로 될 수 없다.","w":"불공정한 법률행위는 취소가 아니라 무효다. 법정추인은 취소할 수 있는 행위에 대한 제도라서 무효인 행위를 유효로 만들지 못한다.","c":"상","v":1},"공인노2019_28-60-4":{"f":"강박에 의한 의사표시를 취소하여 무효가 된 법률행위는 그 무효원인이 종료한 후 무효행위 추인의 요건에 따라 다시 추인할 수 있다.","w":"취소로 무효가 된 행위도 무효원인이 없어진 뒤에는 무효행위 추인의 요건과 효력으로 추인할 수 있다는 것이 판례다.","c":"상","v":1},"공인노2019_28-60-5":{"f":"토지거래허가구역 내의 토지의 매도인은 거래허가 전에는 매수인의 대금지급의무의 불이행을 이유로 계약을 해제할 수 없다.","w":"허가를 받기 전 계약은 유동적 무효 상태라 아직 이행을 청구할 수 없다. 대금지급의무가 이행기에 도래하지 않았으므로 채무불이행을 이유로 해제할 수 없다.","c":"상","v":1},"공인노2019_28-61-5":{"f":"정지조건부 법률행위는 조건이 성취된 때로부터 그 효력이 생긴다.","w":"정지조건은 성취한 때부터 효력이 생기는 것이 원칙이다(제147조 제1항). 소급효는 당사자가 특약으로 정한 때에만 있다.","c":"상","v":1},"공인노2022_31-55-1":{"f":"과도한 위약벌 약정은 법원이 직권으로 감액할 수 없으나 선량한 풍속 기타 사회질서에 반하는 범위에서 무효가 될 수 있다.","w":"위약벌은 손해배상 예정이 아니어서 제398조 제2항의 감액이 적용되지 않는다. 다만 지나치게 과도하면 공서양속에 반하는 한도에서 일부 또는 전부가 무효가 된다.","c":"상","v":1},"공인노2022_31-56-1":{"f":"통정허위표시에 의하여 생긴 채권을 가압류한 경우, 가압류권자는 선의이면 통정허위표시와 관련하여 보호받는 제3자에 해당한다.","w":"허위표시로 생긴 채권을 가압류한 사람은 그 채권을 기초로 새로운 법률상 이해관계를 맺었으므로 선의라면 제108조 제2항의 제3자로 보호된다.","c":"상","v":1},"공인노2022_31-56-2":{"f":"통정허위표시인 법률행위는 무효이더라도 채권자취소권의 대상인 사해행위로 될 수 있다.","w":"허위표시로 무효인 행위도 채권자취소권의 대상이 될 수 있다. 무효라는 이유로 채권자취소가 배제되지 않는다.","c":"상","v":1},"공인노2022_31-56-3":{"f":"표의자의 진의와 표시가 불일치함을 상대방이 명확하게 인식하였더라도 그 불일치에 대하여 양자 간에 합의가 없으면 통정허위표시가 성립하지 않는다.","w":"통정허위표시는 표의자와 상대방이 진의 아닌 표시를 하기로 합의해야 성립한다. 상대방이 알기만 한 경우는 허위표시가 아니고 비진의표시의 문제가 된다.","c":"상","v":1},"공인노2022_31-56-4":{"f":"파산관재인이 통정허위표시와 관련하여 보호받는 제3자로 등장하는 경우, 파산채권자 중 일부라도 선의이면 그의 선의가 인정된다.","w":"파산관재인의 선의는 총파산채권자를 기준으로 판단한다. 파산채권자 중 한 명이라도 선의이면 파산관재인은 선의의 제3자로 본다.","c":"중","v":1},"공인노2022_31-57-3":{"f":"대리인이 수인(數人)인 때에는 법률 또는 수권행위에서 다른 정함이 없으면 각자 본인을 대리한다.","w":"대리인이 여러 명이면 각자대리가 원칙이다(제119조).","c":"상","v":1},"공인노2022_31-58-1":{"f":"대리행위가 강행법규에 위반하여 무효인 경우에는 표현대리가 성립할 수 없다.","w":"표현대리는 대리권이 있는 것으로 믿은 상대방을 보호하는 제도로, 대리행위 자체가 강행법규 위반으로 무효이면 표현대리 법리가 적용되지 않는다.","c":"상","v":1},"공인노2022_31-59-1":{"f":"반사회질서의 법률행위는 당사자가 그 무효를 알고 추인하더라도 유효가 되지 않는다.","w":"반사회질서 법률행위는 확정적 무효이므로 추인해도 유효가 되지 않는다.","c":"상","v":1},"공인노2022_31-59-2":{"f":"담보의 제공은 법정추인사유에 해당한다.","w":"담보 제공은 취소권자가 하든 상대방이 하든 법정추인사유다(제145조 제4호).","c":"상","v":1},"공인노2022_31-59-3":{"f":"무효행위의 추인은 무효원인이 소멸한 후에 할 수 있다.","w":"무효행위의 추인은 무효원인이 소멸한 뒤에 해야 한다. 원인이 남아 있는 동안에는 추인할 수 없다.","c":"상","v":1},"공인노2022_31-59-4":{"f":"피성년후견인은 제한능력 상태가 끝난 후에 취소할 수 있는 법률행위를 추인할 수 있다.","w":"제한능력자 본인의 추인은 취소 원인이 소멸한 뒤에야 할 수 있다(제144조 제1항). 법정대리인의 동의가 있다고 앞당겨지지 않는다.","c":"상","v":1},"공인노2022_31-61-1":{"f":"기한의 이익을 가지고 있는 채무자가 그가 부담하는 담보제공 의무를 이행하지 아니하면 그 기한의 이익은 상실된다.","w":"채무자가 담보제공의무를 이행하지 않으면 기한의 이익을 잃는다(제388조 제2호).","c":"상","v":1},"공인노2022_31-61-2":{"f":"해제조건 있는 법률행위는 조건이 성취한 때로부터 그 효력을 잃는다.","w":"해제조건부 법률행위는 조건이 성취된 때부터 효력이 소멸한다(제147조 제2항). 효력이 생기는 것이 아니라 없어지는 것이다.","c":"상","v":1},"공인노2022_31-61-3":{"f":"기성조건이 정지조건이면 그 법률행위는 조건 없는 법률행위로 한다.","w":"이미 성취된 조건이 정지조건이면 조건 없는 법률행위가 된다. 해제조건이면 무효다(제151조 제2항).","c":"상","v":1},"공인노2022_31-61-4":{"f":"기한이익 상실특약은 특별한 사정이 없는 한 형성권적 기한이익 상실특약으로 추정한다.","w":"기한이익 상실 사유가 생겨도 채권자의 청구나 통지가 있어야 기한의 이익이 상실되는 형성권적 특약으로 추정한다. 사유 발생과 동시에 당연히 상실되는 정지조건부 특약으로 보지 않는다.","c":"상","v":1},"공인노2024_33-04-2":{"f":"지명채권의 양도에 대한 채무자의 승낙은 채권양도 사실을 승인하는 의사를 표명하는 행위로 조건을 붙여서 할 수 있다.","w":"채무자는 채권양도를 승낙하면서 조건을 붙일 수 있다는 것이 판례다. 승낙은 양도 사실을 승인하는 의사를 밝히는 행위일 뿐이어서 조건을 붙이는 것이 막혀 있지 않다.","c":"중","v":1},"공인노2024_33-04-3":{"f":"부당이득반환채권과 같이 이행기의 정함이 없는 채권이 자동채권으로 상계될 때 상계적상에서 의미하는 변제기는 채권 성립 시에 도래한다.","w":"이행기의 정함이 없는 채권은 성립과 동시에 변제기가 도래한다. 상계 의사표시를 한 때가 아니라 채권이 성립한 때부터 상계적상이 될 수 있다.","c":"상","v":1},"공인노2024_33-04-4":{"f":"조건을 붙이고자 하는 의사는 법률행위의 내용으로 외부에 표시되어야 하지만 묵시적 의사표시나 묵시적 약정으로도 할 수 있다.","w":"조건의 의사가 외부에 표시되면 되고 그 방법이 명시적일 필요는 없다. 묵시적 의사표시로도 조건을 붙일 수 있다.","c":"상","v":1},"공인노2024_33-04-5":{"f":"당사자가 금전소비대차계약에 붙인 기한이익 상실특약은 특별한 사정이 없는 한 형성권적 기한이익 상실특약으로 추정한다.","w":"기한이익 상실 특약은 특별한 사정이 없으면 채권자의 의사표시가 있어야 상실되는 형성권적 특약으로 추정한다. 정지조건부 특약으로 추정하지 않는다.","c":"상","v":1},"공인노2024_33-08-2":{"f":"과실로 착오에 빠져 의사표시를 한 후 착오를 이유로 이를 취소한 자는 상대방에게 신뢰이익을 배상할 의무가 없다.","w":"착오 취소에는 신뢰이익 배상 규정이 없다. 표의자에게 경과실이 있어도 취소만으로 상대방에게 신뢰이익을 배상할 의무가 생기지 않는다.","c":"중","v":1},"공인노2024_33-08-3":{"f":"착오를 이유로 의사표시를 취소하려는 자의 착오가 중대한 과실로 인한 것임은 상대방이 증명하여야 한다.","w":"표의자의 중대한 과실은 취소를 막으려는 상대방이 증명한다.","c":"상","v":1},"공인노2024_33-08-4":{"f":"법률에 관해 경과실로 착오를 한 경우, 표의자는 그것이 법률행위의 중요부분에 관한 것이면 그 착오를 이유로 취소할 수 있다.","w":"법률의 착오도 법률행위 내용의 중요부분에 관한 것이면 중과실이 없는 한 취소할 수 있다.","c":"상","v":1},"공인노2024_33-08-5":{"f":"전문가의 진품감정서를 믿고 이를 첨부하여 서화 매매계약을 체결한 후에 그 서화가 위작임이 밝혀진 경우, 매수인은 하자담보책임을 묻는 외에 착오를 이유로 하여 매매계약을 취소할 수 있다.","w":"위작임을 모르고 산 매수인은 하자담보책임과 별개로 착오 취소를 선택할 수 있다.","c":"상","v":1},"공인노2024_33-09-4":{"f":"악의의 제3자로부터 전득한 선의의 제3자도 민법 제108조제2항의 선의의 제3자에 포함된다.","w":"선의의 제3자는 전득자 단계에서도 보호된다. 악의자로부터 취득했더라도 전득자가 선의이면 제108조 제2항에 따라 보호된다.","c":"상","v":1},"공인노2024_33-10-4":{"f":"계약당사자 일방의 대리인이 계약을 하면서 상대방을 기망한 경우, 본인이 그 사실을 몰랐거나 알 수 없었더라도 계약의 상대방은 그 기망을 이유로 의사표시를 취소할 수 있다.","w":"대리인은 제3자가 아니라 본인과 같은 지위에서 행위한다. 대리인의 기망은 본인의 선의와 관계없이 상대방이 취소할 수 있다.","c":"상","v":1},"공인노2024_33-11-1":{"f":"표현대리가 성립하는 경우에도 대리권 남용이 문제될 수 있다.","w":"표현대리가 성립해도 대리인이 자기나 제3자의 이익을 꾀한 사실을 상대방이 알았거나 알 수 있었다면 제107조 제1항 단서를 유추해 본인은 책임을 지지 않는다. 표현대리와 대리권 남용 법리는 함께 적용될 수 있다.","c":"중","v":1},"공인노2024_33-11-3":{"f":"사회통념상 대리권을 추단할 수 있는 직함의 사용을 묵인한 것만으로도 민법 제125조에서 말하는 대리권수여의 표시가 인정될 수 있다.","w":"대리권을 인정할 만한 직함을 사용하도록 묵인한 경우 대리권수여의 표시가 있었다고 볼 수 있다는 것이 판례다.","c":"상","v":1},"공인노2024_33-11-4":{"f":"소멸한 대리권의 범위를 벗어나서 대리행위가 행해진 경우에도 민법 제126조의 권한을 넘은 표현대리가 성립할 수 있다.","w":"소멸한 대리권을 기본대리권으로 보아 그 범위를 넘은 행위에 제129조와 제126조가 중첩해 성립할 수 있다.","c":"상","v":1},"공인노2024_33-11-5":{"f":"대리인이 대리권 소멸 후 복대리인을 선임한 경우, 그 복대리인의 대리행위에 대해서도 표현대리가 성립할 여지가 있다.","w":"대리권이 소멸한 뒤 선임된 복대리인의 행위에도 제129조의 표현대리가 성립할 수 있다.","c":"중","v":1},"공인노2025_34-02-4":{"f":"법정대리인의 동의 없이 매매계약을 체결한 미성년자가 그 동의 없음을 이유로 위 계약을 취소하는 것은 신의칙에 위배되지 않는다.","w":"미성년자의 취소권은 제한능력자 보호를 위한 권리이므로 이를 행사하는 것이 신의칙에 반하지 않는다.","c":"상","v":1},"공인노2025_34-03-3":{"f":"청산 중인 법인의 청산인은 채권신고기간 내에 채권자에 대한 변제를 할 수 없으나 법인은 그 기간 동안 채권자에 대한 지체책임을 면하지 못한다.","w":"채권신고기간 중 변제 금지는 청산인의 변제 행위에 대한 제한이다. 그 기간에도 변제기가 지난 채무의 지연손해금은 계속 발생한다(제90조).","c":"상","v":1},"공인노2025_34-04-1":{"f":"","w":"민법에는 이사회 소집권자에 관한 규정이 없고, 정관에 다른 규정이 없으면 법인의 사무집행은 이사 과반수로 결정한다(제58조 제2항). 이사 한 명이 혼자 이사회를 소집할 권한을 가진다고 볼 근거가 없다.","c":"하","v":1},"공인노2025_34-05-1":{"f":"건물의 개수는 공부상의 등록에 의하여 결정되지 않고, 소유자의 의사 등 주관적 사정을 참작하여 사회통념에 따라 결정된다.","w":"건물의 개수는 건축물대장 등의 공부상 표시에 얽매이지 않는다. 소유자의 의사와 이용 상황 등을 함께 고려해 사회통념으로 정한다.","c":"중","v":1},"공인노2025_34-05-2":{"f":"피상속인이 유언으로 자신의 유체(遺體)를 처분한 경우에도, 제사주재자는 이에 따라야 할 법적 의무를 부담하지 않는다.","w":"판례는 피상속인의 유체 처분 의사를 존중할 도의적 의무만 인정하고, 제사주재자가 그에 따라야 할 법적 의무는 없다고 본다(2008년 전원합의체).","c":"상","v":1},"공인노2025_34-05-3":{"f":"주물ㆍ종물 법리는 압류와 같은 공법상 처분에도 적용된다.","w":"주물에 대한 압류(경매)의 효력은 종물에도 미친다. 제100조 제2항은 압류 같은 공법상 처분에도 적용된다.","c":"상","v":1},"공인노2025_34-05-4":{"f":"주물ㆍ종물 법리는 권리 상호간에도 유추적용되지만 원본채권이 양도되더라도 이미 변제기에 도달한 이자채권은 원칙적으로 함께 양도되지 않는다.","w":"이미 변제기가 된 지분적 이자채권은 원본채권과 독립한 채권이다. 원본채권을 양도하면서 이자채권을 따로 양도하는 합의가 없으면 함께 넘어가지 않는다.","c":"중","v":1},"공인노2026_35-07-2":{"f":"특별한 사정이 없는 한 궁박은 본인을 기준으로 판단하고 경솔ㆍ무경험은 대리인을 기준으로 한다.","w":"대리인이 법률행위를 한 경우 궁박 상태는 본인 기준, 경솔과 무경험은 대리인 기준으로 판단한다.","c":"상","v":1},"공인노2026_35-07-3":{"f":"법률행위가 현저하게 공정을 잃은 경우에도 당사자의 궁박ㆍ경솔ㆍ무경험은 추정되지 않는다.","w":"급부 사이의 현저한 불균형만으로 궁박·경솔·무경험을 추정하지 않는다. 불공정한 법률행위를 주장하는 쪽이 이를 증명해야 한다.","c":"상","v":1},"공인노2026_35-07-4":{"f":"불공정한 법률행위에도 무효행위 전환의 법리가 적용될 수 있다.","w":"불공정한 법률행위에도 제138조의 무효행위 전환이 적용될 수 있다. 불균형이 큰 부분을 무효로 하고 상당한 범위에서 유효로 전환하는 경우다.","c":"중","v":1},"공인노2026_35-07-5":{"f":"매매계약이 불공정한 법률행위로 무효이면, 특별한 사정이 없는 한 그 매매계약에 관한 부제소합의도 무효이다.","w":"부제소합의도 불공정한 법률행위의 무효 범위에 들어가므로 계약이 무효이면 함께 무효다.","c":"상","v":1},"공인노2026_35-11-1":{"f":"사용자가 근로자의 기망을 이유로 근로계약을 적법하게 취소한 경우, 이미 제공된 근로자의 노무를 기초로 형성된 취소 이전의 법률관계는 그 효력을 잃지 않는다.","w":"근로계약은 계속적 계약이어서 취소의 효과를 소급시키지 않는다. 취소 이전에 이미 제공된 근로를 기초로 한 법률관계는 유효하다.","c":"상","v":1},"공인노2026_35-13-1":{"f":"선량한 풍속에 반하는 불법조건이 붙은 법률행위는 무효이다.","w":"불법조건이 붙은 법률행위는 조건만 무효인 것이 아니라 법률행위 전체가 무효다(제151조 제1항).","c":"상","v":1},"공인노2025_34-12-3":{"f":"현상광고에서 정한 행위의 완료에는 기한을 붙일 수 있다.","w":"현상광고에서 정한 행위를 완료할 기한도 광고에 정할 수 있다.","c":"중","v":1},"공인노2019_28-54-1":{"f":"국립공원의 입장료는 토지의 사용대가가 아니므로 민법상의 과실이 아니다.","w":"국립공원 입장료는 토지를 사용한 대가가 아니라 공원 관리·이용에 대한 요금이다. 법정과실로 보지 않는다.","c":"중","v":1},"공인노2019_28-54-3":{"f":"주물의 소유자 아닌 자의 물건은 원칙적으로 종물이 될 수 없다.","w":"종물은 주물과 같은 소유자의 물건이어야 한다(제100조 제1항). 다른 사람 소유의 물건은 종물이 되지 못한다.","c":"상","v":1},"공인노2019_28-54-4":{"f":"주유소 지하에 콘크리트를 타설하여 매설한 유류저장탱크는 토지의 종물이 아니다.","w":"지하에 매설해 토지에 부착된 유류저장탱크는 토지에 부합하여 토지의 구성부분이 되고, 독립한 종물이 아니다.","c":"상","v":1},"공인노2019_28-54-5":{"f":"수목의 집단이 관계법규에 따라 등기된 경우에는 토지소유권을 취득한 자라도 입목의 소유권을 취득하지 못한다.","w":"등기된 입목은 토지와 별개의 부동산으로 다루어진다. 토지 소유권을 취득해도 입목 소유권은 따라오지 않는다.","c":"상","v":1},"공인노2022_31-54-2":{"f":"타인의 토지에 권원 없이 자신의 수목을 식재한 자가 이를 부단히 관리하고 있더라도 그 수목은 토지에 부합한다.","w":"권원 없이 타인 토지에 심은 수목은 토지에 부합하여 토지 소유자의 소유가 된다. 심은 사람이 계속 관리해도 달라지지 않는다.","c":"상","v":1},"공인노2026_35-05-2":{"f":"토지의 정착물은 부동산이다.","w":"토지에 고정된 정착물은 동산이 아니라 부동산이다. 토지와 별개의 독립한 부동산이 되는 것은 건물이다.","c":"상","v":1},"공인노2017_26-55-1":{"f":"미성년후견인이 미성년자에게 특정한 영업을 허락한 경우, 미성년후견인의 대리권은 그 영업과 관련하여서는 소멸한다.","w":"법정대리인이 영업을 허락하면 미성년자는 그 영업에 관해 성년자와 같은 행위능력을 가지고, 그 범위에서 법정대리인의 대리권은 소멸한다.","c":"상","v":1},"공인노2017_26-55-3":{"f":"가정법원이 한정후견개시의 심판을 하는 경우 본인의 의사를 고려하여야 한다.","w":"한정후견개시 심판에서는 본인의 의사를 고려해야 한다(제12조 제2항).","c":"상","v":1},"공인노2017_26-55-4":{"f":"특정후견은 본인의 의사에 반하여서는 할 수 없다.","w":"특정후견의 심판은 본인의 의사에 반하여 할 수 없다(제14조의2 제2항).","c":"상","v":1},"공인노2017_26-55-5":{"f":"성년후견은 후견등기부에 공시된다.","w":"성년후견은 가족관계등록부가 아니라 후견등기부에 등기하여 공시한다.","c":"상","v":1},"공인노2019_28-52-4":{"f":"제한능력자의 취소권은 재판 외에서 의사표시를 하는 방법으로 행사할 수 있다.","w":"취소는 재판 없이 상대방에 대한 의사표시로 하는 형성권이다. 소송을 통해서만 행사하는 것이 아니다.","c":"상","v":1},"공인노2019_28-53-1":{"f":"성년의 남자뿐 아니라 여자도 종중의 구성원이 될 수 있다.","w":"대법원 전원합의체 판결(2005년) 이후 성별과 관계없이 공동선조의 후손인 성년이면 종중원이 된다.","c":"상","v":1},"공인노2019_28-53-2":{"f":"법인 아닌 사단의 대표가 총회 결의 없이 법인 아닌 사단의 이름으로 제3자의 금전채무를 보증한 경우, 특별한 사정이 없는 한 법인 아닌 사단은 보증채무를 부담한다.","w":"타인의 채무를 보증하는 행위는 총유물의 관리·처분행위가 아니어서 사원총회 결의가 필요하지 않다. 대표가 한 보증은 유효하다.","c":"상","v":1},"공인노2019_28-53-4":{"f":"법인 아닌 사단의 대표자의 직무상 불법행위에 대하여는 법인의 불법행위능력에 관한 민법 제35조제1항이 적용된다.","w":"비법인사단의 대표자가 직무에 관해 불법행위를 하면 제35조 제1항이 유추적용되어 사단이 배상책임을 진다.","c":"상","v":1},"공인노2019_28-53-5":{"f":"교인들이 집단적으로 교회를 탈퇴한 경우, 법인 아닌 사단인 교회는 분열되지 않고 기존 교회의 재산은 잔존 교인들의 총유로 귀속된다.","w":"판례는 교회의 분열을 인정하지 않는다. 탈퇴한 교인들은 교회 재산에 대한 권리를 잃고 남은 교인들이 총유로 보유한다.","c":"상","v":1},"공인노2022_31-52-4":{"f":"미성년자는 타인의 임의대리인이 될 수 있다.","w":"대리인은 행위능력자일 필요가 없다(제117조). 미성년자도 임의대리인이 될 수 있다.","c":"상","v":1},"공인노2022_31-53-1":{"f":"생전처분으로 재단법인을 설립하는 자가 서면으로 재산출연의 의사표시를 하였더라도 착오를 이유로 이를 취소할 수 있다.","w":"재단법인 설립을 위한 출연행위도 상대방 없는 단독행위로서 착오 취소 규정이 적용된다. 서면으로 했다는 사정만으로 취소가 막히지 않는다.","c":"상","v":1},"공인노2022_31-53-2":{"f":"생전처분으로 지명채권을 출연하여 재단법인을 설립하는 경우, 그 지명채권은 법인이 성립한 때 양도통지나 채무자의 승낙 없이도 법인의 재산이 된다.","w":"출연재산은 법인이 성립한 때부터 법인의 재산이 된다(제48조 제1항). 지명채권도 대항요건을 갖추어야만 귀속되는 것이 아니다.","c":"중","v":1},"공인노2022_31-53-4":{"f":"법인의 대표기관은 정관 또는 사원총회에 의해 금지되지 않는 한 특정한 행위에 한하여 타인에게 대리권을 수여할 수 있다.","w":"법인 대표기관이 정관이나 총회 결의로 금지되지 않은 특정 행위를 타인에게 대리시키는 것은 가능하지만, 포괄적인 대리권을 수여하는 것은 허용되지 않는다.","c":"상","v":1},"공인노2022_31-53-5":{"f":"법인이 청산종결등기를 하였더라도 실제로 청산사무가 종료되지 않았다면 그 법인은 소멸하지 않는다.","w":"법인은 청산종결등기가 아니라 청산사무가 실제로 끝나야 소멸한다. 사무가 남아 있으면 그 범위에서 법인은 존속한다.","c":"상","v":1},"공인노2024_33-01-4":{"f":"정관의 변경을 초래하는 재단법인의 기본재산 변경은 기존의 기본재산을 처분하는 행위뿐 아니라 새로이 기본재산으로 편입하는 행위도 포함한다.","w":"기본재산의 증가·편입도 정관 변경을 수반하므로 기본재산 변경에 포함된다. 처분만 해당하는 것이 아니다.","c":"상","v":1},"공인노2024_33-03-1":{"f":"甲이 외형상 직무에 관한 행위로 乙에게 손해를 가한 경우, 甲의 행위가 직무범위에 포함되지 아니함을 乙이 중대한 과실로 알지 못하였다면 A는 乙에게 손해배상책임을 지지 않는다.","w":"법인의 불법행위책임은 외형상 직무행위로 보이는 경우에 인정되지만, 피해자가 직무 범위 밖임을 알았거나 중대한 과실로 몰랐다면 법인은 책임을 지지 않는다.","c":"상","v":1},"공인노2024_33-06-1":{"f":"미성년자가 친권자의 동의를 얻어 법률행위를 한 후에는 친권자는 그 동의를 취소할 수 없다.","w":"법정대리인의 동의 취소는 미성년자가 법률행위를 하기 전에만 할 수 있다(제7조). 법률행위를 마친 뒤에는 취소할 수 없다.","c":"상","v":1},"공인노2024_33-06-3":{"f":"상대방이 계약 당시에 제한능력자와 계약을 체결하였음을 알았다면 제한능력자 측의 추인이 있을 때까지 자신의 의사표시를 철회할 수 없다.","w":"상대방의 철회권은 계약 당시 제한능력자임을 몰랐던 선의의 상대방에게만 있다(제16조 제1항 단서).","c":"상","v":1},"공인노2024_33-06-4":{"f":"피성년후견인이 속임수로써 상대방으로 하여금 성년후견인의 동의가 있는 것으로 믿게 하여 체결한 토지매매계약도 제한능력을 이유로 취소할 수 있다.","w":"피성년후견인의 법률행위는 성년후견인이 동의해도 취소할 수 있다. 그러니 동의가 있다고 믿게 했더라도 취소가 막히는 제17조 제2항의 적용 대상이 되지 않는다.","c":"중","v":1},"공인노2024_33-06-5":{"f":"법정대리인이 제한능력을 이유로 법률행위를 취소한 경우, 제한능력자의 부당이득 반환범위는 법정대리인의 선의 또는 악의와 관계없이 현존이익이다.","w":"제한능력자는 선의·악의를 가리지 않고 현존하는 이익의 한도에서만 반환한다(제141조 단서).","c":"상","v":1},"공인노2026_35-01-4":{"f":"사실인 관습은 당사자의 주장·증명이 있어야 하고 법원이 직권으로 확정하는 것이 아니다.","w":"관습법은 법원이 직권으로 확정하지만 사실인 관습은 그 존재를 당사자가 주장하고 증명해야 한다.","c":"상","v":1},"공인노2026_35-02-1":{"f":"실종선고를 받은 자는 실종기간이 만료한 때에 사망한 것으로 본다.","w":"실종선고를 받은 사람은 선고가 있은 때가 아니라 실종기간이 만료한 때에 사망한 것으로 본다(제28조).","c":"상","v":1},"공인노2026_35-02-2":{"f":"태아는 법정대리인을 통하여 사인증여를 받을 수 없다.","w":"태아는 상속·유증·불법행위 손해배상에서만 권리능력이 인정되고 증여를 받을 능력은 없다. 사인증여는 계약이라 법정대리인을 통한 수증도 인정되지 않는다.","c":"상","v":1},"공인노2026_35-02-4":{"f":"2인 이상이 동일한 위난으로 사망한 경우에는 동시에 사망한 것으로 추정한다.","w":"동시사망은 간주가 아니라 추정이다. 반증이 있으면 뒤집을 수 있다(제30조).","c":"상","v":1},"공인노2026_35-02-5":{"f":"반려동물은 위자료 청구권의 귀속주체가 될 수 없다.","w":"동물은 물건이어서 권리의 주체가 아니다. 위자료 청구권은 사람(소유자)에게 귀속된다.","c":"상","v":1},"공인노2026_35-03-2":{"f":"비법인사단의 구성원 개인은 사원총회의 결의를 거친 경우에도 단독으로 총유재산의 보존행위로서 소를 제기할 수 없다.","w":"총유재산에 관한 소송은 사단이 당사자가 되어 해야 한다. 구성원 개인이 보존행위라는 이유로 단독 소제기하는 것은 총회 결의가 있어도 허용되지 않는다.","c":"상","v":1},"공인노2026_35-04-1":{"f":"채권신고기간 동안 청산인이 채권자에게 변제하지 않더라도 법인은 지연손해에 대한 배상의무를 면하지 못한다.","w":"청산인이 채권신고기간 동안 변제하지 못해도 이행기가 지난 채무의 지연배상 책임은 사라지지 않는다(제90조).","c":"상","v":1},"공인노2019_28-62-3":{"f":"가처분은 소멸시효 중단사유 중의 하나이다.","w":"가압류·가처분은 제168조가 정한 시효 중단사유다. 정지사유가 아니다.","c":"상","v":1},"공인노2022_31-60-2":{"f":"월의 처음으로부터 기간을 기산하지 아니하는 때에는 최후의 월에서 그 기산일에 해당한 날의 전일로 기간이 만료한다.","w":"주·월·연의 처음부터 기산하지 않는 기간은 마지막 달에서 기산일에 해당하는 날의 전날로 끝난다(제160조 제2항).","c":"상","v":1},"공인노2022_31-62-3":{"f":"대항요건을 갖추지 못한 채권양도의 양수인이 채무자를 상대로 재판상 청구를 하면 시효중단사유인 재판상 청구에 해당한다.","w":"대항요건을 갖추지 못했더라도 양수인이 채무자에게 제기한 재판상 청구는 시효중단 사유가 된다.","c":"상","v":1},"공인노2024_33-05-2":{"f":"제척기간이 도과하였는지 여부는 법원이 직권으로 조사하여 고려할 수 있다.","w":"제척기간은 소멸시효와 달리 당사자의 원용 없이도 법원이 직권으로 조사한다.","c":"상","v":1},"공인노2025_34-13-4":{"f":"정년이 60세라 함은 60세가 만료되는 날이 아니라 60세에 도달하는 날을 말한다.","w":"판례는 정년 60세를 만 60세가 되는 날로 본다. 만 60세가 다 지나 61세가 되기 전날까지 근무할 수 있다는 뜻이 아니다.","c":"상","v":1},"공인노2025_34-14-1":{"f":"시효의 기산점과 관련하여 사실상 권리의 존재를 알지 못하였다는 것은 법률상 장애 사유에 해당하지 않는다.","w":"권리의 존재나 행사 가능성을 몰랐다는 사정은 사실상의 장애일 뿐 법률상 장애가 아니어서 소멸시효 진행을 막지 못한다.","c":"상","v":1},"공인노2025_34-14-3":{"f":"소멸시효는 법률행위에 의하여 배제할 수 없다.","w":"소멸시효는 법률행위로 배제·연장·가중할 수 없다(제184조 제2항). 단축·경감만 가능하다.","c":"상","v":1},"공인노2025_34-14-4":{"f":"부동산의 매수인이 그 부동산을 인도받아 계속 점유하는 경우에는 그 소유권이전등기 청구권의 소멸시효는 진행하지 않는다.","w":"매수인이 목적물을 인도받아 점유·사용하는 동안에는 권리 위에 잠자는 것이 아니므로 등기청구권의 소멸시효가 진행하지 않는다.","c":"상","v":1},"공인노2025_34-14-5":{"f":"법원은 제척기간의 경과 여부를 직권으로 조사할 수 있다.","w":"제척기간은 당사자의 주장이 없어도 법원이 직권으로 조사해 고려한다.","c":"상","v":1},"공인노2025_34-15-1":{"f":"형사소송에서 피해자가 신청하는 배상명령은 시효중단사유이다.","w":"배상명령 신청은 민사소송에서 소를 제기한 것과 같은 효력이 있어(소송촉진 등에 관한 특례법 제26조) 시효중단 사유가 된다.","c":"중","v":1},"공인노2025_34-15-2":{"f":"채권자가 전소(前訴)로 이행청구를 하여 승소 확정판결을 받은 경우, 시효중단을 위해 후소(後訴)로서 재판상의 청구가 있다는 점에 대하여만 확인을 구하는 소도 허용된다.","w":"전소 확정판결 후 시효만료가 임박하면 이행소송 외에 전소의 재판상 청구가 있었다는 점의 확인을 구하는 소도 소의 이익이 있어 허용된다는 것이 전원합의체 판례다.","c":"상","v":1},"공인노2025_34-15-3":{"f":"시효중단의 효력있는 승인에는 상대방의 권리에 관한 처분의 능력이나 권한을 요하지 않는다.","w":"승인은 관념의 통지라서 처분능력이나 권한이 필요 없고, 이행 가능한 관리능력이 있으면 된다.","c":"상","v":1},"공인노2025_34-15-5":{"f":"유체동산에 대한 가압류결정을 집행한 경우, 가압류에 의한 시효중단의 효력은 본압류가 되더라도 소멸하지 않고 계속된다.","w":"가압류가 본압류로 이전되어도 가압류에 의한 시효중단 효력은 소멸하지 않고 본압류 종료 때까지 이어진다.","c":"상","v":1},"공인노2026_35-14-1":{"f":"주채무자가 시효의 이익을 포기하더라도 특별한 사정이 없는 한 보증인에게는 그 포기의 효력이 미치지 않는다.","w":"시효이익의 포기는 상대적이어서 포기한 사람에게만 효력이 있다. 보증인은 주채무가 시효로 소멸했음을 주장할 수 있다.","c":"상","v":1},"공인노2017_26-63-2":{"f":"乙의 甲에 대한 상계의 의사표시가 2016. 7. 20. 도달하였더라도, 두 채권은 상계적상이 생긴 때로 소급하여 대등액의 범위 내에서 소멸한다.","w":"상계의 의사표시가 도달한 날이 아니라 상계할 수 있게 된 때(상계적상 시)로 소급해서 두 채권이 소멸한다(제493조 제2항).","c":"상","v":1},"공인노2022_31-68-2":{"f":"자동채권의 변제기는 도래하였으나 수동채권의 변제기가 도래하지 않은 경우에도 상계를 할 수 있다.","w":"수동채권의 기한 이익은 상계하는 사람이 포기할 수 있다. 자동채권의 변제기만 도래해 있으면 상계가 된다.","c":"상","v":1},"공인노2022_31-68-3":{"f":"채권자가 주채무자에 대하여 상계적상에 있는 자동채권을 상계하지 않는 경우에도, 보증 채무자는 이를 이유로 보증한 채무의 이행을 거부할 수 없다.","w":"보증인은 주채무자의 채권으로 상계하여 채권자에게 대항할 수 있을 뿐(제434조), 채권자가 상계하지 않았다는 사정만으로 보증채무의 이행을 거부할 수 있는 것은 아니다.","c":"중","v":1},"공인노2022_31-68-4":{"f":"채무자는 채권양도를 승낙한 후에 양도인에 대한 채권을 새로 취득한 경우에는 이를 가지고 양수인에 대하여 상계할 수 없다.","w":"승낙 당시 이미 가지고 있던 채권으로만 양수인에게 상계로 대항할 수 있다. 승낙 후에 새로 취득한 채권은 상계에 쓸 수 없다.","c":"상","v":1},"공인노2022_31-68-5":{"f":"벌금형이 확정된 경우, 그 벌금채권은 상계의 자동채권이 될 수 있다.","w":"벌금형이 확정되면 변제기가 도래한 채권이 되어 상계의 자동채권으로 쓸 수 있다.","c":"상","v":1},"공인노2024_33-25-5":{"f":"손해배상채무가 중과실에 의한 불법행위로 발생한 경우에도 그 채무자는 이를 수동채권으로 하는 상계로 채권자에게 대항할 수 있다.","w":"상계가 금지되는 것은 고의의 불법행위로 인한 손해배상채무다(제496조). 중과실은 고의가 아니므로 상계할 수 있다.","c":"상","v":1},"공인노2025_34-24-5":{"f":"손해배상채무가 중과실의 불법행위로 인한 것인 때에도 그 채무자는 상계로 채권자에게 대항할 수 있다.","w":"제496조는 고의의 불법행위로 인한 채무만 상계를 금지한다. 중과실은 해당하지 않는다.","c":"상","v":1},"공인노2025_34-25-1":{"f":"채무없음을 알고 임의로 변제한 경우, 변제자는 반환을 청구할 수 없다.","w":"채무가 없음을 알면서 변제한 것은 비채변제로서 반환을 청구하지 못한다(제742조).","c":"상","v":1},"공인노2025_34-25-2":{"f":"변제기 전에 변제한 채무자는 변제한 것의 반환을 청구하지 못한다.","w":"변제기 전에 한 변제는 반환을 청구할 수 없다(제743조). 착오로 한 경우에만 채권자가 이익을 반환한다.","c":"상","v":1},"공인노2025_34-25-3":{"f":"채무자가 변제 수령권한이 없는 자에게 변제를 한 경우, 이로 인하여 채권자가 받은 이익이 있으면 그 이익의 한도에서 변제의 효력이 있다.","w":"수령권한 없는 사람에게 한 변제는 원칙적으로 무효이나, 채권자가 이익을 받은 한도에서는 효력이 있다(제472조).","c":"상","v":1},"공인노2025_34-25-5":{"f":"변제금액이 채권액에 부족한 경우, 채무자는 이자에 앞서 원본에 충당할 것을 지정할 수 없다.","w":"변제가 채무 전부에 모자라면 비용·이자·원본 순서로 충당한다(제479조). 당사자가 합의하면 순서를 바꿀 수 있지만, 채무자 혼자 원본에 먼저 충당하라고 지정할 수는 없다.","c":"상","v":1},"공인노2026_35-26-5":{"f":"수인이 시기를 달리하여 피담보채권의 일부씩을 대위변제한 경우, 그 저당권의 실행으로 인한 매각대금의 배당에 있어 특별한 사정이 없는 한 변제 시기와 관계없이 변제금액에 비례하여 배당받는다.","w":"일부대위변제자들끼리는 변제 시기의 선후와 관계없이 각자의 변제 금액에 비례하여 평등하게 배당받는다. 먼저 변제했다고 우선하지 않는다.","c":"상","v":1},"공인노2026_35-27-1":{"f":"두 채권이 이행지를 달리 하는 경우에도 동종의 채권이라면 상계할 수 있다.","w":"이행지가 달라도 상계할 수 있다. 다만 상계하는 사람은 상대방이 입은 손해를 배상해야 한다(제494조).","c":"상","v":1},"공인노2026_35-32-2":{"f":"채무의 성질 또는 당사자의 별도의 정함이 없으면, 특정물의 인도는 채권성립 당시에 그 물건이 있던 장소에서 하여야 한다.","w":"특정물 인도는 채권 성립 당시 물건이 있던 장소에서 한다. 채권자의 현주소에서 하는 것은 그 밖의 채무의 경우다(제467조).","c":"상","v":1},"공인노2017_26-64-1":{"f":"사용자는 근로계약 불이행에 대한 위약금 또는 손해배상액을 예정하는 계약을 체결하지 못한다.","w":"근로기준법 제20조는 근로계약 불이행에 대한 위약금이나 손해배상액 예정을 금지한다.","c":"상","v":1},"공인노2017_26-64-2":{"f":"매매계약에서 채권자는 실제 손해액이 예정액을 초과하는 경우에도 그 초과액을 청구할 수 없다.","w":"손해배상액을 예정하면 실제 손해가 예정액보다 커도 초과분을 청구하지 못한다. 반대로 작아도 예정액을 청구할 수 있다.","c":"상","v":1},"공인노2017_26-64-3":{"f":"계약 내용에 손해배상액을 예정하는 약정이 있는 경우에는 계약상의 채무불이행으로 인한 손해액만 예정한 것이고 그 계약과 관련된 불법행위상의 손해액까지 예정한 것은 아니다.","w":"손해배상 예정은 채무불이행으로 인한 손해를 대상으로 한다. 불법행위로 생기는 손해까지 미리 정한 것으로 보지 않는다.","c":"상","v":1},"공인노2017_26-64-5":{"f":"금전채무에 관하여 이행지체에 대비한 지연손해금 비율을 따로 약정한 경우, 손해배상액의 예정으로서 감액의 대상이 된다.","w":"금전채무의 지연손해금 비율을 약정한 것은 손해배상액의 예정으로 보아 제398조 제2항에 따라 과다하면 감액할 수 있다.","c":"상","v":1},"공인노2017_26-66-1":{"f":"기한이 정해져 있는 지시채권이나 무기명채권의 경우에는 그 증서를 제시하지 않으면 이행기에 도달하더라도 지체책임을 지지 않는다.","w":"증서에 변제기한이 있어도 기한이 지난 뒤 소지인이 증서를 제시하여 이행을 청구한 때부터 채무자가 지체책임을 진다(제517조, 무기명채권은 제524조로 준용).","c":"상","v":1},"공인노2017_26-66-3":{"f":"부동산 이중매매의 경우, 제2매수인과 그 부동산에 관한 매매계약이 체결된 사실만으로는 이행불능이 아니고 제2매수인에게 소유권이전등기를 마친 때 이행불능이 된다.","w":"매매계약만으로는 아직 제1매수인에게 이전이 가능하다. 매도인이 제2매수인에게 소유권이전등기를 해 줌으로써 이행불능이 된다.","c":"상","v":1},"공인노2017_26-66-4":{"f":"부동산의 이중매매에서 매매목적물을 제2매수인에게 처분한 가격이 통상가격을 넘더라도 매도인의 제1매수인에 대한 배상액 산정의 기준은 이행불능 당시의 시가이다.","w":"통상손해는 이행불능 당시의 시가를 기준으로 한다. 매도인이 더 비싸게 팔았어도 그 처분가격이 기준이 되지는 않는다.","c":"중","v":1},"공인노2017_26-66-5":{"f":"아파트 광고모델계약을 체결하면서 품위유지약정을 한 유명 연예인이 남편과의 물리적 충돌로 멍들고 부은 얼굴 등을 언론에 공개한 행위는 채무불이행에 해당한다.","w":"품위유지약정을 한 광고모델이 자기 얼굴 상태를 언론에 공개해 광고 이미지를 해쳤다면 계약상 의무 위반으로 채무불이행이다.","c":"중","v":1},"공인노2019_28-63-5":{"f":"乙의 이행지체로 인하여 특별손해가 발생한 경우에도, 다른 특약이 없는 한 甲은 乙에게 특별손해에 대한 손해배상을 별도로 청구할 수 없다.","w":"손해배상액의 예정은 통상손해뿐 아니라 특별손해까지 포함해 정한 것으로 본다. 예정액 외에 따로 특별손해를 청구하지 못한다.","c":"상","v":1},"공인노2019_28-64-1":{"f":"과실상계의 비율에 대한 당사자의 주장은 법원을 구속하지 않는다.","w":"과실상계는 법원이 재량으로 정하는 사항이다. 당사자가 주장하는 과실 비율에 법원이 구속되지 않는다.","c":"상","v":1},"공인노2019_28-64-2":{"f":"배상의무자가 피해자의 과실에 관하여 주장하지 않는 경우에도 법원이 이를 직권으로 심리·판단할 수 있다.","w":"과실상계는 배상의무자가 주장하지 않아도 법원이 직권으로 피해자 과실을 심리·판단해야 한다(제396조, 불법행위는 제763조로 준용).","c":"상","v":1},"공인노2019_28-64-4":{"f":"채무내용에 따른 본래의 급부의 이행을 구하는 경우에는 과실상계가 적용되지 않는다.","w":"과실상계는 손해배상에 적용된다. 본래의 급부 이행을 청구하는 경우에는 채권자 과실을 이유로 줄일 수 없다.","c":"상","v":1},"공인노2019_28-64-5":{"f":"채무불이행에 관하여 채권자의 과실이 있고 채권자가 그로 인하여 이익을 받은 경우, 손해배상액을 산정함에 있어서 과실상계를 한 다음 손익상계를 해야 한다.","w":"먼저 손해액에서 과실상계를 한 뒤 남은 금액에서 이익을 공제하는 손익상계를 한다.","c":"상","v":1},"공인노2022_31-63-1":{"f":"선택채권의 경우, 특별한 사정이 없는 한 선택의 효력은 소급한다.","w":"선택은 채권이 발생한 때로 소급하여 효력이 있다. 다만 제3자의 권리를 해치지 못한다(제386조).","c":"상","v":1},"공인노2024_33-16-1":{"f":"채무불이행으로 인한 손해배상액이 예정되어 있는 경우, 채권자는 채무불이행 사실만 증명하면 예정배상액을 청구할 수 있고 손해의 발생 사실은 증명할 필요가 없다.","w":"손해배상액을 예정하면 손해의 발생과 액수는 증명하지 않아도 된다. 채무불이행 사실만 증명하면 예정액을 청구할 수 있다.","c":"상","v":1},"공인노2024_33-16-2":{"f":"특별한 사정으로 인한 손해배상에서 채무자가 그 사정을 알았거나 알 수 있었는지의 여부는 채무불이행 당시를 기준으로 판단한다.","w":"특별손해의 예견 가능성은 계약을 체결한 때가 아니라 채무를 불이행한 때를 기준으로 판단한다.","c":"상","v":1},"공인노2024_33-16-3":{"f":"부동산소유권이전채무가 이행불능이 되어 채권자가 채무자에게 갖게 되는 손해배상채권의 소멸시효는 이행불능이 된 때부터 진행된다.","w":"손해배상채권은 본래 채권의 연장이므로 채무가 이행불능이 된 때부터 시효가 진행한다. 계약체결시가 아니다.","c":"상","v":1},"공인노2024_33-16-5":{"f":"불법행위로 영업용 건물이 일부 멸실된 경우, 그에 따른 휴업손해는 통상손해에 해당한다.","w":"건물이 일부 멸실되어 영업을 쉬게 되면 휴업으로 인한 손해가 통상 생기는 손해이므로 통상손해로 본다.","c":"중","v":1},"공인노2024_33-18-1":{"f":"이행지체를 이유로 채권자에게 전보배상청구가 인정되는 경우, 그 손해액은 원칙적으로 본래의 급부를 최고한 상당한 기간이 경과한 시점의 시가를 기준으로 산정하여야 한다.","w":"전보배상의 기준 시점은 최고 당시가 아니라, 최고하여 정한 상당한 기간이 지나 전보배상을 청구할 수 있게 된 때다.","c":"중","v":1},"공인노2025_34-16-3":{"f":"외화채권에서 채무자는 우리나라 통화로 변제할 수 있고 그 환산시기는 이행기가 아니라 현실 지급시이다.","w":"외화채권을 원화로 변제할 때의 환산은 현실로 이행하는 때의 외국환 시세로 한다(제378조).","c":"상","v":1},"공인노2025_34-17-2":{"f":"반환시기의 약정이 없는 소비대차의 경우, 대주가 상당한 기간을 정하여 반환을 최고하고 그 기간이 지난 때부터 이행지체가 된다.","w":"반환시기를 정하지 않은 소비대차는 대주가 상당한 기간을 정해 최고해야 하고 그 기간이 지나야 차주가 지체에 빠진다(제603조 제2항).","c":"상","v":1},"공인노2025_34-17-3":{"f":"은행의 양도성예금증서에 변제기한이 있는 경우, 은행은 그 증서가 제시된 때부터 지체책임을 진다.","w":"양도성예금증서는 증서채권이어서 기한이 지난 뒤 증서를 제시하여 청구한 때부터 지체책임이 생긴다.","c":"상","v":1},"공인노2025_34-17-4":{"f":"채무이행의 불확정한 기한이 있는 경우, 채무자는 그 기한이 도래함을 안 때부터 지체책임을 진다.","w":"불확정기한부 채무는 기한이 객관적으로 도래한 때가 아니라 채무자가 도래를 안 때부터 지체책임을 진다(제387조 제1항 후문).","c":"중","v":1},"공인노2025_34-17-5":{"f":"불법행위로 인한 손해배상책임은 인정되지만 그 배상액이 확정되지 않은 경우에도, 채무자는 불법행위 시부터 지체책임을 진다.","w":"불법행위로 인한 손해배상채무는 불법행위가 성립한 때부터 지체에 빠진다. 배상액이 확정되지 않았다는 이유로 지체책임을 면하지 못한다.","c":"상","v":1},"공인노2025_34-18-4":{"f":"위약벌 약정액이 부당히 과다한 경우, 손해배상액의 예정에 관한 민법 제398조 제2항을 유추적용하여 그 액을 감액할 수 없다.","w":"위약벌은 손해배상 예정이 아니어서 제398조 제2항을 유추해 감액할 수 없다. 과도하면 공서양속 위반으로 무효가 될 수 있을 뿐이다.","c":"상","v":1},"공인노2026_35-16-4":{"f":"이행보조자의 행위가 채무의 이행에 관련된 경우, 그 행위가 채권자에게 불법행위가 되는 때에도 채무자의 채무불이행책임은 면책되지 않는다.","w":"채무자는 이행보조자의 고의·과실을 자기의 것으로 책임진다(제391조). 불법행위가 성립해도 채무불이행책임이 면제되지 않는다.","c":"상","v":1},"공인노2026_35-17-2":{"f":"매도인의 귀책사유로 인하여 매매목적물에 대하여 매도인의 다른 채권자가 강제경매를 신청하여 그 절차가 진행 중인 경우에도 매도인의 소유권이전의무는 이행불능이 되지 않는다.","w":"경매절차가 진행 중이라는 것만으로는 이행불능이 아니다. 경락으로 소유권을 잃은 때에 비로소 이행불능이 된다.","c":"상","v":1},"공인노2026_35-18-5":{"f":"매도인의 소유권이전의무가 이행불능이 된 후 목적물의 가격이 오른 경우, 가격 상승으로 인한 손해는 특별손해에 해당한다.","w":"이행불능 후의 가격 상승은 통상손해가 아니라 특별손해다. 채무자가 그 사정을 알았거나 알 수 있었을 때 배상한다.","c":"상","v":1},"공인노2026_35-24-5":{"f":"금전채무의 이행지체로 인하여 발생하는 지연손해금은 그 성질이 손해배상금이다.","w":"금전채무의 지연손해금은 이자가 아니라 손해배상금이다.","c":"상","v":1},"공인노2017_26-67-1":{"f":"채권자대위권 행사에는 채무자의 무자력이 요구되지 않는 경우가 있어, 소유권이전등기청구권과 같은 특정채권도 피보전채권이 될 수 있다.","w":"금전채권이 아닌 특정채권을 보전하는 대위권은 채무자의 무자력을 요건으로 하지 않는다. 소유권이전등기청구권도 피보전채권이 된다.","c":"상","v":1},"공인노2017_26-67-3":{"f":"채무자의 채권자대위권뿐 아니라 채무자의 채권자취소권도 대위할 수 있다.","w":"판례는 채권자가 채무자의 채권자취소권도 대위행사할 수 있다고 본다.","c":"중","v":1},"공인노2017_26-67-4":{"f":"조합원의 조합탈퇴권은 일신전속적 권리가 아니므로 대위의 대상이 될 수 있다.","w":"조합탈퇴권은 재산적 성격이 강해 일신전속권이 아니다. 채권자가 대위해서 행사할 수 있다.","c":"중","v":1},"공인노2017_26-67-5":{"f":"피보전채권이 금전채권인 경우, 대위채권자는 채무자의 금전채권을 자신에게 직접 이행하도록 청구할 수 있다.","w":"금전채권이나 동산 인도채권처럼 수령이 필요한 경우 대위채권자가 제3채무자에게 자기에게 직접 이행하라고 청구할 수 있다.","c":"상","v":1},"공인노2017_26-69-1":{"f":"채권자취소권은 재판상으로만 행사할 수 있다.","w":"채권자취소권은 반드시 소(訴)로써 행사해야 한다(제406조). 재판 외 의사표시로는 행사할 수 없다.","c":"상","v":1},"공인노2017_26-69-2":{"f":"특정물에 대한 소유권이전등기청구권과 같은 특정채권은 원칙적으로 채권자취소권의 피보전채권이 될 수 없다.","w":"채권자취소권은 일반 채권자의 공동담보 보전을 위한 제도다. 특정물을 목적으로 하는 채권은 원칙적으로 피보전채권이 되지 못한다.","c":"상","v":1},"공인노2017_26-69-4":{"f":"상속재산의 분할협의도 채권자취소권의 대상이 될 수 있다.","w":"상속재산 분할협의는 재산권을 목적으로 한 법률행위이므로 사해행위에 해당하면 채권자취소권의 대상이 된다.","c":"상","v":1},"공인노2017_26-69-5":{"f":"수인의 채권자 중 일부가 제기한 채권자취소권 행사의 효력은 모든 채권자의 이익을 위하여 미친다.","w":"취소와 원상회복의 효력은 모든 채권자의 이익을 위하여 생긴다(제407조). 소송을 한 채권자에게만 귀속하지 않는다.","c":"상","v":1},"공인노2019_28-65-3":{"f":"채권자대위소송에서 甲의 乙에 대한 채권이 존재하는지 여부는 법원의 직권조사사항이다.","w":"피보전채권의 존재는 대위권의 요건이라서 당사자가 다투지 않아도 법원이 직권으로 조사한다.","c":"상","v":1},"공인노2019_28-66-1":{"f":"채권자가 사해행위 취소소송을 통해 원상회복만을 구하는 경우에도 법원은 가액배상을 명할 수 있다.","w":"채권자가 원상회복만 구해도 그 청구에는 원물반환 대신 가액배상을 구하는 취지가 들어 있다고 보아 법원은 가액배상을 명할 수 있다는 것이 판례다.","c":"중","v":1},"공인노2022_31-65-3":{"f":"민법상 조합원의 조합탈퇴권은 특별한 사정이 없는 한 채권자대위권의 목적이 될 수 있다.","w":"조합탈퇴권은 일신전속권이 아니라 재산권적 성격이 있어 채권자대위권의 목적이 될 수 있다.","c":"중","v":1},"공인노2025_34-19-1":{"f":"정지조건부 채권도 특별한 사정이 없는 한 채권자취소권의 피보전채권이 될 수 있다.","w":"사해행위 당시 정지조건의 성취 가능성이 높은 채권은 피보전채권이 된다.","c":"중","v":1},"공인노2025_34-19-3":{"f":"채무자가 소멸시효 완성 후에 한 소멸시효이익의 포기행위도 채권자취소권의 대상인 사해행위가 될 수 있다.","w":"시효 완성 후의 시효이익 포기는 재산권을 줄이는 법률행위라서 사해행위로서 취소할 수 있다는 것이 판례다.","c":"중","v":1},"공인노2025_34-19-4":{"f":"채권자가 전득자를 상대로 사해행위취소의 소를 제기한 경우, 그 취소의 대상은 채무자와 수익자 사이의 법률행위이다.","w":"전득자를 상대로 하더라도 취소할 대상은 채무자와 수익자 사이의 법률행위이다. 수익자와 전득자 사이의 행위가 아니다.","c":"상","v":1},"공인노2025_34-19-5":{"f":"사해행위 이후에 성립한 채권의 채권자는 사해행위취소와 원상회복의 효력을 받는 채권자에 포함되지 않는다.","w":"사해행위 이후에 생긴 채권의 채권자는 피보전채권자가 될 수 없어 취소와 원상회복의 효력을 받는 채권자에 들어가지 않는다.","c":"중","v":1},"공인노2026_35-20-1":{"f":"물권적 청구권에 대하여도 채권자대위권에 관한 민법 제404조의 규정과 법리가 적용될 수 있다.","w":"물권적 청구권은 채권자대위권의 목적이 될 수 있고, 피보전권리가 될 수도 있다.","c":"상","v":1},"공인노2026_35-20-2":{"f":"임대인의 동의없이 임차권을 양도한 경우, 특별한 사정이 없는 한 양수인은 자기의 채권을 보전하기 위하여 임대인의 권리를 대위행사할 수 없다.","w":"임차인에게는 임대인에게 임차권 양도에 동의하라고 청구할 권리가 없다. 그러니 양수인이 이를 대위행사할 수도 없다.","c":"중","v":1},"공인노2026_35-20-3":{"f":"임대인의 임대차계약 해지권은 일신전속권이 아니므로 대위행사할 수 있다.","w":"해지권은 재산권에 관한 형성권이라 일신전속권으로 보지 않고 대위행사의 대상이 된다.","c":"중","v":1},"공인노2026_35-20-5":{"f":"민법상 조합원의 조합탈퇴권은 일신전속권이 아니므로 특별한 사정이 없는 한 대위행사할 수 있다.","w":"조합탈퇴권은 재산적 성격을 가진 권리로 일신전속권이 아니어서 채권자가 대위행사할 수 있다.","c":"중","v":1},"공인노2026_35-21-1":{"f":"채권이 사해행위 이전에 성립하였다면 그 채권이 사해행위 이후 양도된 경우에도 양수인은 채권자취소권을 행사할 수 있다.","w":"사해행위 이전에 성립한 채권이면 양수인도 피보전채권자의 지위를 승계하여 채권자취소권을 행사할 수 있다.","c":"상","v":1},"공인노2026_35-21-2":{"f":"사해행위취소소송에서 채권자는 채무자의 악의를 증명하여야 하지만, 수익자의 악의는 추정되므로 수익자가 자신의 선의를 증명할 책임을 부담한다.","w":"채무자의 사해의사는 채권자가 증명해야 한다. 수익자의 악의는 추정되어 수익자가 자기가 선의였음을 증명해야 한다(제406조 제1항 단서).","c":"상","v":1},"공인노2026_35-21-3":{"f":"채권자취소의 소는 채권자가 취소원인을 안 날부터 1년 내에 제기하여야 한다.","w":"취소원인을 안 날부터 1년, 법률행위가 있은 날부터 5년 안에 소를 제기해야 한다(제406조 제2항).","c":"상","v":1},"공인노2026_35-21-5":{"f":"채무자가 채권자에게 채무의 본지에 따른 변제를 하는 것은 특별한 사정이 없는 한 사해행위가 되지 않는다.","w":"채무의 본지에 따른 변제는 채무 이행에 불과하여 원칙적으로 사해행위가 되지 않는다. 변제를 받은 채권자가 다른 채권자보다 먼저 받아 간 것을 이유로 취소할 수 없다.","c":"상","v":1},"공인노2017_26-70-1":{"f":"丙이 모르는 사이에 주채무의 목적이나 형태가 변경되어 주채무의 실질적 동일성이 상실된 경우에는 丙의 보증채무는 소멸한다.","w":"주채무의 동일성이 없어지면 보증인은 새 채무까지 보증하기로 한 적이 없으므로 보증채무가 소멸한다.","c":"상","v":1},"공인노2017_26-70-3":{"f":"丙은 甲이 가지는 항변으로 乙에게 대항할 수 있고, 甲이 이를 포기하였더라도 丙은 그 항변으로 乙에게 대항할 수 있다.","w":"보증인은 주채무자의 항변으로 채권자에게 대항할 수 있고, 주채무자가 항변을 포기해도 보증인에게는 영향이 없다(제433조).","c":"상","v":1},"공인노2017_26-70-4":{"f":"甲의 乙에 대한 채무가 시효로 소멸되면 丙의 보증채무도 부종성에 따라 소멸한다.","w":"주채무가 소멸하면 보증채무도 소멸한다. 주채무의 시효소멸도 보증인이 원용할 수 있다.","c":"상","v":1},"공인노2019_28-67-4":{"f":"매매로 인한 소유권이전등기청구권에 관한 양도제한의 법리는 취득시효완성으로 인한 소유권이전등기청구권의 양도에는 적용되지 않는다.","w":"취득시효 완성에 따른 등기청구권은 당사자 사이의 신뢰관계에 기초한 채권이 아니어서 매매의 경우와 달리 양도에 채무자 동의가 필요하지 않다.","c":"중","v":1},"공인노2019_28-68-1":{"f":"채권자와 인수인의 계약에 의한 중첩적 채무인수는 채무자의 의사에 반하여 할 수 있다.","w":"채권자와 인수인의 합의로 하는 중첩적 채무인수는 채무자의 의사에 반하더라도 할 수 있다.","c":"상","v":1},"공인노2019_28-68-2":{"f":"채무자와 인수인의 계약에 의한 면책적 채무인수는 채권자의 승낙이 없으면 효력이 없다.","w":"면책적 채무인수는 채권자의 승낙이 있어야 효력이 생긴다(제454조).","c":"상","v":1},"공인노2019_28-68-4":{"f":"채무인수가 면책적 인수인지, 중첩적 인수인지 분명하지 않은 때에는 이를 중첩적 채무인수로 본다.","w":"채무자를 면책시키는 것은 채권자에게 불리하므로 분명하지 않으면 채무자가 계속 채무를 지는 중첩적 인수로 본다.","c":"상","v":1},"공인노2019_28-68-5":{"f":"부동산 매수인이 매매목적물에 설정된 저당권의 피담보채무를 인수하는 한편 그 채무액을 매매대금에서 공제하기로 약정한 경우, 특별한 사정이 없는 한 이는 매도인을 면책시키는 채무인수가 아니라 이행인수로 본다.","w":"채권자의 승낙이 없는 한 매도인(채무자)이 면책되지 않는다. 매수인이 채무자에게 이행할 의무를 지는 이행인수로 본다.","c":"상","v":1},"공인노2022_31-64-1":{"f":"甲의 A에 대한 위 채무가 시효완성으로 소멸한 경우, 乙은 甲의 부담부분 한도에서만 A에 대한 의무를 면한다.","w":"연대채무자 1인에 대한 시효완성은 그 채무자의 부담부분 한도에서만 다른 연대채무자에게 이익이 된다(제421조).","c":"상","v":1},"공인노2022_31-64-2":{"f":"甲이 A에게 2억 원의 상계할 채권을 가지고 있음에도 상계를 하지 않는 경우, 乙은 甲의 부담부분 한도에서만 그 채권으로 상계할 수 있다.","w":"채권이 있는 연대채무자가 상계하지 않으면 다른 연대채무자는 그 채무자의 부담부분 한도에서만 상계할 수 있다(제418조 제2항).","c":"상","v":1},"공인노2022_31-64-4":{"f":"A의 신청에 의한 경매개시결정에 따라 甲소유의 부동산이 압류되어 시효가 중단된 경우, 乙에게는 시효중단의 효력이 없다.","w":"연대채무에서 이행청구 이외의 시효중단 사유는 다른 연대채무자에게 효력이 없다. 압류는 압류당한 채무자에게만 시효중단 효력이 있다.","c":"상","v":1},"공인노2022_31-64-5":{"f":"A가 甲에 대하여 위 채무를 전부 면제해 준 경우, 乙은 甲의 부담부분 한도에서만 A에 대한 의무를 면한다.","w":"면제의 절대적 효력은 면제받은 연대채무자의 부담부분 한도에서만 생긴다(제419조).","c":"상","v":1},"공인노2022_31-66-2":{"f":"채무자와 인수인 사이의 계약에 의한 면책적 채무인수는 채권자의 승낙이 없으면 효력이 없다.","w":"면책적 채무인수는 채권자의 승낙이 필요하다(제454조).","c":"상","v":1},"공인노2024_33-23-3":{"f":"채권양도가 다른 채무의 담보조로 이루어진 후 그 피담보채무가 변제로 소멸된 경우에도, 양도채권의 채무자는 이를 이유로 채권양수인의 양수금 지급청구를 거절할 수 없다.","w":"양도담보 관계는 양도인과 양수인 사이의 일이다. 피담보채무가 소멸했다는 사정만으로 채권의 채무자가 양수인에 대한 지급을 거절하지 못한다.","c":"중","v":1},"공인노2024_33-24-1":{"f":"乙과 丙 사이의 합의에 의한 면책적 채무인수가 성립하는 경우, 甲이 乙 또는 丙을 상대로 승낙을 하지 않으면 그 채무인수의 효력은 발생하지 않는다.","w":"채무자와 인수인의 합의에 의한 면책적 채무인수는 채권자의 승낙이 있어야 효력이 생긴다.","c":"상","v":1},"공인노2024_33-24-3":{"f":"乙의 의사에 반하여 이루어진 甲과 丙 사이의 합의에 의한 중첩적 채무인수도 유효하다.","w":"채권자와 인수인이 합의한 중첩적 채무인수는 채무자의 의사에 반해도 유효하다.","c":"상","v":1},"공인노2024_33-24-4":{"f":"乙과 丙 사이의 합의에 의한 채무인수가 면책적 인수인지, 중첩적 인수인지 분명하지 않은 때에는 이를 중첩적 채무인수로 본다.","w":"분명하지 않으면 채권자에게 유리한 중첩적 채무인수로 본다.","c":"상","v":1},"공인노2024_33-24-5":{"f":"乙의 부탁을 받은 丙이 甲과 합의하여 중첩적 채무인수 계약을 체결한 경우, 특별한 사정이 없는 한 乙과 丙은 연대채무관계에 있다.","w":"채무자의 부탁을 받고 인수한 중첩적 채무인수는 원칙적으로 연대채무가 된다. 채무자의 부탁 없이 한 경우에는 부진정연대채무가 된다.","c":"중","v":1},"공인노2025_34-21-2":{"f":"보증채무의 소멸시효기간은 주채무와 별개로 보증채무 자체의 성질에 따라 정해진다.","w":"보증채무는 주채무와 독립된 별개의 채무다. 소멸시효기간도 주채무가 아니라 보증채무 자체를 기준으로 정한다.","c":"상","v":1},"공인노2025_34-21-3":{"f":"주채무자의 의사에 반하여 보증인이 된 자가 변제로 주채무를 소멸하게 한 때에는 주채무자는 현재 이익이 있는 한도에서 배상하여야 한다.","w":"주채무자의 의사에 반하여 보증인이 된 사람의 구상은 현존이익 한도다(제444조 제2항). 변제 당시 받은 이익이 기준인 것은 주채무자의 부탁 없이 보증인이 된 경우다(제444조 제1항).","c":"상","v":1},"공인노2025_34-21-4":{"f":"보증의 효력발생요건인 보증인의 기명날인은 타인이 이를 대행하는 방법으로 할 수 있다.","w":"보증인의 기명날인은 타인이 대행하여도 된다. 보증인 본인이 직접 해야 하는 것은 아니다.","c":"상","v":1},"공인노2025_34-21-5":{"f":"보증채무의 연체이율은 특별한 약정이 없으면 주채무의 약정연체이율이 아니라 법정이율을 따르는 것이 원칙이다.","w":"보증채무는 주채무와 별개의 채무여서, 보증채무 연체이율을 따로 약정하지 않았다면 법정이율에 따른다. 주채무에 약정한 연체이율이 당연히 적용되지 않는다는 것이 판례다.","c":"중","v":1},"공인노2025_34-22-1":{"f":"보증채권을 주채권과 함께 양도하는 경우, 대항요건은 주채권에 대하여 구비하면 보증채권에도 효력이 미친다.","w":"보증채권은 주채권에 따르는 종된 권리여서 주채권에 대하여 대항요건을 갖추면 보증채권에도 효력이 미친다.","c":"상","v":1},"공인노2025_34-22-2":{"f":"대항요건을 갖추지 못한 채권양도인은 채무자의 제3채무자에 대한 채권에 관하여 가압류를 할 수 있다.","w":"대항요건을 갖추지 못한 동안에는 채무자에 대한 관계에서 양도인이 여전히 채권자이므로 가압류를 할 수 있다.","c":"중","v":1},"공인노2025_34-22-4":{"f":"임대차계약상 임차권양도금지 특약이 있는 경우라도 임대보증금 반환채권의 양도까지 금지하는 것으로 볼 수는 없다.","w":"임차권양도 금지 특약은 임차권을 대상으로 한다. 보증금 반환채권의 양도금지까지 포함하는 것으로 해석하지 않는다.","c":"상","v":1},"공인노2025_34-22-5":{"f":"양도금지특약부 채권을 전부받은 자로부터 다시 그 채권을 양수한 자가 특약에 대하여 악의이더라도, 채무자는 특약을 근거로 채권양도의 무효를 주장할 수 없다.","w":"양도금지특약이 있는 채권도 전부명령으로는 유효하게 이전된다. 그 전부채권자로부터 다시 채권을 양수한 사람은 특약을 알았더라도 채권을 유효하게 취득한다는 것이 판례다.","c":"상","v":1},"공인노2025_34-23-2":{"f":"채무자와 인수인의 계약에 의한 채무인수의 경우, 채권자의 승낙은 채무인수계약의 효력발생 요건이다.","w":"면책적 채무인수에서 채권자의 승낙은 계약의 효력을 발생시키는 요건이다.","c":"상","v":1},"공인노2026_35-22-4":{"f":"어느 연대채무자가 채무를 승인하여 그에 대한 시효가 중단된 경우에도 다른 연대채무자에게는 시효중단의 효력이 발생하지 않는다.","w":"연대채무에서 이행청구를 제외한 시효중단 사유는 상대적 효력만 있다. 승인으로 중단된 효력은 그 채무자에게만 미친다.","c":"상","v":1},"공인노2026_35-23-3":{"f":"가압류된 채권도 처분이 금지되는 것은 아니어서 이를 양도할 수 있다.","w":"가압류는 채무자의 처분을 절대적으로 금지하지 않는다. 양도는 가능하지만 양수인은 가압류의 제한을 그대로 부담한다.","c":"상","v":1},"공인노2019_28-70-5":{"f":"계약해제에 따른 원상회복으로 매매대금의 반환을 구하는 경우, 해제자가 해제원인의 일부를 제공하였더라도 과실상계가 적용되지 않는다.","w":"해제에 따른 원상회복은 손해배상이 아니라 계약이 없었던 상태로 돌아가는 것이어서 과실상계의 대상이 아니다.","c":"상","v":1},"공인노2022_31-69-4":{"f":"승낙자가 승낙기간을 도과한 후 승낙을 발송한 경우에는 청약자가 승낙의 연착을 통지하지 아니하여도 계약은 성립하지 않고, 청약자는 그 승낙을 새 청약으로 볼 수 있다.","w":"연착 통지를 하지 않으면 연착되지 않은 것으로 보는 규정(제528조 제2항·제3항)은 보통이면 기간 안에 도달할 수 있게 발송한 승낙에만 적용된다. 기간이 지난 뒤 발송한 승낙은 청약자가 새 청약으로 볼 수 있을 뿐이다(제530조).","c":"상","v":1},"공인노2022_31-70-1":{"f":"채무자와 인수인 사이에 체결되는 중첩적 채무인수계약은 제3자를 위한 계약이다.","w":"채무자와 인수인이 채권자(제3자)에게 채권을 취득시키기로 하는 중첩적 채무인수는 제3자를 위한 계약이다.","c":"상","v":1},"공인노2022_31-70-3":{"f":"요약자와 낙약자의 합의에 따라 제3자의 권리를 소멸시킬 수 있음을 미리 유보하였다면, 제3자에게 그 권리가 확정적으로 귀속된 후에도 요약자와 낙약자는 제3자의 권리를 소멸시킬 수 있다.","w":"제3자의 권리가 확정된 뒤에는 변경·소멸이 안 되는 것이 원칙이지만(제541조), 계약 당시 이를 미리 유보했다면 소멸시킬 수 있다.","c":"상","v":1},"공인노2022_31-70-4":{"f":"제3자가 수익의 의사표시를 한 후에는 요약자는 낙약자에 대하여 제3자에게 급부를 이행할 것을 요구할 수 있는 권리를 갖는다.","w":"요약자도 낙약자에게 제3자에게 급부하라고 청구할 권리가 있다. 제3자의 수익 의사표시로 이 권리가 없어지지 않는다.","c":"상","v":1},"공인노2022_31-70-5":{"f":"제3자가 수익의 의사표시를 한 경우에도, 특별한 사정이 없는 한 요약자는 낙약자의 채무불이행을 이유로 제3자의 동의 없이 계약을 해제할 수 있다.","w":"요약자는 계약 당사자이므로 낙약자의 채무불이행을 이유로 제3자의 동의 없이 계약을 해제할 수 있다는 것이 판례다.","c":"상","v":1},"공인노2024_33-26-1":{"f":"민법은 청약의 구속력에 관한 규정에서 철회할 수 있는 예외를 규정하고 있지 않다.","w":"청약은 승낙기간을 정했거나 상당한 기간이 지나기 전에는 철회하지 못한다(제527조). 이 구속력에 대한 예외 규정은 두지 않았다.","c":"상","v":1},"공인노2024_33-26-3":{"f":"민법은 격지자간의 계약은 승낙의 통지를 발송한 때에 성립한다고 규정하고 있다.","w":"격지자 사이의 계약은 승낙의 통지를 발송한 때에 성립한다(제531조). 도달한 때가 아니다.","c":"상","v":1},"공인노2024_33-26-4":{"f":"청약은 그에 응하는 승낙이 있어야 계약이 성립하므로 구체적이고 확정적이어야 한다.","w":"청약은 승낙만으로 계약이 성립할 수 있을 정도로 내용이 구체적이고 확정적이어야 한다.","c":"상","v":1},"공인노2024_33-26-5":{"f":"아파트의 분양광고가 청약의 유인인 경우, 피유인자가 이에 대응하여 청약을 하더라도 분양자의 승낙이 있어야 분양계약이 성립한다.","w":"청약의 유인은 상대방의 청약을 유도하는 행위일 뿐이다. 피유인자의 청약만으로는 계약이 성립하지 않고 분양자의 승낙이 필요하다.","c":"상","v":1},"공인노2024_33-27-2":{"f":"목적물이 타인의 소유에 속하는 매매계약은 유효하다.","w":"타인의 권리를 목적으로 하는 매매도 유효하다. 매도인이 그 권리를 취득하여 매수인에게 이전할 의무를 진다(제569조).","c":"상","v":1},"공인노2024_33-28-5":{"f":"동시이행항변권에 따른 이행지체 책임 면제의 효력은 그 항변권을 행사하지 않아도 발생한다.","w":"동시이행항변권이 있으면 상대방이 이행제공을 하지 않는 한 항변권을 행사하지 않아도 이행지체 책임이 생기지 않는다.","c":"상","v":1},"공인노2024_33-29-4":{"f":"제3자를 위한 계약에서 제3자는 낙약자에게 계약의 이익을 받을 의사를 표시해야 권리를 직접 취득한다.","w":"제3자의 수익 의사표시는 낙약자에 대하여 한다(제539조 제2항). 요약자와 낙약자 양쪽에 할 필요가 없다.","c":"상","v":1},"공인노2025_34-27-1":{"f":"乙이 중도금을 지급하지 않은 채 잔금기일이 지난 경우, 기계인도채무와 동시이행관계에 있는 것은 중도금과 잔금지급채무 전부이다.","w":"선이행 의무인 중도금을 내지 않은 채 잔금기일이 지나면 중도금과 잔금이 모두 인도채무와 동시이행 관계가 된다.","c":"상","v":1},"공인노2025_34-27-2":{"f":"乙이 중도금을 지급하지 않은 채 잔금기일이 지난 경우, 중도금에 대한 지연손해금은 잔금기일이 지나면 더 이상 발생하지 않는다.","w":"잔금기일이 지나면 중도금도 동시이행 관계에 들어가 이행지체가 되지 않는다. 그래서 잔금기일 이후 중도금의 지연손해금은 발생하지 않는다.","c":"상","v":1},"공인노2025_34-27-4":{"f":"‘잔금을 지급기일에 지급하지 않으면 최고없이 해제된다’고 특약한 경우에도, 매도인이 자기 채무의 이행을 제공하지 않았다면 잔금이 지급기일에 지급되지 않았다는 이유만으로 특약에 의해 해제된 것으로 볼 수 없다.","w":"잔금은 매도인의 소유권이전등기 이행과 동시이행 관계다. 매도인이 이행을 제공하지 않았다면 매수인이 잔금을 내지 않아도 지체가 아니므로 해제 특약이 작동하지 않는다.","c":"상","v":1},"공인노2025_34-27-5":{"f":"매매목적물이 자기소유라고 주장하는 제3자가 있다면, 乙은 매매대금의 지급을 거절할 권리가 있다.","w":"매매목적물에 대해 권리를 주장하는 사람이 있어 권리를 잃을 염려가 있으면 매수인은 대금 지급을 거절할 수 있다(제588조).","c":"상","v":1},"공인노2025_34-28-5":{"f":"매수인이 매매목적물을 인도받아 사용하던 중 당사자 쌍방의 귀책사유 없이 제3자의 소유로 판명되어 제3자에게 그 목적물을 인도한 경우, 매수인은 매도인에게 그 목적물의 사용에 따른 이익을 반환할 의무가 있다.","w":"타인 소유로 밝혀져 이행이 불능이 되면 계약 관계는 원상으로 정리되고, 매수인이 목적물을 쓰며 얻은 이익도 매도인에게 반환해야 한다.","c":"중","v":1},"공인노2025_34-29-2":{"f":"요약자는 낙약자에 대하여 ‘제3자에게 급부를 이행할 것’을 요구할 권리가 있다.","w":"요약자도 계약의 당사자로서 낙약자에게 제3자에게 급부할 것을 청구할 수 있다.","c":"상","v":1},"공인노2025_34-29-3":{"f":"제3자가 수익의 의사표시를 한 이후에도 요약자와 낙약자가 계약 당시 제3자의 권리를 변경시킬 수 있도록 미리 유보하였다면 요약자와 낙약자는 제3자의 권리를 변경시킬 수 있다.","w":"권리가 확정된 뒤의 변경·소멸 금지는 제3자 보호를 위한 규정이다. 계약 당시 이를 미리 유보했다면 변경할 수 있다.","c":"상","v":1},"공인노2025_34-29-4":{"f":"요약자와 낙약자 사이의 매매계약이 해제된 경우, 그 계약에 따라 매매대금을 제3자에게 지급한 낙약자는 그 제3자에 대하여 지급한 금액의 반환을 청구할 수 없다.","w":"낙약자가 제3자에게 한 급부는 요약자와의 계약 관계에서 한 것이다. 해제 후 낙약자는 제3자가 아니라 요약자에게 반환을 청구해야 한다.","c":"상","v":1},"공인노2025_34-29-5":{"f":"낙약자는 요약자와 수익자 사이의 대가관계가 해제되었다는 점을 들어 수익자에게 대항할 수 없다.","w":"낙약자는 기본관계(보상관계)에 기한 항변으로만 수익자에게 대항할 수 있다. 요약자와 수익자 사이의 대가관계의 효력은 낙약자와 무관하다.","c":"상","v":1},"공인노2026_35-28-4":{"f":"乙의 책임있는 사유로 고려청자가 멸실되어 甲이 자기의 채무를 면함으로써 이익을 얻은 때에는 甲은 이를 乙에게 상환하여야 한다.","w":"채권자 책임으로 이행불능이 되어도 채무자는 대금을 청구할 수 있지만, 채무를 면해서 얻은 이익은 채권자에게 상환해야 한다(제538조 제2항).","c":"상","v":1},"공인노2026_35-30-5":{"f":"매매계약의 해제로 인한 매매대금의 반환에 대하여는 그 받은 날로부터 민법 소정의 법정이자를 부가하여 지급하여야 한다.","w":"해제로 반환하는 금전에는 받은 날부터 이자를 붙인다(제548조 제2항). 해제가 있은 날부터가 아니다.","c":"상","v":1},"공인노2017_26-73-1":{"f":"연체차임은 임대차계약 종료 후 목적물이 반환되는 때에 별도의 의사표시 없이 임대차보증금에서 당연히 공제된다.","w":"연체차임은 임대차가 끝나고 목적물이 반환될 때 보증금에서 당연히 공제된다. 계약이 계속되는 동안에는 별도의 의사표시 없이 공제되지 않는다.","c":"상","v":1},"공인노2017_26-73-2":{"f":"건물임대차의 존속기간에는 20년의 제한이 없다.","w":"임대차 존속기간을 20년으로 제한하던 제651조는 2016년 삭제되었다. 지금은 건물임대차의 존속기간에 상한이 없다.","c":"상","v":1},"공인노2017_26-73-4":{"f":"임대인이 임대목적물에 대한 소유권 기타 이를 임대할 권한이 없는 경우에도 임대차 계약은 유효하게 성립한다.","w":"임대차는 채권계약이어서 임대인이 소유자일 필요가 없다. 타인 소유물의 임대차도 유효하다.","c":"상","v":1},"공인노2017_26-73-5":{"f":"임차인이 임대인의 동의 없이 임차권을 양도한 경우 임대인은 임대차계약을 해지할 수 있다.","w":"임차권 양도에는 임대인의 동의가 필요하다. 동의 없이 양도하면 임대인이 계약을 해지할 수 있다(제629조 제2항).","c":"상","v":1},"공인노2019_28-71-4":{"f":"위임사무처리에 비용을 요하는 경우, 乙은 위임사무를 완료하기 전이라도 그 비용의 선급을 청구할 수 있다.","w":"위임인은 수임인의 청구에 따라 비용을 미리 지급해야 한다(제687조).","c":"상","v":1},"공인노2019_28-72-2":{"f":"甲의 귀책사유로 임대차계약이 해지된 경우에도 원칙적으로 乙은 원상회복의무를 부담한다.","w":"임대차가 끝나면 해지 귀책 사유와 관계없이 임차인은 목적물을 원상으로 회복해 반환해야 한다.","c":"상","v":1},"공인노2019_28-73-1":{"f":"화해당사자의 자격에 관한 착오가 있는 경우에는 이를 이유로 취소할 수 있다.","w":"화해는 분쟁 대상에 관한 착오로는 취소할 수 없지만, 화해 당사자의 자격이나 화해의 목적물이 아닌 사항에 관한 착오는 취소할 수 있다(제733조 단서).","c":"상","v":1},"공인노2022_31-73-4":{"f":"위임인에게 불리한 시기에 부득이한 사유로 계약을 해지한 수임인은 그 해지로 인해 위임인에게 발생한 손해를 배상할 필요가 없다.","w":"부득이한 사유가 있으면 불리한 시기에 해지해도 손해배상 책임이 없다(제689조 제2항).","c":"상","v":1},"공인노2024_33-32-2":{"f":"매매계약에 관한 비용은 다른 약정이 없는 한 당사자 쌍방이 균분하여 부담한다.","w":"매매계약 비용은 쌍방이 똑같이 나눈다(제566조). 매수인이 전부 부담하는 것이 아니다.","c":"상","v":1},"공인노2024_33-32-3":{"f":"경매목적물에 하자가 있는 경우에도 경매에서의 채무자는 하자담보책임을 부담하지 않는다.","w":"경매에서 물건의 하자에 대한 담보책임(제580조)은 적용되지 않는다. 권리의 하자에 관한 담보책임만 있다.","c":"상","v":1},"공인노2024_33-32-4":{"f":"매매계약 후 인도되지 않은 목적물로부터 생긴 과실은 다른 약정이 없는 한 매수인이 대금을 완제하지 않았다면 매도인에게 속한다.","w":"인도하지 않은 목적물에서 생긴 과실은 매도인에게 속한다(제587조). 매수인이 대금을 다 낸 뒤라면 인도 전이라도 과실은 매수인에게 속한다는 것이 판례다.","c":"상","v":1},"공인노2024_33-32-5":{"f":"부동산 매매등기와 동시에 환매권의 보류를 등기하지 않으면 제3자에 대하여 효력이 없다.","w":"환매특약은 매매등기와 동시에 등기해야 제3자에게 대항할 수 있다(제592조). 5년 뒤에 등기하면 제3자에게 효력이 없다.","c":"상","v":1},"공인노2024_33-35-3":{"f":"도급인이 하자보수에 갈음하여 손해배상을 청구하는 경우, 수급인이 그 채무이행을 제공할 때까지 도급인은 그 손해배상액에 상응하는 보수액에 한하여 지급을 거절할 수 있다.","w":"보수 지급 거절은 손해배상액에 상응하는 부분으로 한정된다. 나머지 보수까지 전부 거절하는 것은 신의칙에 반한다.","c":"상","v":1},"공인노2024_33-36-1":{"f":"여행자는 여행을 시작하기 전에는 언제든지 여행계약을 해제할 수 있다.","w":"여행자는 여행을 시작하기 전에는 언제든지 계약을 해제할 수 있고, 상대방에게 생긴 손해만 배상하면 된다(제674조의3).","c":"상","v":1},"공인노2024_33-36-2":{"f":"여행대금지급시기에 관해 약정이 없는 경우, 여행자는 관습이 없으면 여행 종료 후 지체 없이 여행대금을 지급하여야 한다.","w":"대금 지급시기는 약정이 없으면 관습에 따르고, 관습도 없으면 여행 종료 후 지체 없이 지급한다(제674조의5).","c":"상","v":1},"공인노2024_33-36-3":{"f":"여행의 하자에 대한 시정에 지나치게 많은 비용이 드는 경우에는 여행자는 그 시정을 청구할 수 없다.","w":"시정에 지나치게 많은 비용이 들거나 시정이 불가능하면 시정을 청구하지 못한다(제674조의6 제1항 단서).","c":"상","v":1},"공인노2024_33-36-5":{"f":"여행계약의 담보책임 존속기간에 관한 규정과 다른 합의가 있는 경우, 그 합의가 여행자에게 불리한 것이면 효력이 없다.","w":"여행자에게 불리한 합의만 효력이 없다(제674조의9). 여행자에게 유리한 합의는 효력이 있다.","c":"상","v":1},"공인노2024_33-37-4":{"f":"기간의 약정이 없는 토지임대차의 임대인이 임대차계약의 해지를 통고한 경우, 그 해지의 효력은 임차인이 통고를 받은 날부터 6개월 후에 발생한다.","w":"토지임대차는 임대인이 해지를 통고하면 6개월이 지나서 효력이 생긴다. 토지·건물 등 부동산 임대차는 임대인이 통고하면 6개월, 임차인이 통고하면 1개월 뒤에 효력이 생긴다.","c":"상","v":1},"공인노2025_34-34-2":{"f":"매도인이 매수인에 대하여 이행을 최고하고 매매잔대금의 지급을 구하는 소를 제기하였다는 것만으로는 이행에 착수하였다고 볼 수 없다.","w":"이행의 최고나 이행 청구의 소 제기는 이행의 제공이 아니어서 이행에 착수한 것으로 보지 않는다.","c":"상","v":1},"공인노2025_34-34-3":{"f":"당사자 사이에 해약권을 배제하기로 하는 약정이 있다면 해약금 해제를 할 수 없다.","w":"당사자가 해약권을 배제하기로 약정하면 해약금에 의한 해제를 할 수 없다.","c":"상","v":1},"공인노2025_34-34-4":{"f":"매도인이 계약금의 배액을 이행제공하였으나 매수인이 이를 수령하지 아니하는 경우에도, 매도인이 해약금 해제를 하기 위해서 공탁까지 할 필요는 없다.","w":"배액을 제공했는데 수령하지 않으면 해제 효력이 생긴다. 공탁까지 해야 하는 것은 아니다.","c":"상","v":1},"공인노2025_34-34-5":{"f":"계약금 일부만 지급된 경우, 매도인은 약정 계약금의 배액을 상환하고 해약금 해제를 할 수 있다.","w":"계약금의 일부만 받은 매도인도 받은 금액이 아니라 약정한 계약금 전체의 배액을 상환해야 해약금 해제를 할 수 있다.","c":"상","v":1},"공인노2025_34-38-2":{"f":"2인 조합에서 조합원 1인이 탈퇴하는 경우, 잔존자는 조합의 탈퇴자에 대한 채권을 자동채권으로 하여 탈퇴자에 대한 지분 상당의 조합재산 반환채무와 상계할 수 있다.","w":"2인 조합에서 한 사람이 탈퇴하면 조합관계가 끝나고 정산만 남는다. 잔존자는 탈퇴자에 대한 채권으로 지분 반환채무와 상계할 수 있다.","c":"중","v":1},"공인노2026_35-34-1":{"f":"미등기인 무허가 건물도 원칙적으로 지상물매수청구의 대상이 될 수 있다.","w":"지상물매수청구의 대상 건물은 등기 여부나 적법한 건축 여부와 관계없이 임차인 소유의 독립한 건물이면 된다.","c":"상","v":1},"공인노2026_35-34-3":{"f":"임대차 기간 만료시에 지상물매수청구의 대상인 건물을 철거하기로 하는 특약은 임차인에게 불리하므로 원칙적으로 무효이다.","w":"지상물매수청구권 규정은 임차인에게 불리한 약정을 무효로 하는 강행규정이다(제652조). 철거 특약은 이를 배제하는 것이어서 무효다.","c":"상","v":1},"공인노2026_35-34-4":{"f":"건물에 저당권이 설정된 경우에도 임차인은 지상물매수청구권을 행사할 수 있다.","w":"건물에 저당권이 있다는 사정만으로 매수청구권이 부정되지 않는다.","c":"상","v":1},"공인노2026_35-34-5":{"f":"임차인의 채무불이행을 이유로 계약이 해지된 경우, 임차인은 임대인에 대하여 지상물매수청구권을 행사할 수 없다.","w":"임차인의 차임 연체 같은 채무불이행으로 해지되면 지상물매수청구권은 인정되지 않는다.","c":"상","v":1},"공인노2026_35-35-3":{"f":"부동산 임대차계약을 체결한 후 임대차등기를 하면 그 등기를 한 때부터 제3자에 대하여 효력을 주장할 수 있다.","w":"임대차는 등기를 한 때부터 제3자에게 대항할 수 있다(제621조 제2항). 계약을 체결한 때부터가 아니다.","c":"상","v":1},"공인노2017_26-74-5":{"f":"부당이득 반환의무는 수익자에게 고의 또는 과실이 없는 경우에도 인정된다.","w":"부당이득은 법률상 원인 없이 이익을 얻어 타인에게 손해를 준 사실만으로 성립한다. 수익자의 고의·과실은 요건이 아니다.","c":"상","v":1},"공인노2019_28-75-1":{"f":"채무자가 채무 없음을 알고 임의로 변제한 경우, 그 반환을 청구할 수 없다.","w":"채무 없음을 알고 한 변제는 반환을 청구하지 못한다(제742조).","c":"상","v":1},"공인노2019_28-75-2":{"f":"선의의 수익자가 패소한 때에는 그 소송이 제기된 때부터 악의의 수익자로 본다.","w":"선의 수익자는 패소한 경우 판결 확정 시가 아니라 소가 제기된 때부터 악의로 본다(제749조 제2항).","c":"상","v":1},"공인노2019_28-75-3":{"f":"불법원인급여로 인해 반환을 청구하지 못하는 이익은 종국적인 것이어야 한다.","w":"불법원인급여의 반환 거절은 급여가 종국적 이행으로 이루어진 경우에 적용된다. 아직 되돌릴 수 있는 급여는 해당하지 않는다.","c":"상","v":1},"공인노2019_28-75-4":{"f":"제한능력을 이유로 법률행위를 취소하는 경우, 악의의 제한능력자도 그 행위로 인하여 받은 이익이 현존하는 한도에서 상환하면 된다.","w":"제한능력자는 선의·악의를 구분하지 않고 현존이익 한도에서만 반환하면 된다(제141조 단서).","c":"상","v":1},"공인노2022_31-74-1":{"f":"채무자가 착오로 변제기 전에 채무를 변제한 경우, 채권자는 이로 인해 얻은 이익을 반환할 의무가 있다.","w":"변제기 전 변제는 원칙적으로 반환을 청구하지 못하지만, 착오로 한 때에는 채권자가 이로 인한 이익을 반환해야 한다(제743조).","c":"상","v":1},"공인노2022_31-74-2":{"f":"수익자가 이익을 받은 후 법률상 원인없음을 안 때에는 그때부터 악의의 수익자로서 이익반환의 책임이 있다.","w":"악의의 수익자로 책임지는 것은 법률상 원인 없음을 안 때부터다(제749조 제1항). 이익을 받은 날부터가 아니다.","c":"상","v":1},"공인노2022_31-74-3":{"f":"선의의 수익자가 패소한 때에는 그 소송이 제기된 때부터 악의의 수익자로 본다.","w":"패소가 확정된 때가 아니라 소가 제기된 때부터 악의로 본다.","c":"상","v":1},"공인노2022_31-74-4":{"f":"불법원인급여에서 수익자의 불법성이 현저히 크고, 그에 비하여 급여자의 불법성은 경미한 경우에는 급여자의 반환 청구가 허용된다.","w":"수익자의 불법성이 급여자보다 현저히 크면 반환청구를 막는 제746조 본문이 적용되지 않아 급여자는 반환을 청구할 수 있다는 것이 판례다.","c":"상","v":1},"공인노2024_33-38-3":{"f":"사무관리의 성립요건인 ‘타인을 위하여 사무를 처리하는 의사’는 반드시 외부적으로 표시될 필요는 없다.","w":"관리의 의사는 내심이면 충분하고 외부에 표시될 필요가 없다.","c":"상","v":1},"공인노2019_28-74-4":{"f":"공동불법행위자 1인에 대한 이행청구는 다른 공동불법행위자에 대하여 시효중단의 효력이 없다.","w":"공동불법행위자의 채무는 부진정연대채무라서 이행청구 같은 사유는 다른 사람에게 효력이 없다.","c":"상","v":1},"공인노2025_34-40-2":{"f":"공동불법행위에서 과실상계를 함에 있어서 피해자의 공동불법행위자 각자에 대한 과실 비율이 서로 다른 경우, 피해자의 과실은 공동불법행위자 전원에 대한 과실로 전체적으로 평가함이 원칙이다.","w":"피해자 과실은 공동불법행위 전체에 대해 하나로 평가해 과실상계한다. 가해자별로 따로 나누어 계산하는 것은 원칙이 아니다.","c":"중","v":1},"공인노2025_34-40-3":{"f":"민법 제758조의 공작물책임 중 소유자의 책임은 무과실책임이다.","w":"공작물 점유자는 면책 가능성이 있는 과실책임이지만, 점유자가 면책되면 부담하는 소유자의 책임은 무과실책임이다.","c":"상","v":1},"공인노2025_34-40-4":{"f":"채무불이행으로 인한 손해배상청구권에 대한 소멸시효 항변에는 불법행위로 인한 손해배상청구권에 대한 소멸시효 항변이 포함된 것으로 볼 수 없다.","w":"채무불이행과 불법행위는 별개의 청구권이어서 소멸시효 항변도 따로 주장해야 한다.","c":"상","v":1},"공인노2025_34-40-5":{"f":"공동불법행위자 중 일부가 피해자의 부주의를 이용하여 고의로 불법행위를 저지른 경우에도, 그러한 사유가 없는 다른 불법행위자는 과실상계를 주장할 수 있다.","w":"고의 가해자는 과실상계를 주장할 수 없지만 그런 사정이 없는 다른 불법행위자는 피해자 과실을 이유로 과실상계를 주장할 수 있다.","c":"상","v":1},"공인노2025_34-06-1":{"f":"무경험은 어느 특정영역에서의 경험부족이 아니라 거래일반에 대한 경험부족을 의미한다.","w":"무경험은 특정 분야를 몰랐다는 뜻이 아니라 생활 전반의 거래 경험이 부족한 것을 말한다.","c":"상","v":1},"공인노2025_34-09-1":{"f":"본인을 대리하여 부동산을 매수할 권한을 수여받은 대리인은 특별한 사정이 없으면 그 부동산을 처분할 대리권을 가지지 않는다.","w":"매수 대리권은 매수 행위에 한정된다. 사들인 부동산을 다시 처분하는 권한까지 포함하지 않으므로 별도의 수권이 있어야 한다.","c":"상","v":1},"공인노2019_28-59-1":{"f":"甲이 매매계약을 추인하면 다른 의사표시가 없는 한 계약 시에 소급하여 효력이 생긴다.","w":"무권대리행위의 추인은 다른 의사표시가 없으면 계약 시로 소급하여 효력이 생긴다. 다만 제3자의 권리를 해하지 못한다(민법 제133조).","c":"상","v":1},"공인노2019_28-59-3":{"f":"甲은 매매계약의 추인을 거절하였다면 이를 다시 번복하여 추인할 수 없다.","w":"본인이 추인을 거절하면 무권대리행위는 본인에 대하여 무효로 확정되므로, 그 뒤에 추인하더라도 유효로 되지 않는다는 것이 판례다.","c":"상","v":1},"공인노2019_28-59-4":{"f":"乙이 미성년자인 경우에는 乙은 무권대리인의 책임을 지지 않는다.","w":"대리인으로서 계약한 사람이 제한능력자이면 상대방에 대한 무권대리인의 이행·손해배상 책임 규정이 적용되지 않는다(민법 제135조 제2항).","c":"상","v":1},"공인노2024_33-14-1":{"f":"","w":"강박에 의한 의사표시는 취소할 수 있을 뿐이다(민법 제110조). 판례는 강박으로 맺은 계약이라는 사정만으로 반사회질서 법률행위(제103조)가 되어 무효로 되지는 않는다고 본다.","c":"상","v":1},"공인노2024_33-14-2":{"f":"","w":"乙은 강박 때문이기는 하지만 지분을 증여한다는 뜻을 정하고 표시하였다. 판례는 이런 경우 증여의 내심의 효과의사가 없다고 할 수 없어 비진의표시가 아니라고 본다.","c":"상","v":1},"공인노2024_33-14-3":{"f":"","w":"乙은 丙에게 지분이전등기를 해 주지 않았고, 丁이 그간의 사정을 알았다는 것만으로는 반사회질서 법률행위가 되지 않는다. 이중매매가 무효로 되려면 매수인이 매도인의 배임행위에 적극 가담해야 한다는 것이 판례다.","c":"중","v":1},"공인노2024_33-14-4":{"f":"","w":"취소권은 추인할 수 있는 날부터 3년 안에 행사해야 한다(민법 제146조). 乙은 증여계약 직후 강박 상태에서 벗어났고 그 뒤 5년이 지났으므로 취소권이 소멸하였다.","c":"상","v":1},"공인노2017_26-70-2":{"f":"丙의 보증계약은 구두계약에 의하여는 그 효력이 발생하지 않는다.","w":"보증은 보증인의 기명날인 또는 서명이 있는 서면으로 그 의사가 표시되어야 효력이 생긴다(민법 제428조의2 제1항). 다만 보증인이 보증채무를 이행한 한도에서는 방식 위반을 이유로 무효를 주장하지 못한다(같은 조 제3항).","c":"상","v":1},"공인노2025_34-36-2":{"f":"Y가 미등기 무허가 건물인 경우에도, 乙은 甲에게 건물매수청구권을 행사할 수 있다.","w":"판례는 건물 소유를 목적으로 한 토지임대차에서 임차인 소유 건물이 미등기 무허가 건물이라도 매수청구권의 대상이 된다고 본다(민법 제643조).","c":"상","v":1},"공인노2017_26-56":{"w":"ㄱ O 본인이 대리인 행세를 알면서 이의 없이 방임하면 묵시적 대리권 수여가 추단될 수 있다(판례).\nㄴ X 적법한 대리인이 체결한 계약이 해제되면 대리인이 받은 급부를 본인이 실제로 넘겨받지 못했더라도 원상회복의무는 본인이 진다(판례).\nㄷ O 재단법인 설립행위는 상대방 없는 단독행위여서 무권대리는 확정적으로 무효이고 추인할 수 없으며, 제135조의 무권대리인 책임도 생기지 않는다.\nㄹ X 계약 체결 대리권에는 특별한 사정이 없으면 그 계약을 해제할 권한이나 상대방의 의사표시를 수령할 권한이 들어 있지 않다(판례).","c":"상","v":1},"공인노2017_26-59":{"w":"② 희망퇴직 권고를 받고 여러 사정을 따져 본 끝에 사직서를 냈다면 그 당시로서는 사직이 최선이라고 판단해 내린 의사표시이므로 진의가 있다(판례). 비진의 의사표시가 아니다.\n① 회사 방침에 따라 사직원을 내고 즉시 재입사해 근로관계 단절 없이 일했다면 사직 의사가 없었으므로 비진의 의사표시다(판례).\n③ 사용자 지시로 사직 의사 없이 낸 사직서를 선별 수리했다면 비진의 의사표시다.\n④ 명의대여자는 채무 부담 의사로 표시한 것이어서 비진의가 아니고 주채무자 책임을 진다.\n⑤ 공무원의 사직 의사표시에는 제107조가 준용되지 않아 표시대로 효력이 생긴다(판례).","c":"상","v":1},"공인노2019_28-55":{"w":"ㄱ X 뇌물을 소극적으로 숨기려고 맡긴 임치약정은 반사회적 법률행위가 아니다(판례).\nㄴ X 강제집행을 피하려고 허위 근저당권을 설정한 행위는 통정허위표시로 무효일 뿐, 제103조 위반이 아니다(판례).\nㄷ O 도박자금으로 쓰일 것을 알고 금전을 빌려주는 행위는 제103조 위반으로 무효다.\nㄹ X 해외파견 후 일정 기간 근무하지 않으면 파견 비용을 갚기로 한 약정은 비용 반환 약정으로서 유효하다(판례).","c":"상","v":1},"공인노2024_33-12":{"w":"④ 유언은 유언자가 사망해야 효력이 생기는 사후행위(사인행위)다.\n① 보증은 서면으로 해야 효력이 생기므로(제428조의2) 요식행위다.\n② 증여는 합의만으로 성립하는 낙성계약이다.\n③ 채무면제는 채권을 직접 소멸시키는 처분행위다.\n⑤ 상계는 상대방에 대한 의사표시로 하는 단독행위다(제493조).","c":"상","v":1},"공인노2024_33-13":{"w":"ㄱ X 부동산 매도 대리권에는 계약 체결 후 이를 합의해제할 권한까지 들어 있지 않다(판례).\nㄴ O 본인 허락 없는 자기계약(제124조)은 무권대리가 되어 본인이 추인하기 전까지 유동적 무효다.\nㄷ X 임의대리인은 본인 승낙이나 부득이한 사유가 있어야 복대리인을 선임할 수 있다(제120조). 오피스텔 분양처럼 대리인의 능력이 중요한 사무는 묵시적 승낙도 쉽게 인정되지 않는다(판례).\nㄹ X 제128조: 원인된 법률관계가 끝나면 수권행위 철회가 없어도 대리권은 소멸한다.","c":"상","v":1},"공인노2024_33-15":{"w":"ㄱ O 토지거래허가 전 유동적 무효 상태에서도 매도인은 계약금 배액을 상환하고 해제할 수 있다(판례).\nㄴ X 허가 전에는 매매계약상 채무가 생기지 않으므로, 협력의무 불이행을 이유로 매매계약 자체를 해제할 수 없다(판례). 협력의무 이행은 소로 구할 수 있다.\nㄷ X 유동적 무효 상태에서는 계약금을 부당이득으로 돌려받을 수 없다. 계약이 확정적으로 무효가 되어야 반환을 청구할 수 있다.\nㄹ O 허가구역 지정이 해제되면 계약은 확정적으로 유효가 된다(판례).","c":"상","v":1},"공인노2025_34-07":{"w":"ㄱ O 비진의표시의 진의는 특정 내용의 의사표시를 하려는 표의자의 생각이지, 마음속으로 바라는 사항이 아니다(판례).\nㄴ O 통정허위표시도 채권자취소권의 대상이 될 수 있고, 그 자체로 무효다(판례).\nㄷ O 회사 방침에 따라 사직원을 내고 곧바로 재입사해 근로관계 단절 없이 일했다면 그 사직원 제출은 비진의표시다(판례).","c":"상","v":1},"공인노2025_34-08":{"w":"④ 제116조 제1항: 대리행위의 착오 유무는 대리인을 표준으로 결정한다.\n① 제733조 단서: 화해 당사자의 자격에 관한 착오는 화해계약을 취소할 수 있다.\n② 매도인이 해제한 뒤에도 매수인은 착오를 이유로 취소해 해제에 따른 손해배상책임을 피할 수 있다(판례).\n③ 하자담보책임이 성립해도 착오 취소는 따로 할 수 있다(판례).\n⑤ 법률에 관한 착오도 법률행위 내용의 중요부분에 관한 것이면 취소할 수 있다(판례).","c":"상","v":1},"공인노2025_34-10":{"w":"ㄱ O 표현대리가 성립하면 본인은 전적인 이행책임을 지고, 상대방 과실을 들어 과실상계로 책임을 줄일 수 없다(판례).\nㄴ O 표현대리를 주장하는 당사자는 무권대리인과 표현대리에 해당하는 무권대리행위를 특정해야 한다(판례).\nㄷ O 권한을 넘은 표현대리(제126조)에서 기본대리권과 표현대리행위는 같은 종류일 필요가 없다(판례).","c":"상","v":1},"공인노2025_34-11":{"w":"③ 제146조의 취소권 행사기간(추인할 수 있는 날부터 3년, 법률행위를 한 날부터 10년)은 제척기간이다(판례).\n① 제145조 제3호 경개는 법정추인 사유다.\n② 불공정한 법률행위에도 제138조 무효행위 전환이 적용될 수 있다(판례).\n④ 토지거래허가 위반으로 확정적 무효가 되면 그 무효에 책임이 있는 사람도 무효를 주장할 수 있다(판례).\n⑤ 제140조: 포괄승계인도 취소권자다.","c":"상","v":1},"공인노2026_35-06":{"w":"ㄱ X 제2매수인이 이중매매 사실을 알았다는 것만으로는 부족하고, 매도인의 배임행위에 적극 가담해야 반사회적 법률행위가 된다(판례).\nㄴ O 제1매수인은 제2매수인에게 직접 말소를 청구할 수 없고, 매도인을 대위해서 청구해야 한다(판례).\nㄷ O 반사회적 이중매매는 절대적 무효여서 제2매수인에게서 다시 산 제3자는 선의여도 소유권을 취득하지 못한다(판례).","c":"상","v":1},"공인노2026_35-08":{"w":"ㄱ O 제109조는 임의규정이어서 당사자가 그 적용을 배제하기로 합의하면 착오를 이유로 취소할 수 없다(판례).\nㄴ O 제109조 제1항 단서는 중대한 과실만 취소를 막는다. 경과실이 있어도 취소할 수 있다.\nㄷ O 동기의 착오도 그 동기를 법률행위 내용으로 삼았다면 중요부분의 착오로 취소할 수 있다(판례).","c":"상","v":1},"공인노2026_35-09":{"w":"ㄱ O 복대리인 선임권이 없는 대리인이 선임한 복대리인의 권한도 제126조 표현대리의 기본대리권이 될 수 있다(판례).\nㄴ O 강행법규 위반으로 무효인 계약에는 표현대리 법리가 적용되지 않는다(판례).\nㄷ X 표현대리가 성립하면 본인은 전적인 책임을 지며, 상대방 과실을 이유로 과실상계를 유추적용해 책임을 줄일 수 없다(판례).","c":"상","v":1},"공인노2026_35-10":{"w":"② 허가 전 유동적 무효 상태에서는 계약금을 부당이득으로 반환청구할 수 없다(판례). 계약이 확정적으로 무효가 된 뒤에야 반환을 구할 수 있다.\n① 허가 전에도 계약금 배액을 상환하고 해제할 수 있다(판례).\n③ 허가 전에는 소유권이전등기를 청구할 수 없다.\n④ 착오 등 취소 사유를 주장해 허가신청 협력을 거절하면 계약을 확정적 무효로 만들 수 있다(판례).\n⑤ 허가신청 협력의무는 소로 구할 수 있다(판례).","c":"상","v":1},"공인노2026_35-12":{"w":"ㄱ O 권리자가 무권리자의 처분을 추인하면 무권리자에게 그 처분으로 얻은 이득의 반환을 청구할 수 있다(판례).\nㄴ O 무권리자의 처분을 권리자가 추인하면 무권대리 추인(제130조·제133조)을 유추해 처분 시점으로 소급해 권리자에게 효력이 생긴다(판례).\nㄷ O 강박을 이유로 취소되어 무효가 된 법률행위도 무효행위 추인의 요건과 효력으로 추인할 수 있다(판례).","c":"상","v":1},"공인노2017_26-53":{"w":"⑤ 제100조 제2항(종물은 주물의 처분에 따른다)은 임의규정이어서 특약으로 종물을 처분에서 뺄 수 있다.\n① 제99조 제2항\n② 임대료는 물건 사용의 대가인 법정과실이다(제101조 제2항).\n③ 종물은 주물과 독립한 물건이어야 한다.\n④ 부동산도 주물과 종물 어느 쪽이든 될 수 있다.","c":"상","v":1},"공인노2024_33-02":{"w":"② 종물은 주물의 구성부분이 아닌 독립한 물건이어야 한다.\n① 부동산도 종물이 될 수 있다.\n③ 제100조 제2항은 임의규정이어서 종물을 처분에서 빼는 특약은 유효하다.\n④ 종물은 주물 자체의 경제적 효용을 돕는 물건이어야 한다. 소유자나 이용자의 상용에 쓰일 뿐 주물의 효용과 직접 관계없는 물건은 종물이 아니다(판례).\n⑤ 주물·종물 법리는 원본채권과 이자채권처럼 권리 상호간에도 유추적용된다(판례).","c":"상","v":1},"공인노2019_28-51":{"w":"⑤ 임차인의 부속물매수청구권은 행사하는 순간 매매계약이 성립하는 형성권이다.\n물권은 지배권, 제한능력자의 취소권과 매매예약 완결권은 형성권, 동시이행의 항변권은 연기적 항변권이다.","c":"상","v":1},"공인노2025_34-01":{"w":"ㄱ O 부작위 불법행위의 전제인 작위의무는 법령·계약뿐 아니라 신의칙상 작위의무가 기대되는 경우에도 인정된다(판례).\nㄴ O 사용자책임을 진 사용자가 피용자에게 구상할 때 신의칙상 상당한 한도로 구상권이 제한될 수 있다(판례).\nㄷ O 상계권 행사가 제도의 목적을 벗어나 법적 보호가치가 없으면 신의칙상 허용되지 않고, 이때 권리남용의 주관적 요건은 필요 없다(판례).","c":"상","v":1},"공인노2017_26-62":{"w":"④ 소멸시효 완성 후 채무를 승인해 시효이익을 포기하면 그때부터 시효가 새로 진행한다(판례).\n① 시효 완성은 당사자가 원용해야 하고 법원이 직권으로 고려하지 않는다(변론주의).\n② 제167조: 소멸시효는 기산일에 소급하여 효력이 생긴다.\n③ 제184조 제2항: 법률행위로 시효기간을 단축하거나 요건을 경감할 수 있다.\n⑤ 제166조 제2항: 부작위 채권의 시효는 위반행위를 한 때부터 진행한다.","c":"상","v":1},"공인노2024_33-07":{"w":"ㄱ O 소를 제기했다가 취하하면 재판상 청구로서의 중단 효력은 없지만, 재판 외 최고의 효력은 인정된다(제170조, 판례).\nㄴ X 대항요건을 갖추지 못한 채권양수인이 채무자에게 소를 제기해도 소멸시효는 중단된다(판례).\nㄷ X 제178조 제2항: 재판상 청구로 중단된 시효는 판결이 확정된 때(2024. 4. 20.)부터 새로 진행한다.","c":"상","v":1},"공인노2026_35-15":{"w":"ㄱ O 제척기간에는 중단이 없다.\nㄴ O 제척기간은 원칙적으로 권리가 발생한 때부터 기산한다.\nㄷ O 행사기간 약정이 없으면 매매예약 완결권은 예약이 성립한 때부터 10년의 제척기간이 지나면 소멸한다(판례).","c":"상","v":1},"공인노2022_31-67":{"w":"ㄱ O 당사자가 합의하면 충당 순서를 자유롭게 정할 수 있다.\nㄴ X 6월 5일에는 두 채무 모두 이행기가 지났다. 주채무자에게는 보증인 유무가 변제이익에 차이를 주지 않으므로(판례), 이율이 높은 B채무(월 1%)가 변제이익이 커서 먼저 충당된다(제477조 제2호).\nㄷ X 5월 3일에는 A채무만 이행기가 지났으므로 A채무에 먼저 충당한다(제477조 제1호).\nㄹ O 4월 28일에는 둘 다 이행기 전이므로 변제이익이 많은 B채무(이율이 높음)에 먼저 충당한다.","c":"상","v":1},"공인노2024_33-22":{"w":"ㄱ X 제482조 제2항 제1호의 '제3취득자'에 후순위 근저당권자는 들어가지 않는다. 보증인은 대위 부기등기 없이도 후순위 근저당권자에게 채권자를 대위할 수 있다(판례).\nㄴ O 주채무자가 변제자이면 보증인이 있는 채무와 없는 채무의 변제이익에 차이가 없다(판례).\nㄷ X 물상보증인은 제3취득자에게 채권 전부를 대위할 수 있지만, 제3취득자는 물상보증인에게 대위할 수 없다(판례). 가액 비례 대위는 물상보증인 상호간의 규칙이다.","c":"상","v":1},"공인노2025_34-32":{"w":"② 甲의 매매대금채권에는 乙의 동시이행항변권이 붙어 있다. 항변권이 붙은 채권을 자동채권으로 상계하면 상대방의 항변권을 빼앗게 되므로 甲은 상계할 수 없다(판례).\n① 제493조 제1항: 상계에는 조건이나 기한을 붙이지 못한다.\n③ 乙은 변제기가 지난 대여금채권으로 상계할 수 있고, 수동채권의 항변권은 스스로 포기하면 되므로 상계 후 인도를 구할 수 있다.\n④ 압류 전에 이미 취득했고 변제기도 먼저 도래한 대여금채권이므로 압류 후에도 상계할 수 있다(제498조, 판례).\n⑤ 제495조: 시효 완성 전에 상계적상에 있었으면 시효 소멸 후에도 상계할 수 있다.","c":"상","v":1},"공인노2026_35-25":{"w":"ㄱ X 제476조: 먼저 변제자가 지정하고, 변제자가 지정하지 않으면 변제받는 자가 지정할 수 있다.\nㄴ O 제477조 제1호\nㄷ X 제477조 제3호·제4호: 변제이익이 같으면 이행기가 먼저 도래한 채무에 충당하고, 그것도 같으면 채무액에 비례해 충당한다.\nㄹ X 제479조: 비용, 이자, 원본 순서다.","c":"상","v":1},"공인노2017_26-65":{"w":"① 제377조 제1항: 채권의 목적이 다른 나라 통화로 지급할 것이면 채무자는 자기가 고른 그 나라의 각 종류 통화로 변제할 수 있다.\n② 민사 법정이율은 연 5%(제379조), 상사 법정이율은 연 6%(상법 제54조)다.\n③ 제397조 제2항: 금전채무 불이행은 채권자가 손해를 증명할 필요가 없다.\n④ 지연손해금은 손해배상금이어서 3년 단기소멸시효(이자채권)가 아니라 원본채권의 시효를 따른다(판례).\n⑤ 특정한 봉투 속 금전처럼 금전도 특정물채권의 목적이 될 수 있다.","c":"상","v":1},"공인노2026_35-19":{"w":"ㄱ O 제460조 단서: 채권자의 행위가 필요한 경우 변제 준비를 마치고 수령을 최고하는 구두의 제공으로 충분하다.\nㄴ X 채권자지체는 법정책임이어서 채권자의 귀책사유가 필요 없다(판례).\nㄷ O 제403조\nㄹ X 채권자에게는 원칙적으로 수령의무가 없으므로 채권자지체만으로 채무불이행책임을 물을 수 없다(판례).","c":"상","v":1},"공인노2024_33-19":{"w":"ㄱ O 특정채권 보전을 위한 대위에는 채무자의 무자력이 필요 없다.\nㄴ O 임차인은 임차권 보전을 위해 임대인이 제3자에게 가진 인도청구권을 대위행사할 수 있다(판례).\nㄷ O 채권자대위권도 대위의 대상이 된다(판례).","c":"상","v":1},"공인노2024_33-20":{"w":"ㄱ O 사해행위의 수익자는 취소채권자의 피보전채권이 시효로 소멸했다고 원용할 수 있다(판례).\nㄴ O 채권양도가 취소되면 수익자가 제3채무자에게 양도가 취소되었다는 통지를 하도록 청구하는 방식으로 원상회복한다(판례).\nㄷ X 취소의 효력은 채권자와 수익자 사이에서만 생겨 채무자가 채권을 다시 취득하지 않는다. 그래서 취소채권자는 채무자를 대위해 제3채무자에게 지급을 청구할 수 없다(판례).","c":"상","v":1},"공인노2024_33-21":{"w":"ㄱ X 정지조건부 채권도 성립의 개연성이 있으면 피보전채권이 될 수 있다(판례).\nㄴ X 사해행위 후 제3자가 저당권을 취득해 가액배상을 명할 때는 그 저당권의 피담보채권액을 빼지 않은 가액을 배상한다(판례).\nㄷ X 동산을 현물반환할 때 취소채권자는 직접 자기에게 인도하라고 청구할 수 있다(판례).","c":"상","v":1},"공인노2017_26-68":{"w":"③ 채무자와 인수인 사이의 인수 합의는 특별한 사정이 없으면 병존적 채무인수로 보고, 제3자를 위한 계약이므로 채권자가 수익의 의사표시를 하면 인수인에게 권리를 갖는다(판례).\n① 제459조: 보증인이 동의하지 않으면 면책적 인수로 보증채무는 소멸한다.\n② 제3자가 기존 채무를 위해 어음·수표를 발행해도 면책적 인수로 보지 않는다.\n④ 제508조: 지시채권은 증서에 배서해 교부하는 방식으로 양도한다.\n⑤ 채무자는 채권양도 승낙에 조건을 붙일 수 있다(판례).","c":"상","v":1},"공인노2024_33-17":{"w":"⑤ 연대채무자 전원의 부탁을 받고 연대보증한 丁은 乙과 丙 모두의 보증인이므로 변제 후 어느 연대채무자에게나 전액을 구상할 수 있다.\n① 제420조: 혼동은 乙의 부담부분(6,000만 원) 한도에서만 丙을 면책시킨다.\n② 제418조 제2항: 丙은 乙의 부담부분 6,000만 원 한도에서만 乙의 반대채권으로 상계할 수 있다.\n③ 제416조: 연대채무자 한 사람에 대한 이행청구는 다른 채무자에게도 효력이 있다.\n④ 제419조: 乙에 대한 면제는 乙의 부담부분 6,000만 원만큼만 丙을 면하게 하므로 丙은 1억 2,000만 원 채무를 진다.","c":"상","v":1},"공인노2025_34-20":{"w":"부담부분은 각 3억 원이다.\nㄱ O 제417조: 경개는 절대적 효력이 있어 모든 연대채무자의 채무가 소멸한다.\nㄴ X 일부 면제 후 甲의 잔존 채무(5억 원)가 부담부분(3억 원)보다 많으면 甲의 부담부분이 줄지 않으므로, 乙과 丙은 9억 원 전액을 그대로 진다(판례).\nㄷ O 8억 원 면제 후 甲의 잔존 채무는 1억 원으로 부담부분보다 2억 원 적다. 그 차액 2억 원만큼 乙·丙도 면책되어 7억 원의 연대채무를 진다.","c":"상","v":1},"공인노2017_26-71":{"w":"① 채권증서 반환은 변제를 마친 뒤에 청구할 수 있어(제475조) 변제의무와 동시이행 관계가 아니다. 동시이행 관계에 있는 것은 영수증 교부다.\n②·③·④·⑤는 모두 판례상 동시이행 관계다.","c":"상","v":1},"공인노2019_28-69":{"w":"ㄱ X 수익자는 계약 체결 당시 특정되거나 현존하지 않아도 된다.\nㄴ O 제3자에 대한 채무를 면제하는 계약도 제3자를 위한 계약에 준하여 유효하다(판례).\nㄷ O 낙약자는 요약자와 수익자 사이의 대가관계에 기한 항변으로 수익자에게 대항할 수 없다(판례).\nㄹ X 수익자는 계약 당사자가 아니어서 해제권이 없다(판례).","c":"상","v":1},"공인노2022_31-71":{"w":"⑤ 이행불능을 이유로 해제한 경우 손해배상액은 이행불능 당시의 시가를 기준으로 산정한다(판례).\n① 합의해제는 유효하다.\n② 과다최고가 그 금액을 받지 않으면 수령하지 않을 것이 분명한 정도이면 그 최고에 기한 해제는 무효다(판례).\n③ 계약 체결 대리권에는 해제권이 없다(판례).\n④ 제547조 제1항","c":"상","v":1},"공인노2024_33-30":{"w":"ㄱ O 사직의 의사표시(합의해지 청약)는 사용자의 승낙으로 근로계약 종료 효과가 확정되기 전이면 철회할 수 있다(판례).\nㄴ O 묵시적 합의해지는 이행 착수 후 쌍방의 계약 실현 의사가 없거나 포기되어 계약을 실현하지 않기로 하는 의사가 일치해야 한다(판례).\nㄷ X 합의해지에는 제548조 제2항이 적용되지 않으므로, 약정이 없으면 반환할 금전에 받은 날부터의 이자를 붙일 의무가 없다(판례).","c":"상","v":1},"공인노2025_34-30":{"w":"ㄱ O 제543조 제2항\nㄴ X 제547조 제2항: 당사자 일방이 여러 명일 때 그중 1인의 해제권이 소멸하면 다른 당사자의 해제권도 소멸한다.\nㄷ O 제552조\nㄹ O 제553조: 해제권자의 가공·개조로 목적물이 다른 종류의 물건이 되면 해제권은 소멸한다.","c":"상","v":1},"공인노2025_34-31":{"w":"제548조 제1항 단서의 제3자는 해제된 계약에서 생긴 법률효과를 기초로 새로운 이해관계를 맺고 등기 등으로 완전한 권리를 취득한 자다.\nㄱ 해당 안 됨 계약상 매매대금채권 자체를 압류한 자는 제3자가 아니다(판례).\nㄴ 해당 목적물 X를 해제 전에 압류한 자는 제3자다.\nㄷ 해당 해제 전에 저당권을 취득했으면 해제 가능성을 알았어도 보호된다.\nㄹ 해당 안 됨 해제 후 이해관계를 맺은 자는 해제 사실을 몰랐어야 보호되는데, 알고 가등기를 했으므로 보호받지 못한다(판례).","c":"상","v":1},"공인노2026_35-29":{"w":"ㄱ X 요약자와 수익자 사이의 대가관계(대여금채무)가 소멸해도 요약자와 낙약자 사이의 매매계약(기본관계)에는 영향이 없다.\nㄴ O 낙약자는 대가관계의 무효를 들어 수익자에게 대항할 수 없다(판례).\nㄷ X 수익자는 계약 당사자가 아니어서 해제권이 없다.\nㄹ X 요약자는 낙약자의 채무불이행을 이유로 수익자의 동의 없이 계약을 해제할 수 있다(판례).","c":"상","v":1},"공인노2026_35-31":{"w":"ㄱ O 계약 해제로 인한 매수인의 가등기말소의무와 매도인의 대금반환의무는 동시이행 관계다(판례).\nㄴ O 건물매수청구권 행사 후 임차인의 건물 인도·이전등기의무와 임대인의 대금지급의무는 동시이행 관계다(판례).\nㄷ X 무효인 경매의 매수인이 지는 등기말소의무와 근저당권자의 배당금 반환의무는 서로 대가관계가 아니어서 동시이행 관계가 아니다(판례).","c":"상","v":1},"공인노2017_26-72":{"w":"③ 중도금 지급으로 매수인이 이행에 착수했으므로 매도인은 배액을 상환해도 해약금 해제를 할 수 없다(제565조).\n① 계약금은 위약금 약정이 없으면 해약금으로만 추정되므로, 채무불이행으로 해제해도 당연히 매도인에게 귀속되지 않는다(판례).\n② 매도인은 계약금의 배액을 상환해야 해제할 수 있다.\n④ 이행 착수 후에는 매수인도 해약금 해제를 할 수 없다.\n⑤ 제565조 제2항: 해약금 해제에는 손해배상 규정이 적용되지 않고, 이행 전이므로 원상회복 문제도 생기지 않는다.","c":"상","v":1},"공인노2024_33-31":{"w":"⑤ 증여자는 원칙적으로 하자에 대한 담보책임을 지지 않으며(제559조 제1항), 하자는 해제 사유가 아니다.\n① 제555조 서면에 의하지 않은 증여\n② 제556조 제1항 제1호 수증자의 범죄행위\n③ 제556조 제1항 제2호 부양의무 불이행\n④ 제557조 증여자의 재산상태 변경","c":"상","v":1},"공인노2024_33-33":{"w":"ㄱ X 수임인이 대변제청구권을 보전하려고 위임인의 채권을 대위행사할 때는 위임인의 무자력이 필요 없다(판례).\nㄴ X 제689조 제2항: 부득이한 사유가 있으면 불리한 시기에도 해지할 수 있고 손해배상책임도 지지 않는다.\nㄷ O 제681조: 무상이어도 수임인은 선량한 관리자의 주의의무를 진다.","c":"상","v":1},"공인노2024_33-34":{"w":"ㄱ X 관행상 보수가 따르는 것이 보통이면 명시적 합의가 없어도 묵시적 보수 약정이 인정되어 보수를 청구할 수 있다(판례).\nㄴ X 전적은 근로자의 동의가 있어야 효력이 생긴다(판례).\nㄷ X 제661조의 부득이한 사유에는 고용계약상 의무의 중대한 위반도 포함된다(판례).","c":"상","v":1},"공인노2025_34-33":{"w":"ㄱ O 제559조 제2항: 부담부 증여의 증여자는 부담의 한도에서 매도인과 같은 담보책임을 진다.\nㄴ O 부담 불이행으로 해제되면 이미 이행된 증여도 원상회복해야 하므로 수증자는 이전등기를 말소해야 한다(판례).\nㄷ O 증여에 부담이 붙었다는 사실은 그것을 주장하는 자가 증명한다(판례).","c":"상","v":1},"공인노2025_34-35":{"w":"⑤ 제616조: 공동차주는 연대하여 의무를 부담한다.\n① 제609조 무상계약\n② 제610조 제3항\n③ 제611조 제1항\n④ 제613조 제2항","c":"상","v":1},"공인노2025_34-37":{"w":"ㄱ O 제686조 제1항: 특별한 약정이 없으면 보수를 청구하지 못한다.\nㄴ O 제690조: 수임인의 성년후견개시는 위임 종료 사유다.\nㄷ O 제689조 제2항","c":"상","v":1},"공인노2026_35-33":{"w":"ㄱ O 제574조: 수량을 지정한 매매에서 수량이 부족하면 선의의 매수인은 대금감액을 청구할 수 있다.\nㄴ O 제575조 제1항: 목적물이 유치권의 목적이 되어 계약 목적을 달성할 수 없으면 선의의 매수인은 해제할 수 있다.\nㄷ X 제576조: 저당권 실행으로 소유권을 취득할 수 없게 되면 매수인은 악의여도 해제할 수 있다.","c":"상","v":1},"공인노2026_35-36":{"w":"ㄱ X 도급인이 제673조로 해제하면서 손해를 배상할 때는 수급인의 과실을 들어 과실상계를 주장할 수 없다(판례).\nㄴ O 수급인의 저당권설정청구권은 공사대금채권을 담보하기 위한 것이어서 공사대금채권이 양도되면 함께 이전한다(판례).\nㄷ X 하자보수에 갈음한 손해배상액은 건물 완성 시가 아니라 손해배상을 청구한 때를 기준으로 산정한다(판례).","c":"상","v":1},"공인노2026_35-37":{"w":"ㄱ O 2인 조합에서 1인이 탈퇴하면 조합재산은 남은 조합원의 단독소유가 되지만, 합유 부동산은 그 내용의 등기를 해야 소유권 변동 효력이 생긴다(판례).\nㄴ O 조합재산을 넘겨받은 잔존 조합원은 조합채무 전부를 인수하므로 조합채권자는 그에게 전부 이행을 청구할 수 있다(판례).\nㄷ O 제719조 제1항: 탈퇴 조합원과의 계산은 탈퇴 당시의 조합재산 상태로 한다.","c":"상","v":1},"공인노2026_35-39":{"w":"부속물매수청구권(제646조)은 건물 기타 공작물 임차인의 권리다. 토지임차인에게는 인정되지 않는다.\n필요비·유익비 상환청구권(제626조), 지상물매수청구권(제643조), 임대차등기 협력청구권(제621조)은 토지임차인도 가진다.","c":"상","v":1},"공인노2026_35-40":{"w":"ㄱ X 제587조: 대금 완납 전이라도 목적물을 인도받은 매수인은 그 사용이익을 매도인에게 부당이득으로 반환할 의무가 없다(판례).\nㄴ X 계약금 일부만 받은 상태에서 해약금 해제를 하려면 실제 받은 금액이 아니라 약정 계약금(1천만원)의 배액 2천만원을 상환해야 한다(판례).\nㄷ O 매수인이 대금을 모두 지급하면 인도 전이라도 그 이후 과실은 매수인에게 속한다(판례).","c":"상","v":1},"공인노2024_33-40":{"w":"ㄱ O 제548조 제2항에 따라 반환 금전에 붙이는 이자는 지연손해금이 아니라 부당이득반환의 성질을 갖는다(판례).\nㄴ O 제742조는 채무 없음을 알고 변제한 경우에만 적용되고, 몰랐다면 과실이 있어도 적용되지 않는다(판례).\nㄷ O 금전상 이득은 소비 여부와 관계없이 현존하는 것으로 추정된다(판례).","c":"상","v":1},"공인노2025_34-39":{"w":"ㄱ O 계약상 급부가 제3자에게 이익이 되었더라도 급부자는 계약 상대방에게만 청구할 수 있고, 제3자에게 직접 부당이득반환을 청구할 수 없다(판례).\nㄴ O 임대차 종료 후 동시이행항변권으로 건물을 계속 점유해도 실제로 사용·수익해 얻은 이익은 부당이득으로 반환해야 한다(판례).\nㄷ X 급부부당이득에서는 법률상 원인이 없다는 점을 반환을 청구하는 사람이 증명해야 한다(판례).","c":"상","v":1},"공인노2017_26-75":{"w":"③ 도급인이 수급인에게 특정 행위를 지휘하거나 공사 진행을 구체적으로 지휘·감독했다면 도급인은 사용자책임을 진다(판례).\n① 실질적 지휘·감독 관계가 필요하다.\n② 퇴직 후 행위는 원칙적으로 사용자책임 대상이 아니다.\n④ 외형이론(다만 피해자가 직무 범위가 아님을 알았거나 중과실로 몰랐으면 제외).\n⑤ 피해자 과실이 있으면 과실상계할 수 있다.","c":"상","v":1},"공인노2022_31-75":{"w":"ㄱ X 작위의무 있는 자의 부작위에 의한 과실방조도 공동불법행위의 방조가 될 수 있다(판례).\nㄴ O 도급인이 일의 진행과 방법을 구체적으로 지휘·감독했다면 사용자책임을 진다(판례).\nㄷ X 제755조 제1항 단서: 감독자가 감독의무를 게을리하지 않았음을 증명해야 책임을 면한다. 피해자가 감독의무 해태를 증명할 필요가 없다.\nㄹ X 파견사업주도 파견근로자의 선발과 일반적 지휘·감독에 주의를 다하지 않았다면 사용자책임을 진다(판례).","c":"상","v":1},"공인노2024_33-39":{"w":"ㄱ X 법적 작위의무가 객관적으로 인정되면 의무자가 그 의무를 알지 못했어도 부작위 불법행위가 성립할 수 있다(판례).\nㄴ X 공작물책임은 공작물의 하자와 관련된 위험이 현실화되어 생긴 손해에 대해서만 인정된다(판례).\nㄷ O 제766조 제3항: 미성년자가 성적 침해를 당한 경우 손해배상청구권의 시효는 성년이 될 때까지 진행하지 않는다.","c":"상","v":1},"공인노2026_35-38":{"w":"ㄱ O 사용자는 피용자 乙과 같은 범위의 책임을 지므로, 공동불법행위자들의 과실비율과 관계없이 丁에게 1억원 전액을 배상할 책임이 있다.\nㄴ O 피용자의 고의 영득행위라도 사용자책임을 지는 사용자는 피해자의 과실을 들어 감경을 주장할 수 있다(판례).\nㄷ X 금액이 다른 부진정연대채무에서 다액채무자가 일부 변제하면 다액채무자가 혼자 부담하는 부분(4천만원)부터 소멸한다(판례). 乙의 5천만원 변제 중 1천만원만 공동 부분에 충당되어 丙의 채무는 5천만원이 된다.","c":"상","v":1},"공인노2017_26-51-3":{"w":"제104조의 불공정한 법률행위는 객관적으로 급부가 현저히 불균형하고 주관적으로 피해자의 궁박·경솔·무경험을 폭리자가 알면서 이용하려는 의사(폭리행위의 악의)가 있어야 성립한다는 것이 판례다.","c":"중","v":1},"공인노2017_26-52-2":{"w":"허위표시의 외형을 기초로 새로 법률상 이해관계를 맺은 사람은 제108조 제2항의 제3자다. 丙이 악의라도 丙의 근저당권부 채권을 선의로 압류한 丁은 따로 보호되므로 甲은 허위표시의 무효를 丁에게 주장하지 못한다(판례).","c":"중","v":1},"공인노2017_26-52-3":{"w":"가장채권을 선의로 양수한 사람도 제108조 제2항으로 보호받지만 채무자에게 채권을 행사하려면 제450조의 대항요건(양도인의 통지 또는 채무자의 승낙)을 갖추어야 한다.","c":"중","v":1},"공인노2017_26-52-4":{"w":"파산관재인은 파산채권자 전체의 공동이익을 위해 직무를 행하므로 허위표시에 따른 가장채권에 관하여 제108조 제2항의 제3자로 본다. 선의 여부는 총파산채권자를 기준으로 하여 파산채권자 모두가 악의가 아닌 한 선의로 다룬다(판례).","c":"중","v":1},"공인노2017_26-52-5":{"w":"제108조 제2항은 「선의의 제삼자」라고만 정한다. 판례도 제3자는 선의이면 족하고 무과실까지 요하지 않는다고 본다.","c":"상","v":1},"공인노2017_26-54-5":{"w":"당사자 쌍방이 같은 토지를 매매목적물로 합의했다면 계약서에 지번을 잘못 적었더라도 합의한 대로 계약이 성립한다(오표시 무해의 원칙). 따라서 착오 취소 문제도 생기지 않는다(판례).","c":"중","v":1},"공인노2017_26-57-1":{"w":"제126조의 정당한 이유는 대리행위 당시의 여러 사정을 객관적으로 보아 판단하고 그 뒤의 사정은 고려하지 않는다(판례).","c":"중","v":1},"공인노2017_26-57-2":{"w":"표현대리가 성립하면 본인은 표현대리행위에 대해 전적인 책임을 진다. 상대방에게 과실이 있더라도 과실상계 법리를 유추해 본인의 책임을 줄일 수 없다(판례).","c":"중","v":1},"공인노2017_26-57-3":{"w":"제125조 단서에 따라 제3자가 대리권 없음을 알았거나 알 수 있었을 때에는 본인이 책임지지 않는다. 그래서 상대방은 선의·무과실이어야 한다.","c":"상","v":1},"공인노2017_26-57-5":{"w":"교회 재산은 교인들의 총유이고 총유물의 처분은 정관 등에 정함이 없으면 교인총회 결의를 거쳐야 한다(제275조·제276조 제1항). 결의 없이 대표자가 한 처분은 무효이고 이는 대표자의 권한을 넘은 행위가 아니어서 제126조를 준용할 여지가 없다(판례).","c":"중","v":1},"공인노2017_26-58-4":{"w":"제135조 제1항은 무권대리인이 「상대방의 선택에 따라」 계약 이행 책임 또는 손해배상 책임을 진다고 정한다.","c":"상","v":1},"공인노2017_26-60-2":{"w":"제103조 위반 법률행위는 절대적 무효라서 당사자가 그 무효를 알고 추인해도 유효가 되지 않는다(판례). 제139조 단서의 새로운 법률행위로 보더라도 같은 이유로 무효다.","c":"중","v":1},"공인노2017_26-60-3":{"w":"제140조가 취소권자로 제한능력자 본인을 들고 있다. 미성년자는 법정대리인의 동의 없이 단독으로 취소할 수 있고 그 취소는 다시 취소할 수 없다.","c":"상","v":1},"공인노2017_26-60-4":{"w":"제137조 본문은 일부무효면 전부를 무효로 한다. 무효 부분이 없더라도 법률행위를 했으리라고 인정되는 때에만 나머지가 유효하다(같은 조 단서).","c":"상","v":1},"공인노2017_26-60-5":{"w":"제141조 단서는 취소된 행위로 받은 이익을 제한능력자가 현존하는 한도에서만 돌려주게 한다. 선의·악의를 묻지 않는다.","c":"상","v":1},"공인노2017_26-61-1":{"w":"제151조 제2항: 조건이 법률행위 당시 이미 성취된 경우 정지조건이면 조건 없는 법률행위, 해제조건이면 무효인 법률행위가 된다.","c":"상","v":1},"공인노2017_26-61-2":{"w":"제149조가 조건의 성취가 미정한 권리의무를 일반규정에 의해 처분·상속·보존·담보로 할 수 있게 한다.","c":"상","v":1},"공인노2017_26-61-3":{"w":"조건은 법률행위의 효력 발생·소멸을 제한하는 부관이므로 조건이 붙어 있다는 사실은 그 조건 때문에 법률효과가 생기지 않았다거나 소멸했다고 주장하는 쪽이 증명해야 한다(판례).","c":"중","v":1},"공인노2017_26-61-5":{"w":"제153조 제2항은 기한의 이익을 포기할 수 있되 상대방의 이익을 해하지 못한다고 정한다. 그래서 상대방에게도 기한의 이익이 있으면 그 손해(예: 이행기까지의 이자)를 배상하고 포기할 수 있다.","c":"중","v":1},"공인노2019_28-56-1":{"w":"甲과 乙이 짜고 한 허위의 매매는 제108조 제1항에 따라 무효다. 강제집행을 면하려는 목적이 있어도 그 자체로 제103조 위반이 되지는 않는다(판례).","c":"상","v":1},"공인노2019_28-56-2":{"w":"제108조 제2항의 제3자는 특별한 사정이 없으면 선의로 추정되고 제3자의 악의는 무효를 주장하는 쪽이 증명해야 한다(판례).","c":"중","v":1},"공인노2019_28-56-3":{"w":"제108조 제2항은 선의만 요구한다. 판례도 제3자에게 무과실까지 요구하지 않는다.","c":"상","v":1},"공인노2019_28-56-4":{"w":"악의의 제3자에게는 허위표시의 무효로 대항할 수 있다(제108조 제2항 반대해석). 乙 명의 등기는 무효이므로 그에 기초한 丙의 저당권등기도 무효이고 소유자 甲은 제214조에 따라 말소를 청구할 수 있다.","c":"중","v":1},"공인노2019_28-57-3":{"w":"제109조의 중요부분 착오는 표의자가 그 착오가 없었다면 의사표시를 하지 않았을 정도이고 보통 사람도 그랬을 정도여야 한다. 착오로 경제적 불이익을 입지 않았다면 중요부분 착오가 아니라는 것이 판례다.","c":"중","v":1},"공인노2019_28-58-1":{"w":"제118조 제1호에 따라 권한을 정하지 않은 대리인도 보존행위는 제한 없이 할 수 있다.","c":"상","v":1},"공인노2019_28-58-3":{"w":"부동산을 팔 권한을 받은 대리인은 특별한 사정이 없으면 계약 체결뿐 아니라 그에 따른 중도금·잔금 수령 권한도 가진다(판례).","c":"중","v":1},"공인노2019_28-58-4":{"w":"매매계약 체결에 관한 포괄적 대리권에는 특별한 사정이 없으면 약정된 대금의 지급기일을 연장해 주는 권한도 포함된다(판례).","c":"중","v":1},"공인노2019_28-58-5":{"w":"대여금 영수권한만 받은 대리인에게는 채무 면제 같은 처분 권한이 없다. 면제하려면 본인의 특별수권이 있어야 한다(판례).","c":"중","v":1},"공인노2019_28-59-2":{"w":"무권대리행위의 추인권은 본인에게 있다(제130조). 본인에게서 추인에 관한 특별수권을 받은 대리인도 본인을 대리해 추인할 수 있다.","c":"중","v":1},"공인노2019_28-60-1":{"w":"제139조 단서: 무효인 법률행위의 당사자가 무효임을 알고 추인하면 새로운 법률행위로 본다. 소급효는 없다.","c":"상","v":1},"공인노2019_28-61-1":{"w":"소멸시효는 권리를 행사할 수 있는 때부터 진행한다(제166조 제1항). 정지조건부 권리는 조건이 성취되기 전에는 행사할 수 없으므로 그동안 시효가 진행하지 않는다.","c":"중","v":1},"공인노2019_28-61-2":{"w":"제151조 제1항은 조건이 사회질서에 위반하면 「그 법률행위」를 무효로 한다고 정한다. 조건만 떼어 무효로 하고 나머지를 조건 없는 법률행위로 살리지 않는다(판례).","c":"상","v":1},"공인노2019_28-61-3":{"w":"제149조가 조건의 성취가 미정한 권리의무를 일반규정에 의해 처분·상속·보존·담보로 할 수 있게 한다.","c":"상","v":1},"공인노2019_28-61-4":{"w":"제151조 제2항 후단: 법률행위 당시 이미 성취된 조건이 해제조건이면 그 법률행위는 무효다.","c":"상","v":1},"공인노2022_31-55-2":{"w":"이중매매가 제103조 위반이 되려면 제2매수인이 매도인의 배임행위에 적극 가담해야 한다. 계약금만 오가고 이행 착수 전이면 매도인은 제565조에 따라 배액을 상환하고 해제할 수 있어 배임이 성립하지 않으므로 제3자가 적극 유인했어도 반사회질서 행위가 아니다(판례).","c":"중","v":1},"공인노2022_31-55-3":{"w":"보험사고를 가장해 보험금을 부정 취득할 목적으로 맺은 보험계약은 보험제도의 목적을 해치는 것으로 제103조에 따라 무효다. 보험자가 그 목적을 알았는지는 묻지 않는다(판례).","c":"중","v":1},"공인노2022_31-55-4":{"w":"부첩관계의 종료를 해제조건으로 하는 증여는 그 조건만이 아니라 증여계약 자체가 제103조·제151조 제1항에 따라 무효다(판례).","c":"중","v":1},"공인노2022_31-55-5":{"w":"제103조 위반 법률행위는 절대적 무효다. 제107조·제108조처럼 선의의 제3자 보호 규정이 없으므로 선의의 제3자에게도 무효를 주장할 수 있다.","c":"중","v":1},"공인노2022_31-56-5":{"w":"임대차보증금 반환채권 담보 목적의 전세권설정계약은 사용·수익을 배제하지 않더라도 임대차계약과 양립할 수 없는 범위에서는 당사자 사이에 실제 의사가 없으므로 통정허위표시로 무효다(판례). 다만 이를 기초로 새로 이해관계를 맺은 선의의 제3자에게는 대항하지 못한다.","c":"중","v":1},"공인노2022_31-57-1":{"w":"제114조 제1항: 대리인이 그 권한 내에서 본인을 위한 것임을 표시한 의사표시는 직접 본인에게 효력이 생긴다.","c":"상","v":1},"공인노2022_31-57-2":{"w":"제123조 제2항: 복대리인은 본인이나 제3자에 대하여 대리인과 동일한 권리의무가 있다.","c":"상","v":1},"공인노2022_31-57-4":{"w":"제127조 제2호에 따라 대리인의 사망·성년후견 개시·파산은 대리권 소멸사유다. 임의대리·법정대리 모두에 적용된다.","c":"상","v":1},"공인노2022_31-57-5":{"w":"제116조 제2항: 특정한 법률행위를 위임받은 대리인이 본인의 지시대로 행위한 때에는 본인은 자기가 안 사정 또는 과실로 알지 못한 사정에 관하여 대리인의 부지를 주장하지 못한다.","c":"상","v":1},"공인노2022_31-58-2":{"w":"복임권 없는 대리인이 선임한 복대리인의 권한도 원래 대리권 범위를 넘지 않는다. 상대방이 복대리인에게 권한이 있다고 믿을 정당한 이유가 있으면 제126조의 표현대리가 성립할 수 있다(판례).","c":"중","v":1},"공인노2022_31-58-3":{"w":"무권대리행위의 추인은 그 전부에 대해 해야 한다. 일부에 대한 추인이나 내용을 바꾼 추인은 상대방의 동의가 없으면 무효다(판례).","c":"중","v":1},"공인노2022_31-58-4":{"w":"무권대리인이 본인을 단독상속한 뒤 본인 지위에서 추인을 거절하고 무효를 주장하는 것은 금반언·신의칙에 반해 허용되지 않는다(판례).","c":"중","v":1},"공인노2022_31-58-5":{"w":"제135조 제2항: 대리인으로 계약을 맺은 사람이 제한능력자일 때에는 제1항의 이행 또는 손해배상 책임을 지지 않는다.","c":"상","v":1},"공인노2022_31-59-5":{"w":"제141조 단서는 취소된 행위로 받은 이익을 제한능력자가 현존하는 한도에서만 돌려주게 한다. 선의·악의를 묻지 않는다.","c":"상","v":1},"공인노2022_31-61-5":{"w":"제153조 제1항: 기한은 채무자의 이익을 위한 것으로 추정한다. 추정이므로 반대 사정을 증명하면 뒤집힌다.","c":"상","v":1},"공인노2024_33-04-1":{"w":"이행지체로 이미 발생해 확정된 지연손해금채무는 이행기의 정함이 없는 채무다. 그래서 제387조 제2항에 따라 채권자의 이행청구를 받은 때부터 그에 대한 지체책임이 생긴다(판례).","c":"중","v":1},"공인노2024_33-08-1":{"w":"착오가 중요부분의 착오이더라도 법령 개정 등으로 착오에 따른 불이익이 사라졌다면 이를 이유로 취소권을 행사하는 것은 신의칙상 허용되지 않을 수 있다(판례).","c":"중","v":1},"공인노2024_33-09-1":{"w":"제108조의 통정은 표의자가 진의 아닌 표시를 한다는 것을 상대방이 알고 있는 것만으로는 부족하고 그 점에 관해 상대방과 합의가 있어야 한다(판례). 합의 없이 상대방이 알기만 한 경우는 제107조 비진의표시 문제다.","c":"중","v":1},"공인노2024_33-09-2":{"w":"통정허위표시로 무효인 행위도 채무자의 책임재산을 줄이는 외형을 만들므로 사해행위 요건을 갖추면 제406조 채권자취소권의 대상이 된다(판례).","c":"중","v":1},"공인노2024_33-09-3":{"w":"제108조 제2항의 선의의 제3자에게는 허위표시의 당사자뿐 아니라 누구도 허위표시의 무효를 주장하지 못한다(판례). 제3자 보호가 절대적이라는 뜻이다.","c":"중","v":1},"공인노2024_33-09-5":{"w":"가장매매예약이 철회된 뒤 乙이 허위 서류로 한 본등기는 허위표시가 아니라 원인 없는 무효 등기다. 그래서 제108조 제2항이 적용되지 않고 등기에 공신력도 없으므로 선의의 丙도 소유권을 취득하지 못한다(판례).","c":"중","v":1},"공인노2024_33-10-1":{"w":"강박이 극심해 의사결정의 여지를 완전히 박탈당한 상태의 의사표시는 의사 자체가 없어 제110조의 취소 대상이 아니라 무효다(판례).","c":"중","v":1},"공인노2024_33-10-2":{"w":"제110조의 사기는 기망행위가 위법해야 한다. 거래에서 통상 용인되는 정도의 과장 광고처럼 위법성이 없으면 사기로 취소할 수 없다(판례).","c":"중","v":1},"공인노2024_33-10-3":{"w":"강박에 의한 의사표시는 강박자에게 상대방을 공포에 빠뜨리려는 고의와 그 공포로 의사표시를 하게 하려는 고의(2단의 고의)가 있어야 성립한다(통설·판례).","c":"중","v":1},"공인노2024_33-10-5":{"w":"근로계약은 노무 제공이 이미 이뤄진 계속적 관계라서 사기를 이유로 취소해도 소급효가 제한된다. 취소의 의사표시 이후 장래에 관해서만 효력이 소멸한다(판례).","c":"중","v":1},"공인노2024_33-11-2":{"w":"제135조의 무권대리인 책임은 상대방 보호와 거래 안전을 위한 법정 무과실책임이다. 대리권 흠결에 무권대리인의 과실이 없어도 책임을 진다(판례).","c":"중","v":1},"공인노2024_33-14-5":{"w":"강박에 의한 증여는 제110조로 취소할 수 있지만 취소권은 추인할 수 있는 날부터 3년 내에 행사해야 한다(제146조). 乙이 강박에서 벗어난 뒤 5년이 지나 취소권이 소멸했으므로 증여계약은 유효하고 이행하지 않으면 채무불이행 책임을 진다.","c":"중","v":1},"공인노2025_34-06-2":{"w":"불공정한 법률행위인지는 법률행위 당시를 기준으로 판단한다. 계약 뒤 사정 변화로 급부가 불균형해졌다고 해서 제104조가 적용되지 않는다(판례).","c":"중","v":1},"공인노2025_34-06-3":{"w":"급부와 반대급부 사이의 현저한 불균형은 당사자의 주관적 가치가 아니라 거래상 객관적 가치로 판단한다(판례).","c":"중","v":1},"공인노2025_34-06-4":{"w":"제104조 위반 법률행위는 절대적 무효라서 추인으로 유효가 되지 않는다(판례). 무효행위의 전환(제138조)은 인정될 수 있다.","c":"중","v":1},"공인노2025_34-06-5":{"w":"매매계약이 제104조로 무효이면 그 계약과 관련해 맺은 부제소합의도 특별한 사정이 없는 한 같이 무효다(판례).","c":"중","v":1},"공인노2025_34-09-2":{"w":"제117조: 대리인은 행위능력자임을 요하지 아니한다. 대리행위의 효과는 본인에게 귀속하기 때문이다.","c":"상","v":1},"공인노2025_34-09-3":{"w":"대리인이 맺은 계약의 당사자는 본인이므로 계약이 해제되면 원상회복의무도 본인이 진다. 대리인이 대금을 받아 본인에게 넘기지 않았더라도 같다(판례).","c":"중","v":1},"공인노2025_34-09-4":{"w":"대리행위의 효과는 본인에게 귀속하므로(제114조) 의사표시의 하자에 따른 취소권도 본인이 가진다. 대리인은 본인에게서 따로 권한을 받아야 취소할 수 있다.","c":"중","v":1},"공인노2025_34-09-5":{"w":"제123조 제1항: 복대리인은 그 권한 내에서 본인을 대리한다. 대리인의 대리인이 아니라 본인의 대리인이다.","c":"상","v":1},"공인노2025_34-12-1":{"w":"조건은 발생 여부가 불확실한 장래 사실이다. 반드시 실현되는 사실은 시기가 정해지지 않았더라도 불확정기한이고 조건이 아니다(판례).","c":"하","v":1},"공인노2025_34-12-2":{"w":"제388조 제1호: 채무자가 담보를 손상·감소·멸실하게 한 때에는 기한의 이익을 주장하지 못한다.","c":"상","v":1},"공인노2025_34-12-4":{"w":"제153조 제1항: 기한은 채무자의 이익을 위한 것으로 추정한다.","c":"상","v":1},"공인노2025_34-12-5":{"w":"조건은 법률행위의 내용이어야 하므로 조건을 붙이려는 의사가 외부에 표시되어야 한다. 표시되지 않은 의사는 동기에 불과하다(판례).","c":"중","v":1},"공인노2026_35-07-1":{"w":"제104조는 대가 관계가 있는 쌍무적 행위에 적용되고 증여처럼 대가 없는 무상행위에는 적용되지 않는다(판례). 이런 증여는 불공정 법률행위가 아니라 제103조 반사회질서 행위로 무효가 된다.","c":"중","v":1},"공인노2026_35-11-2":{"w":"매도인이 계약을 해제한 뒤에도 매수인은 착오를 이유로 취소해 해제에 따른 손해배상책임 등을 면할 수 있다. 해제와 취소는 요건과 효과가 다르기 때문이다(판례).","c":"중","v":1},"공인노2026_35-11-3":{"w":"재단법인 설립을 위한 출연행위는 상대방 없는 단독행위지만 의사표시이므로 제109조의 착오 취소가 가능하다. 서면으로 출연했다는 사정이 착오 취소를 막지 않는다(판례).","c":"중","v":1},"공인노2026_35-11-4":{"w":"제137조 본문은 일부무효면 전부를 무효로 한다. 무효 부분이 없더라도 법률행위를 했으리라고 인정되는 때에만 나머지가 유효하다(같은 조 단서).","c":"상","v":1},"공인노2026_35-11-5":{"w":"판례는 의사무능력자 보호 필요성이 제한능력자와 같다고 보아 의사무능력으로 무효가 된 경우에도 제141조 단서를 유추해 반환범위를 현존이익으로 한정한다.","c":"중","v":1},"공인노2026_35-13-2":{"w":"혼인·입양·상계처럼 조건을 붙일 수 없는 법률행위에 조건을 붙이면 다른 정함이 없는 한 조건만이 아니라 법률행위 전부가 무효다(판례).","c":"중","v":1},"공인노2026_35-13-3":{"w":"현상광고는 광고에 정한 행위를 완료하면 보수를 지급하는 계약이고(제675조) 그 행위의 완료에 조건을 붙여 조건이 성취될 때 보수 지급 의무가 생기게 할 수 있다(판례).","c":"중","v":1},"공인노2026_35-13-4":{"w":"조건은 당사자의 의사로 붙이는 부관이므로 조건을 붙이려는 의사와 그 의사의 표시가 모두 있어야 한다. 표시되지 않은 의사는 동기에 불과하다(판례).","c":"중","v":1},"공인노2026_35-13-5":{"w":"제147조 제3항: 당사자가 조건성취의 효력을 그 성취 전에 소급하게 할 의사를 표시한 때에는 그 의사에 의한다. 원칙은 성취 때부터 효력이 생긴다(같은 조 제1항·제2항).","c":"상","v":1},"공인노2019_28-54-2":{"w":"종물은 주물의 처분에 따른다는 제100조 제2항은 권리 상호간에도 유추된다. 예컨대 건물에 대한 저당권의 효력은 그 건물을 위한 대지 임차권이나 지상권에도 미친다(판례).","c":"중","v":1},"공인노2022_31-54-1":{"w":"양식장의 뱀장어처럼 구성물이 늘고 줄어도 종류·장소·수량 지정 등으로 특정할 수 있으면 집합물 전체를 하나의 물건으로 보아 양도담보 등의 목적으로 삼을 수 있다(판례).","c":"중","v":1},"공인노2022_31-54-3":{"w":"수목은 원래 토지의 일부지만 입목법에 따른 등기를 하거나 명인방법을 갖추면 토지와 별개의 독립한 물건으로 거래할 수 있다(관습법·판례).","c":"중","v":1},"공인노2022_31-54-4":{"w":"제100조 제1항은 종물을 물건의 소유자가 「자기소유인 다른 물건」을 부속하게 한 것으로 정한다. 그래서 주물과 종물은 원칙적으로 같은 사람의 소유여야 한다.","c":"상","v":1},"공인노2022_31-54-5":{"w":"남의 토지 위 건물의 소유권과 그 건물을 위한 토지임차권 사이에도 주물·종물 법리가 유추된다. 건물이 경매로 넘어가면 매수인은 토지임차권도 함께 취득한다(판례).","c":"중","v":1},"공인노2025_34-05-5":{"w":"제587조는 매매목적물 인도 전에 생긴 과실을 매도인에게 속하게 한다. 매수인이 대금을 다 치르지 않은 동안에는 매도인이 이행지체 중이어도 과실은 매도인에게 귀속하고 매수인은 대금 이자를 내지 않는다(판례).","c":"중","v":1},"공인노2026_35-05-1":{"w":"제98조는 전기 기타 관리할 수 있는 자연력을 물건에 포함한다. 부동산 아닌 물건은 동산이므로(제99조 제2항) 관리할 수 있는 전기는 동산이다.","c":"상","v":1},"공인노2026_35-05-3":{"w":"제102조 제1항: 천연과실은 원물로부터 분리하는 때에 이를 수취할 권리자에게 속한다.","c":"상","v":1},"공인노2026_35-05-4":{"w":"종물은 주물의 처분에 따른다는 제100조 제2항은 임의규정이다. 그래서 당사자는 특약으로 종물만 따로 처분하거나 주물 처분에서 종물을 뺄 수 있다(판례).","c":"중","v":1},"공인노2026_35-05-5":{"w":"법정과실은 「물건」의 사용대가로 받는 금전 등이다(제101조 제2항). 특허권은 물건이 아닌 권리라서 그 사용료는 법정과실이 아니다.","c":"상","v":1},"공인노2017_26-55-2":{"w":"제10조 제2항: 가정법원은 피성년후견인의 법률행위 가운데 취소할 수 없는 범위를 정할 수 있다.","c":"상","v":1},"공인노2019_28-52-1":{"w":"제17조 제2항: 미성년자나 피한정후견인이 속임수로 법정대리인의 동의가 있는 것으로 믿게 한 경우에도 그 행위를 취소할 수 없다.","c":"상","v":1},"공인노2019_28-52-2":{"w":"19세로 성년이 되고(제4조) 나이는 출생일을 산입해 계산한다(제158조). 2018. 12. 1. 출생자는 그날을 1일로 쳐서 2037. 11. 30. 24시에 만 19세가 차므로 2037. 12. 1. 0시에 성년이 된다.","c":"상","v":1},"공인노2019_28-52-3":{"w":"제10조 제4항: 일용품 구입 등 일상생활에 필요하고 그 대가가 과도하지 않은 피성년후견인의 법률행위는 성년후견인이 취소할 수 없다.","c":"상","v":1},"공인노2019_28-52-5":{"w":"제16조 제1항: 제한능력자가 맺은 계약은 추인이 있을 때까지 상대방이 철회할 수 있다. 다만 상대방이 계약 당시 제한능력자임을 알았으면 철회하지 못한다.","c":"상","v":1},"공인노2019_28-53-3":{"w":"종중 재산 분배는 종중총회가 자율적으로 정할 수 있지만 그 내용이 종원의 고유하고 기본적인 권리의 본질을 침해하거나 현저히 불공정하면 결의는 무효다(판례).","c":"중","v":1},"공인노2022_31-52-1":{"w":"제5조 제1항 단서에 따라 권리만 얻거나 의무만 면하는 행위는 법정대리인의 동의가 필요 없다. 채무면제계약 승낙은 의무만 면하는 행위라서 미성년자 혼자 해도 확정적으로 유효하다.","c":"상","v":1},"공인노2022_31-52-2":{"w":"제6조는 법정대리인이 범위를 정해 처분을 허락한 재산을 미성년자가 임의로 처분할 수 있게 한다. 이 허락에는 방식 제한이 없어 묵시적으로도 할 수 있다(판례).","c":"중","v":1},"공인노2022_31-52-3":{"w":"제8조 제1항에 따라 허락받은 영업에 관하여 미성년자는 성년자와 같은 행위능력을 가진다. 그 범위에서는 법정대리인의 동의권뿐 아니라 대리권도 소멸한다(통설).","c":"중","v":1},"공인노2022_31-52-5":{"w":"미성년자는 제140조에 따라 단독으로 취소할 수 있고 이 취소는 확정적으로 유효하다. 그래서 법정대리인이 미성년자의 취소를 다시 취소할 수 없다.","c":"중","v":1},"공인노2022_31-53-3":{"w":"제35조 제1항의 「이사 기타 대표자」에는 대표자로 등기되지 않았더라도 법인을 실질적으로 운영하며 사실상 대표해 사무를 집행하는 사람도 포함된다(판례).","c":"중","v":1},"공인노2024_33-01-1":{"w":"제41조: 이사의 대표권에 대한 제한은 정관에 기재하지 않으면 효력이 없다. 정관에 적은 제한도 등기해야 제3자에게 대항할 수 있다(제60조).","c":"상","v":1},"공인노2024_33-01-2":{"w":"제54조 제1항: 설립등기 이외의 등기사항은 등기한 뒤가 아니면 제3자에게 대항하지 못한다.","c":"상","v":1},"공인노2024_33-01-3":{"w":"재단법인 정관은 변경방법을 정관에 정한 때에만 바꿀 수 있지만(제45조 제1항) 같은 조 제2항은 목적 달성이나 재산 보전을 위해 적당하면 명칭·사무소 소재지를 변경할 수 있게 한다. 주무관청 허가가 필요하다(같은 조 제3항).","c":"상","v":1},"공인노2024_33-01-5":{"w":"정관에 이사 해임사유를 정했다면 이는 법인이 그 사유로만 해임하겠다는 뜻으로 본다. 그래서 중대한 의무위반 등 특별한 사정이 없으면 정관에 없는 사유로 해임할 수 없다(판례).","c":"중","v":1},"공인노2024_33-03-2":{"w":"비법인사단에는 대표권 제한 등기 제도가 없어 제60조를 적용하지 않는다. 대표권 제한을 어긴 거래는 상대방이 그 제한을 알았거나 알 수 있었을 때 사단에 효력이 없다(판례).","c":"중","v":1},"공인노2024_33-03-3":{"w":"제62조는 이사가 정관·총회결의로 금지되지 않은 사항에 한해 「특정한 행위」를 대리하게 할 수 있게 한다. 이 규정은 비법인사단에도 유추되므로 대표자가 사무 전반을 포괄적으로 위임해 한 대행행위는 사단에 효력이 없다(판례).","c":"중","v":1},"공인노2024_33-03-4":{"w":"제63조에 따라 법원이 선임한 임시이사는 원칙적으로 정식 이사와 같은 권한을 가진다(판례). 이 규정은 비법인사단에도 유추된다.","c":"중","v":1},"공인노2024_33-03-5":{"w":"제75조 제1항: 총회의 결의는 법률이나 정관에 다른 규정이 없으면 사원 과반수의 출석과 출석사원 결의권의 과반수로 한다. 비법인사단에도 이 규정이 유추된다.","c":"상","v":1},"공인노2024_33-06-2":{"w":"제8조 제1항에 따라 허락받은 영업에 관하여 미성년자는 성년자와 같은 행위능력을 가진다. 그 범위에서 법정대리인의 동의권과 대리권이 모두 소멸한다(통설).","c":"중","v":1},"공인노2025_34-02-1":{"w":"의사무능력은 법률행위의 효력을 부정하는 사유이므로 무효를 주장하는 쪽이 법률행위 당시 의사능력이 없었다는 것을 증명해야 한다(판례).","c":"중","v":1},"공인노2025_34-02-2":{"w":"판례는 의사무능력자 보호를 위해 제141조 단서를 유추해 의사무능력으로 무효가 된 경우에도 받은 이익을 현존하는 한도에서만 돌려주게 한다.","c":"중","v":1},"공인노2025_34-02-3":{"w":"제14조의2 제2항: 특정후견은 본인의 의사에 반하여 할 수 없다.","c":"상","v":1},"공인노2025_34-02-5":{"w":"제14조의3 제2항: 가정법원이 피성년후견인 또는 피특정후견인에 대해 한정후견개시 심판을 할 때에는 종전의 성년후견 또는 특정후견의 종료 심판을 한다.","c":"상","v":1},"공인노2025_34-03-1":{"w":"정관은 자치법규이므로 그 해석은 법률 해석처럼 객관적으로 해야 한다. 사원총회 결의로 정관의 규범적 의미와 다른 해석을 내놓아도 법원은 그에 구속되지 않는다(판례).","c":"중","v":1},"공인노2025_34-03-2":{"w":"정관에 이사 해임사유를 정했다면 법인은 그 사유로만 해임할 수 있다. 이사의 중대한 의무위반 등 특별한 사정이 없으면 정관에 없는 사유로 해임할 수 없다(판례).","c":"중","v":1},"공인노2025_34-03-4":{"w":"제89조 후단: 청산인은 알고 있는 채권자를 청산으로부터 제외하지 못한다. 채권신고기간 안에 신고하지 않았어도 같다.","c":"상","v":1},"공인노2025_34-03-5":{"w":"민법의 청산절차 규정은 제3자 이해관계와 직결되는 강행규정이다. 이를 어기고 한 잔여재산 처분은 특별한 사정이 없으면 무효다(판례).","c":"중","v":1},"공인노2025_34-04-2":{"w":"제62조: 이사는 정관 또는 총회의 결의로 금지하지 아니한 사항에 한하여 타인으로 하여금 특정한 행위를 대리하게 할 수 있다.","c":"상","v":1},"공인노2025_34-04-3":{"w":"이사의 사임은 원래 법인에 도달하면 효력이 생겨 철회할 수 없다. 다만 정관에 사임 효력발생 시기를 정해 두었다면 그 시기가 오기 전에는 사임 의사를 철회할 수 있다(판례).","c":"중","v":1},"공인노2025_34-04-4":{"w":"이사의 성명·주소는 법인의 등기사항이고(제49조 제2항 제8호) 등기사항에 변경이 있으면 3주간 내에 변경등기를 해야 한다(제52조).","c":"상","v":1},"공인노2025_34-04-5":{"w":"이사들이 공동으로만 대표하게 한 정관 규정은 대표권 제한이다(제49조 제2항 제9호). 제60조에 따라 대표권 제한은 등기하지 않으면 제3자에게 대항하지 못한다.","c":"상","v":1},"공인노2026_35-01-1":{"w":"판례는 관습법을 사회의 거듭된 관행으로 생성한 사회생활규범이 사회의 법적 확신과 인식에 의해 법적 규범으로 승인·강행되기에 이른 것으로 정의한다. 법적 확신이 없으면 사실인 관습에 그친다.","c":"중","v":1},"공인노2026_35-01-2":{"w":"제106조: 법령 중 사회질서와 관계없는 규정(임의규정)과 다른 관습이 있고 당사자의 의사가 명확하지 않으면 그 관습에 의한다. 사실인 관습은 이렇게 법률행위 해석기준이 된다.","c":"상","v":1},"공인노2026_35-01-3":{"w":"고유한 의미의 종중은 공동선조의 후손 가운데 성년인 사람을 구성원으로 하여 자연발생적으로 성립한다(판례). 미성년자는 구성원이 아니다.","c":"중","v":1},"공인노2026_35-01-5":{"w":"민법의 법원은 법률·관습법·조리다(제1조). 사실인 관습은 법적 확신이 없는 관행이라 법원이 아니고 법률행위 해석기준이 될 뿐이다(제106조, 판례).","c":"중","v":1},"공인노2026_35-02-3":{"w":"법인도 권리능력이 있어 유증을 받을 수 있고 포괄적 수증자는 상속인과 같은 권리의무가 있다(제1078조). 포괄적 유증을 받는 데 자연인만이라는 제한은 없다.","c":"중","v":1},"공인노2026_35-03-1":{"w":"제63조의 임시이사 선임은 법인격을 전제로 하지 않는 규정이므로 비법인사단에도 유추적용된다(판례).","c":"중","v":1},"공인노2026_35-03-3":{"w":"비법인사단은 법인등기를 할 수 없으므로 대표권 제한을 등기하지 않으면 대항하지 못한다는 제60조가 적용되지 않는다. 상대방이 제한을 알았거나 알 수 있었는지로 효력을 가린다(판례).","c":"중","v":1},"공인노2026_35-03-4":{"w":"총유물의 관리·처분은 총유물 그 자체에 관한 이용·개량·처분행위를 말한다. 남의 금전채무를 보증하는 행위는 사단이 채무를 부담하는 것일 뿐이어서 이에 해당하지 않으므로 제276조의 총회결의가 없어도 그 이유만으로 무효가 되지 않는다(판례).","c":"중","v":1},"공인노2026_35-03-5":{"w":"종중규약에 특별한 정함이 없으면 종원은 종중총회에 직접 나가지 않고 서면으로 결의권을 행사하거나 대리인을 통해 행사할 수 있다(판례).","c":"중","v":1},"공인노2026_35-04-2":{"w":"제95조: 법인의 해산 및 청산은 법원이 검사·감독한다. 설립과 존속 중 사무는 주무관청이 감독한다(제37조).","c":"상","v":1},"공인노2026_35-04-3":{"w":"제81조: 해산한 법인은 청산의 목적범위 내에서만 권리가 있고 의무를 부담한다. 권리능력은 청산이 끝나야 소멸한다.","c":"상","v":1},"공인노2026_35-04-4":{"w":"제89조: 청산인은 알고 있는 채권자에게 각각 채권신고를 최고해야 하고 알고 있는 채권자는 청산으로부터 제외하지 못한다.","c":"상","v":1},"공인노2026_35-04-5":{"w":"민법의 청산절차 규정은 제3자 이해관계와 직결되는 강행규정이다. 이를 어긴 잔여재산 처분은 특별한 사정이 없으면 무효다(판례).","c":"중","v":1},"공인노2019_28-62-1":{"w":"제164조 제1호: 음식점의 음식료 채권은 1년간 행사하지 않으면 소멸시효가 완성한다.","c":"상","v":1},"공인노2019_28-62-2":{"w":"제184조 제1항은 시효이익을 「미리」 포기하지 못하게 할 뿐이다. 시효가 완성된 뒤에는 포기할 수 있다.","c":"상","v":1},"공인노2019_28-62-4":{"w":"가압류에 의한 시효중단(제168조 제2호)은 가압류 집행보전의 효력이 존속하는 동안 계속된다. 본안에서 승소 확정되어도 가압류 효력이 남아 있으면 중단 효력은 끝나지 않는다(판례).","c":"중","v":1},"공인노2019_28-62-5":{"w":"동시이행항변권이 붙어 있어도 채권자는 자기 채무를 이행 제공하면 언제든 청구할 수 있으므로 매매대금 채권의 소멸시효는 지급기일부터 진행한다(제166조 제1항, 판례).","c":"중","v":1},"공인노2022_31-60-1":{"w":"제158조: 나이는 출생일을 산입하여 만 나이로 계산한다. 초일 불산입 원칙(제157조)의 예외다.","c":"상","v":1},"공인노2022_31-60-3":{"w":"제161조: 기간의 말일이 토요일 또는 공휴일이면 기간은 그 다음 날로 만료한다.","c":"상","v":1},"공인노2022_31-60-4":{"w":"제156조: 기간을 시·분·초로 정한 때에는 즉시로부터 기산한다.","c":"상","v":1},"공인노2022_31-60-5":{"w":"제160조 제1항: 기간을 주·월·연으로 정한 때에는 역(달력)에 의하여 계산한다. 한 달을 30일로 환산하지 않는다.","c":"상","v":1},"공인노2022_31-62-1":{"w":"제165조 제2항은 판결과 같은 효력이 있는 것으로 확정된 채권도 단기시효 대상이라도 시효를 10년으로 한다. 확정된 지급명령은 확정판결과 같은 효력이 있으므로(민사소송법 제474조) 10년이 된다.","c":"상","v":1},"공인노2022_31-62-2":{"w":"같은 목적을 위한 채권이라도 채권마다 별개로 시효가 진행한다. 그래서 하나를 행사해도 특별한 사정이 없으면 다른 채권의 시효는 중단되지 않는다(판례).","c":"중","v":1},"공인노2022_31-62-4":{"w":"최고는 6개월 내에 재판상 청구 등을 해야 중단 효력이 있다(제174조). 최고를 여러 번 했다면 재판상 청구를 한 때부터 거꾸로 6개월 내에 한 최고 때에 시효중단 효력이 생긴다(판례).","c":"중","v":1},"공인노2022_31-62-5":{"w":"계속적 거래로 생긴 여러 금전채무가 있을 때 채무자가 일부를 변제하면 특별한 사정이 없는 한 채무 전부를 승인한 것으로 보아 모두에 시효중단 효력이 생긴다(제168조 제3호, 판례).","c":"중","v":1},"공인노2024_33-05-1":{"w":"제495조는 시효로 소멸한 채권도 소멸 전에 상계할 수 있었으면 상계를 허용한다. 판례는 이를 제척기간이 지난 채권(예: 담보책임에 따른 손해배상채권)에도 유추적용한다.","c":"중","v":1},"공인노2024_33-05-3":{"w":"보증채무는 주채무에 부종하므로 주채무가 시효로 소멸하면 보증인도 이를 원용할 수 있다. 다만 부종성을 부정할 특별한 사정이 있으면 보증인은 주채무 시효소멸을 내세울 수 없다(판례).","c":"중","v":1},"공인노2024_33-05-4":{"w":"제166조 제2항: 부작위를 목적으로 하는 채권의 소멸시효는 위반행위를 한 때로부터 진행한다.","c":"상","v":1},"공인노2024_33-05-5":{"w":"제163조 제3호: 도급받은 자·기사 기타 공사의 설계 또는 감독에 종사하는 자의 공사에 관한 채권은 3년의 단기소멸시효에 걸린다.","c":"상","v":1},"공인노2025_34-13-1":{"w":"제158조 단서: 1세에 이르지 아니한 경우에는 나이를 월수로 표시할 수 있다.","c":"상","v":1},"공인노2025_34-13-2":{"w":"제160조 제1항: 기간을 주·월·연으로 정한 때에는 역에 의하여 계산한다.","c":"상","v":1},"공인노2025_34-13-3":{"w":"제161조: 기간의 말일이 토요일 또는 공휴일에 해당한 때에는 기간은 그 익일로 만료한다.","c":"상","v":1},"공인노2025_34-13-5":{"w":"기간을 거꾸로 셀 때도 민법 기간 계산 규정을 유추해 선거일 당일은 빼고 전날인 2025. 6. 1.을 기산일로 삼는다(제157조). 거기서 3년을 거슬러 올라가면 2022. 6. 2. 0시가 시작점이 된다.","c":"중","v":1},"공인노2025_34-14-2":{"w":"사용자의 보호의무 위반에 따른 근로자의 손해배상청구권은 채무불이행 책임이므로 불법행위의 단기시효(제766조)가 아니라 제162조 제1항의 10년 시효가 적용된다(판례).","c":"중","v":1},"공인노2025_34-15-4":{"w":"시효중단 사유인 승인은 시효이익을 받을 채무자나 그 대리인이 해야 한다. 이행인수인은 채무자와 약정했을 뿐 채무자를 대리하지 않으므로 채권자에게 한 승인에 중단 효력이 없다(판례).","c":"중","v":1},"공인노2026_35-14-2":{"w":"주채무자에 대한 시효중단은 보증인에게도 효력이 있다(제440조). 반대 방향 규정은 없으므로 보증채무에 대한 시효중단은 주채무에 영향을 주지 않는다(판례).","c":"중","v":1},"공인노2026_35-14-3":{"w":"보증채무는 주채무에 부종하므로 주채무가 시효로 소멸하면 보증채무도 소멸한다. 보증채무 자체의 시효가 중단되었더라도 마찬가지이고 보증인은 주채무 시효소멸을 원용할 수 있다(판례).","c":"중","v":1},"공인노2026_35-14-4":{"w":"제183조: 주된 권리의 소멸시효가 완성한 때에는 종속된 권리에 그 효력이 미친다. 원금채권이 시효로 소멸하면 그 전에 생긴 이자·지연손해금 채권도 함께 소멸한다(판례).","c":"상","v":1},"공인노2026_35-14-5":{"w":"시효완성 후 시효이익을 포기하면 그때부터 채권은 다시 행사할 수 있는 상태가 되므로 포기한 때부터 새로 소멸시효가 진행한다(판례).","c":"중","v":1},"공인노2017_26-63-1":{"w":"제492조 제1항에 따라 쌍방 채무의 이행기가 도래해야 상계할 수 있다. 수동채권 A는 2016. 2. 8.에 이미 이행기가 왔고 자동채권 B의 이행기가 2016. 5. 8.이므로 그날부터 乙은 B채권으로 상계할 수 있다.","c":"상","v":1},"공인노2017_26-63-3":{"w":"임금은 직접 전액을 지급해야 하므로(근로기준법 제43조 제1항) 사용자는 근로자에 대한 자기 채권으로 임금채권과 상계하지 못한다(판례). 임금채권의 2분의 1은 압류금지채권이기도 해서 제497조도 상계를 막는다.","c":"중","v":1},"공인노2017_26-63-4":{"w":"제496조는 고의의 불법행위로 인한 채무의 「채무자」가 상계로 대항하지 못하게 한다. 가해자 甲은 수동채권으로 삼아 상계할 수 없지만 피해자 乙이 손해배상채권을 자동채권으로 상계하는 것은 막지 않는다.","c":"상","v":1},"공인노2017_26-63-5":{"w":"압류(가압류) 전에 자동채권을 취득했더라도 압류 당시 자동채권의 변제기가 도래하지 않았고 그 변제기가 수동채권의 변제기보다 늦게 오면 제3채무자는 상계로 압류채권자에게 대항하지 못한다(제498조, 판례). B채권 변제기(5. 8.)가 송달일(4. 15.) 뒤이고 A채권 변제기(2. 8.)보다 늦다.","c":"중","v":1},"공인노2022_31-68-1":{"w":"제496조: 채무가 고의의 불법행위로 인한 것인 때에는 그 채무자는 상계로 채권자에게 대항하지 못한다. 피해자가 현실로 배상받게 하려는 취지다.","c":"상","v":1},"공인노2024_33-25-1":{"w":"변제공탁은 공탁공무원의 수탁처분과 공탁물보관자의 공탁물 수령으로 효력이 생겨 채무가 소멸한다. 채권자의 수익 의사표시나 공탁통지 도달은 효력 요건이 아니다(판례).","c":"중","v":1},"공인노2024_33-25-2":{"w":"기존 채무를 소비대차의 목적으로 하기로 약정한 경우 그것이 경개인지 준소비대차인지는 당사자 의사로 정한다. 의사가 명백하지 않으면 기존 채무의 동일성을 유지하는 준소비대차(제605조)로 본다(판례).","c":"중","v":1},"공인노2024_33-25-3":{"w":"벌금형이 확정되면 벌금채권의 변제기가 도래하므로 법률상 금지 근거가 없는 한 국가는 이를 자동채권으로 하여 상대방의 채권과 상계할 수 있다(판례).","c":"중","v":1},"공인노2024_33-25-4":{"w":"부진정연대채무자 1인이 한 상계는 채권자가 실제로 만족을 얻은 것과 같으므로 그 소멸 효력이 다른 부진정연대채무자에게도 미친다. 채권자와 상계계약을 맺은 경우도 같다(판례).","c":"중","v":1},"공인노2025_34-24-1":{"w":"제494조: 각 채무의 이행지가 다른 경우에도 상계할 수 있다. 다만 상계하는 쪽은 상대방에게 상계로 인한 손해를 배상해야 한다.","c":"상","v":1},"공인노2025_34-24-2":{"w":"상계는 쌍방이 「서로」 같은 종류의 채무를 부담할 때 할 수 있다(제492조 제1항). 그래서 수동채권은 원칙적으로 상대방이 상계자에게 가지는 채권이어야 하고 제3자에 대한 채권과는 상계할 수 없다.","c":"상","v":1},"공인노2025_34-24-3":{"w":"제495조는 시효로 소멸한 채권이 소멸 전에 상계적상에 있었으면 상계를 허용한다. 판례는 이를 제척기간이 지난 채권에도 유추적용한다.","c":"중","v":1},"공인노2025_34-24-4":{"w":"자동채권은 변제기가 도래해야 한다. 그렇지 않으면 상대방의 기한 이익을 일방적으로 빼앗게 되기 때문이다. 반면 수동채권은 상계자가 기한의 이익을 포기할 수 있어 변제기 전이라도 된다(판례).","c":"중","v":1},"공인노2025_34-25-4":{"w":"변제공탁은 채무 전액에 대해 해야 효력이 있다. 일부만 공탁하면 채권자가 수락하지 않는 한 그 부분에 대해서도 변제 효력이 없으므로 나머지 3천만 원만 제공해서는 채무 전부를 이행한 것이 되지 않는다(판례).","c":"중","v":1},"공인노2026_35-26-1":{"w":"일부대위변제자는 변제한 가액에 비례해 채권자와 함께 권리를 행사하므로(제483조 제1항) 채권자는 일부대위변제자에게 저당권 일부이전의 부기등기를 해 줄 의무가 있다(판례).","c":"중","v":1},"공인노2026_35-26-2":{"w":"제483조 제1항에 따라 일부대위변제자는 변제한 가액에 비례해 채권자와 함께 권리를 행사하므로 저당권을 채권자와 준공유하게 된다(판례).","c":"중","v":1},"공인노2026_35-26-3":{"w":"제483조 제2항: 일부대위의 경우 채무불이행을 원인으로 하는 계약의 해지 또는 해제는 채권자만이 할 수 있다.","c":"상","v":1},"공인노2026_35-26-4":{"w":"일부대위변제자와 채권자가 저당권을 준공유하더라도 배당에서는 채권자가 일부대위변제자보다 우선해서 변제받는다(판례). 대위는 채권자를 해치지 않는 범위에서 인정되기 때문이다.","c":"중","v":1},"공인노2026_35-27-2":{"w":"제493조 제1항 후단: 상계의 의사표시에는 조건 또는 기한을 붙이지 못한다. 상계는 소급효가 있어 기한을 붙여도 의미가 없고 조건은 상대방 지위를 불안하게 한다.","c":"상","v":1},"공인노2026_35-27-3":{"w":"제495조: 소멸시효가 완성된 채권이 그 완성 전에 상계할 수 있었던 것이면 그 채권자는 상계할 수 있다.","c":"상","v":1},"공인노2026_35-27-4":{"w":"자동채권에 상대방의 동시이행항변권이 붙어 있으면 상계를 허용할 경우 상대방은 항변권을 잃게 되므로 그런 상계는 허용되지 않는다(제492조 제1항 단서, 판례).","c":"중","v":1},"공인노2026_35-27-5":{"w":"제493조 제2항: 상계의 의사표시는 각 채무가 상계할 수 있는 때에 대등액에 관하여 소멸한 것으로 본다.","c":"상","v":1},"공인노2026_35-32-1":{"w":"제462조: 특정물의 인도가 채권의 목적인 때에는 채무자는 이행기의 현상대로 그 물건을 인도하여야 한다.","c":"상","v":1},"공인노2026_35-32-3":{"w":"제460조 단서: 채권자가 미리 변제받기를 거절하거나 채무 이행에 채권자의 행위가 필요한 경우에는 변제준비 완료를 통지하고 수령을 최고하면 된다(구두제공).","c":"상","v":1},"공인노2026_35-32-4":{"w":"제468조: 당사자의 특별한 의사표시가 없으면 변제기 전이라도 채무자는 변제할 수 있다. 다만 상대방의 손해는 배상해야 한다.","c":"상","v":1},"공인노2026_35-32-5":{"w":"제461조: 변제의 제공은 그때로부터 채무불이행의 책임을 면하게 한다.","c":"상","v":1},"공인노2017_26-64-4":{"w":"하자·미시공 공사를 기한 내에 끝내지 못하면 미지급 공사비를 포기해 도급인의 손해배상금으로 충당한다는 합의는 채무불이행 시 배상액을 미리 정한 것이므로 제398조의 손해배상액 예정에 해당한다(판례).","c":"중","v":1},"공인노2017_26-66-2":{"w":"불확정한 사실의 발생을 이행기한으로 정했다면 그 사실이 발생한 때뿐 아니라 발생이 불가능해진 때에도 기한이 도래한 것으로 본다(판례). 불확정기한은 조건과 달리 채무 자체는 확정되어 있기 때문이다.","c":"중","v":1},"공인노2019_28-63-1":{"w":"손해배상액을 예정하면 채권자는 채무불이행 사실만 증명하면 되고 손해의 발생과 액수는 증명할 필요가 없다(제398조, 판례).","c":"중","v":1},"공인노2019_28-63-2":{"w":"손해배상액의 예정은 채무불이행 책임을 전제로 하므로 특약이 없는 한 채무자는 자기에게 귀책사유가 없음을 증명하면 예정액 지급책임을 면한다(판례).","c":"중","v":1},"공인노2019_28-63-3":{"w":"손해배상액 예정은 손해 발생과 액수에 관한 증명의 곤란을 없애려는 것이므로 채무자가 손해가 생기지 않았다고 증명해도 예정액 지급을 면하지 못한다(판례).","c":"중","v":1},"공인노2019_28-63-4":{"w":"손해배상액을 예정하면 실제 손해가 그보다 크더라도 다른 특약이 없는 한 초과분을 따로 청구할 수 없다(제398조, 판례).","c":"중","v":1},"공인노2019_28-64-3":{"w":"일부청구 소송에서 과실상계는 손해 전액에서 과실비율만큼 감액하고 남은 금액이 청구액을 넘지 않으면 그 잔액을 인용하고 넘으면 청구액을 인용한다(외측설, 판례).","c":"중","v":1},"공인노2022_31-63-2":{"w":"제373조: 금전으로 가액을 산정할 수 없는 것이라도 채권의 목적으로 할 수 있다.","c":"상","v":1},"공인노2022_31-63-3":{"w":"제375조 제2항: 채무자가 이행에 필요한 행위를 완료하거나 채권자의 동의를 얻어 이행할 물건을 지정한 때에는 그때부터 그 물건을 채권의 목적물로 한다.","c":"상","v":1},"공인노2022_31-63-4":{"w":"제374조: 특정물의 인도가 채권의 목적인 때에는 채무자는 그 물건을 인도하기까지 선량한 관리자의 주의로 보존하여야 한다.","c":"상","v":1},"공인노2022_31-63-5":{"w":"금전채무 이행지체에 대비해 지연손해금 비율을 따로 정한 약정은 채무불이행에 따른 배상액을 미리 정한 것이므로 손해배상액의 예정이다. 그래서 부당히 과다하면 제398조 제2항으로 감액할 수 있다(판례).","c":"중","v":1},"공인노2024_33-16-4":{"w":"손해배상액을 예정하면 특별한 사정이 없는 한 통상손해뿐 아니라 특별손해도 예정액에 포함되므로 특별손해를 따로 청구할 수 없다(판례).","c":"중","v":1},"공인노2024_33-18-2":{"w":"「2층 골조공사 완료시」처럼 발생 시기가 확정되지 않은 사실을 기한으로 정한 것은 불확정기한이다. 제387조 제1항 후단에 따라 채무자는 기한이 도래함을 안 때부터 지체책임을 진다.","c":"상","v":1},"공인노2024_33-18-3":{"w":"금전채무 이행지체로 생기는 지연이자는 원본 사용의 대가인 이자가 아니라 채무불이행에 따른 손해배상금이다(제397조, 판례). 그래서 3년 단기시효(제163조 제1호) 대상이 아니다.","c":"중","v":1},"공인노2024_33-18-4":{"w":"매도인의 담보책임에 따른 손해배상채무는 이행기의 정함이 없는 채무이므로 제387조 제2항에 따라 이행청구를 받은 때부터 지체책임을 진다(판례).","c":"중","v":1},"공인노2024_33-18-5":{"w":"이행기 없는 채무는 이행청구를 받은 때부터 지체책임이 생기지만(제387조 제2항) 양수인은 양도통지가 있어야 채무자에게 대항할 수 있다(제450조). 그래서 소송 중 양도통지가 도달하면 그 다음 날부터 지체책임을 진다(판례).","c":"중","v":1},"공인노2025_34-16-1":{"w":"제374조: 특정물의 인도가 채권의 목적인 때에는 채무자는 그 물건을 인도하기까지 선량한 관리자의 주의로 보존하여야 한다.","c":"상","v":1},"공인노2025_34-16-2":{"w":"제397조 제2항: 금전채무불이행의 손해배상에 관하여 채권자는 손해의 증명을 요하지 않고 채무자는 과실 없음을 항변하지 못한다.","c":"상","v":1},"공인노2025_34-16-4":{"w":"제380조: 다른 법률의 규정이나 당사자의 약정이 없으면 선택채권의 선택권은 채무자에게 있다.","c":"상","v":1},"공인노2025_34-16-5":{"w":"제385조 제1항: 선택할 수개의 행위 중 처음부터 불능한 것이나 후에 불능이 된 것이 있으면 채권의 목적은 잔존한 것에 존재한다.","c":"상","v":1},"공인노2025_34-17-1":{"w":"이행지체로 이미 확정된 지연손해금채무는 이행기의 정함이 없는 채무다. 제387조 제2항에 따라 채권자의 이행청구를 받은 때부터 그 지연손해금에 대한 지체책임이 생긴다(판례).","c":"중","v":1},"공인노2025_34-18-1":{"w":"손해배상액을 예정하면 실제 손해가 더 커도 특약이 없는 한 예정액을 넘는 배상을 청구할 수 없다(제398조, 판례).","c":"중","v":1},"공인노2025_34-18-2":{"w":"예정액이 부당히 과다한지와 감액 비율은 법원이 여러 사정을 참작해 정하는 것으로(제398조 제2항) 형평에 반해 현저히 불합리하지 않으면 사실심의 전권에 속한다(판례).","c":"중","v":1},"공인노2025_34-18-3":{"w":"손해배상액을 예정하면 손해 발생과 액수의 증명은 필요 없지만 배상청구의 전제인 채무불이행 사실은 채권자가 증명해야 한다(판례).","c":"중","v":1},"공인노2025_34-18-5":{"w":"지체상금을 계약 총액에 지체상금률을 곱해 산출하기로 했다면 부당히 과다한지(제398조 제2항)는 지체상금률이 아니라 실제로 산출된 지체상금 총액을 기준으로 판단한다(판례).","c":"중","v":1},"공인노2026_35-16-1":{"w":"불법행위로 인한 손해배상채무는 이행최고가 없어도 불법행위 성립과 동시에 지체에 빠지므로 그때부터 지연손해금이 발생한다(판례).","c":"중","v":1},"공인노2026_35-16-2":{"w":"채무의 내용에 좇은 이행을 하지 않으면(제390조) 그 사실 자체가 채무자에게 위법한 것으로 평가되므로 채권자가 위법성을 따로 증명할 필요가 없다(판례).","c":"중","v":1},"공인노2026_35-16-3":{"w":"제391조의 이행보조자는 채무자의 의사관여 아래 채무 이행행위에 속하는 활동을 하는 사람이면 되고 채무자와 계약관계가 있을 필요가 없다. 호의로 했더라도 채무자가 용인했다면 이행보조자다(판례).","c":"중","v":1},"공인노2026_35-16-5":{"w":"채무불이행책임과 불법행위책임은 별개의 청구권이므로(청구권 경합) 계약상 채무불이행책임만 면제하기로 한 특약은 특별한 사정이 없는 한 불법행위책임에는 미치지 않는다(판례).","c":"중","v":1},"공인노2026_35-17-1":{"w":"남의 권리를 목적으로 한 증여도 유효하고 증여자는 그 권리를 취득해 이전할 의무를 진다. 그래서 권리가 타인에게 있다는 사정만으로 이행불능이 되지 않는다(판례).","c":"중","v":1},"공인노2026_35-17-3":{"w":"가압류 집행이 되어 있어도 처분 자체가 금지되는 것이 아니어서 소유권이전등기를 할 수 있다. 그래서 그것만으로 매도인의 소유권이전의무가 이행불능이 되지 않는다(판례).","c":"중","v":1},"공인노2026_35-17-4":{"w":"일부만 불능이더라도 나머지 이행만으로 계약 목적을 달성할 수 없으면 채무 전부가 불능인 것으로 다룬다(판례). 그러면 채권자는 계약 전부를 해제할 수 있다.","c":"중","v":1},"공인노2026_35-17-5":{"w":"대상청구권은 불능이 된 급부에 갈음하는 이익을 상대방이 이행하는 것을 전제로 한다. 쌍방의 급부가 모두 불능이 되면 상대방에게 반대급부를 할 수 없으므로 특별한 사정이 없으면 대상청구권을 행사할 수 없다(판례).","c":"중","v":1},"공인노2026_35-18-1":{"w":"채무불이행으로 인한 손해배상청구권은 본래 채권이 모습을 바꾼 것이므로 그 소멸시효는 채무불이행이 생긴 때부터 진행한다(제166조 제1항, 판례).","c":"중","v":1},"공인노2026_35-18-2":{"w":"손해배상액을 예정한 경우 채권자의 과실은 제398조 제2항의 감액 사유로 고려될 뿐 과실상계(제396조)는 할 수 없다(판례).","c":"중","v":1},"공인노2026_35-18-3":{"w":"재산적 손해액을 확정할 수 있는데도 위자료 명목으로 재산적 손해를 사실상 메우게 하는 것은 허용되지 않는다(판례). 위자료의 보완적 기능은 재산적 손해의 증명이 곤란할 때에만 인정된다.","c":"중","v":1},"공인노2026_35-18-4":{"w":"계약을 해제하고 손해배상을 청구할 때 이행이익 대신 신뢰이익을 청구할 수 있으나 그 신뢰이익은 계약이 이행되었더라면 얻었을 이행이익의 범위를 넘을 수 없다(판례).","c":"중","v":1},"공인노2026_35-24-1":{"w":"임차인은 계약이 끝나면 빌린 바로 그 물건을 돌려줘야 하므로 임차목적물 반환채무는 특정물채무다(제654조·제615조).","c":"중","v":1},"공인노2026_35-24-2":{"w":"제383조 제1항: 제3자가 선택하는 경우에는 그 선택은 채무자 및 채권자에 대한 의사표시로 한다.","c":"상","v":1},"공인노2026_35-24-3":{"w":"제397조 제2항: 금전채무불이행의 손해배상에 관하여 채권자는 손해의 증명을 요하지 않는다.","c":"상","v":1},"공인노2026_35-24-4":{"w":"금전채무에 관해 지연손해금 비율을 따로 정한 약정은 이행지체 시 배상액을 미리 정한 것이므로 손해배상액의 예정이다. 그래서 제398조 제2항의 감액 대상이 된다(판례).","c":"중","v":1},"공인노2017_26-67-2":{"w":"토지거래허가 전 매수인이 매도인에게 가지는 허가신청 절차 협력청구권은 매수인의 재산적 권리이므로 매수인의 채권자가 이를 대위행사할 수 있다(판례).","c":"중","v":1},"공인노2017_26-69-3":{"w":"피보전채권은 원칙적으로 사해행위 전에 성립해야 한다. 다만 사해행위 당시 채권 성립의 기초가 되는 법률관계가 이미 있었고 가까운 장래에 채권이 성립할 고도의 개연성이 있으며 실제로 성립했다면 그 채권도 피보전채권이 된다(판례).","c":"중","v":1},"공인노2019_28-65-1":{"w":"채권자대위소송에서 제3채무자는 채무자가 채권자에게 가지는 항변을 원용할 수 없다. 그래서 甲의 乙에 대한 채권이 시효로 소멸했더라도 丙은 그 시효를 원용하지 못한다(판례).","c":"중","v":1},"공인노2019_28-65-2":{"w":"채권자는 채무자의 권리를 그대로 행사하는 것이므로 제3채무자는 채무자에게 대항할 수 있는 동시이행항변권 등으로 채권자에게도 대항할 수 있다(판례).","c":"중","v":1},"공인노2019_28-65-4":{"w":"제404조 제2항: 채권자는 채권의 기한이 도래하기 전에는 법원의 허가 없이 대위권을 행사하지 못한다. 법원 허가를 받으면 이행기 전에도 행사할 수 있다(보존행위는 허가 불요).","c":"상","v":1},"공인노2019_28-65-5":{"w":"금전이나 물건의 인도를 구하는 대위소송에서는 채권자가 제3채무자에게 직접 자기에게 이행하라고 청구해 대위수령할 수 있다(판례).","c":"중","v":1},"공인노2019_28-66-2":{"w":"사해행위 취소와 원상회복 청구는 함께 할 수도 있지만 취소를 먼저 청구하고 원상회복은 나중에 청구할 수도 있다(판례). 다만 취소청구는 제406조 제2항의 제척기간 안에 해야 한다.","c":"중","v":1},"공인노2019_28-66-3":{"w":"우선변제권 있는 채권자에게 그 담보물로 대물변제하면 그 채권자는 원래 그 재산에서 우선 변제받을 지위에 있었으므로 일반채권자의 공동담보를 줄이지 않아 원칙적으로 사해행위가 아니다(판례).","c":"중","v":1},"공인노2019_28-66-4":{"w":"사해행위 취소는 채권자와 수익자(전득자) 사이에서만 상대적으로 효력이 있으므로 취소소송의 피고는 수익자나 전득자이고 채무자는 피고적격이 없다(판례).","c":"중","v":1},"공인노2019_28-66-5":{"w":"채권자취소권의 제척기간(제406조 제2항) 경과는 권리 소멸을 주장하는 쪽, 곧 취소소송의 상대방(수익자·전득자)이 증명해야 한다(판례).","c":"중","v":1},"공인노2022_31-65-1":{"w":"피보전권리는 금전채권에 한하지 않는다. 소유권에 기한 방해배제청구권 같은 물권적 청구권도 채권자대위권의 피보전권리가 될 수 있다(판례).","c":"중","v":1},"공인노2022_31-65-2":{"w":"채권자취소권 대위행사는 보존행위가 아니므로 이행기 전에는 제404조 제2항에 따라 법원의 허가를 얻어야 대위행사할 수 있다. 허가를 받으면 이행기 전에도 가능하다.","c":"중","v":1},"공인노2022_31-65-4":{"w":"제404조 제1항 단서: 채무자의 일신에 전속한 권리는 대위행사할 수 없다. 여기서 일신전속권은 행사상 일신전속권을 말한다.","c":"상","v":1},"공인노2022_31-65-5":{"w":"피보전채권이 존재하지 않으면 채권자는 대위할 당사자적격이 없어 소가 부적법해진다. 그래서 피보전채권의 존재 여부는 법원이 직권으로 조사할 사항이다(판례).","c":"중","v":1},"공인노2025_34-19-2":{"w":"피보전채권이 사해행위 전에 성립했다면 그 채권을 양수한 사람은 대항요건을 사해행위 뒤에 갖추었더라도 채권자취소권을 행사할 수 있다(판례). 채권 성립 시기가 기준이고 대항요건 구비 시기는 문제되지 않는다.","c":"중","v":1},"공인노2026_35-20-4":{"w":"금전채권을 대위행사할 때 채권자는 제3채무자에게 채무자가 아닌 자기에게 직접 지급하라고 청구할 수 있다(판례). 다만 대위채권자가 받은 금전도 채무자의 책임재산이 된다.","c":"중","v":1},"공인노2026_35-21-4":{"w":"사해행위인지 가리려면 채무자의 책임재산이 채무 총액에 부족한지를 보는데 압류금지재산은 강제집행의 대상이 되지 않아 공동담보가 아니므로 적극재산에서 뺀다(판례).","c":"중","v":1},"공인노2017_26-70-5":{"w":"제444조 제2항: 주채무자의 의사에 반하여 보증인이 된 자가 자기의 출재로 주채무를 소멸하게 한 때에는 주채무자는 현존이익의 한도에서 배상한다. 부탁 없이 보증인이 된 경우는 그 당시 이익을 받은 한도다(같은 조 제1항).","c":"상","v":1},"공인노2019_28-67-1":{"w":"임금은 근로자에게 직접 지급해야 하므로(근로기준법 제43조 제1항) 근로자가 임금채권을 양도했더라도 사용자는 근로자에게 직접 임금을 지급해야 한다. 그래서 양수인이 사용자에게 직접 지급을 청구할 수 없다(판례).","c":"중","v":1},"공인노2019_28-67-2":{"w":"보증채권은 주채권을 담보하는 종된 채권이어서 주채권과 함께 이전한다(수반성). 주채권과 떼어 보증채권만 양도하는 약정은 효력이 없다(판례).","c":"중","v":1},"공인노2019_28-67-3":{"w":"제452조 제2항은 양도통지를 양수인의 동의 없이 철회하지 못하게 한다. 이 취지에 따라 양도계약이 해제되었을 때 양도인이 다시 채무자에게 대항하려면 양수인이 채무자에게 해제 사실을 통지해야 한다(판례).","c":"중","v":1},"공인노2019_28-67-5":{"w":"조합재산은 조합원의 합유이므로(제704조) 조합채권의 처분에는 조합원 전원의 동의가 필요하다(제272조). 2인 조합에서 1인이 다른 조합원의 동의 없이 한 조합채권 양도는 무효다(판례).","c":"중","v":1},"공인노2019_28-68-3":{"w":"면책적 채무인수는 채무의 동일성을 유지한 채 인수인에게 채무가 이전하는 것이어서 채무가 소멸하지 않는다. 그래서 채무자 자신이 제공한 저당권은 당연히 소멸하지 않는다. 제459조로 소멸하는 것은 제3자가 제공한 담보와 보증이다.","c":"중","v":1},"공인노2022_31-64-3":{"w":"제416조: 어느 연대채무자에 대한 이행청구는 다른 연대채무자에게도 효력이 있다. 그래서 채권자 A가 甲에게 청구해 생긴 시효중단 효력이 乙에게도 미친다.","c":"상","v":1},"공인노2022_31-66-1":{"w":"중첩적 채무인수는 채무자가 면책되지 않고 인수인이 채무를 더 부담하는 것이어서 채무자에게 불이익이 없다. 그래서 채권자와 인수인의 합의만으로 채무자의 의사에 반해서도 할 수 있다(판례).","c":"중","v":1},"공인노2022_31-66-3":{"w":"면책적 인수인지 중첩적 인수인지 분명하지 않으면 채권자에게 더 유리한 중첩적 채무인수로 본다(판례).","c":"중","v":1},"공인노2022_31-66-4":{"w":"제458조: 인수인은 전채무자의 항변할 수 있는 사유로 채권자에게 대항할 수 있다. 채무가 동일성을 유지한 채 이전하기 때문이다.","c":"상","v":1},"공인노2022_31-66-5":{"w":"제459조: 전채무자의 채무에 대한 보증이나 제3자가 제공한 담보는 채무인수로 소멸한다. 보증인이나 제3자가 채무인수에 동의하면 소멸하지 않는다.","c":"상","v":1},"공인노2024_33-23-1":{"w":"제451조 제1항이 이의를 보류하지 않은 승낙으로 차단하는 것은 양도인에게 대항할 수 있던 사유뿐이다. 채권이 이미 다른 사람에게 양도되었다는 사실은 그런 항변이 아니어서 승낙 뒤에도 양수인에게 주장할 수 있다(판례).","c":"중","v":1},"공인노2024_33-23-2":{"w":"보증채무는 주채무에 수반하므로 주채권이 양도되면 보증채권도 함께 이전한다. 주채무자에게 대항요건을 갖추면 보증인에게 따로 통지하지 않아도 대항할 수 있다(판례).","c":"중","v":1},"공인노2024_33-23-4":{"w":"제449조 제2항 단서의 선의의 제3자는 양도금지특약을 몰랐던 사람이다. 판례는 중과실로 몰랐으면 악의와 같이 보지만 경과실로 몰랐으면 선의로 보호한다.","c":"중","v":1},"공인노2024_33-23-5":{"w":"양도금지특약은 당사자의 합의로 압류금지 재산을 만드는 결과가 되면 안 되므로 특약이 있는 채권도 압류·전부명령으로 이전할 수 있다. 압류채권자가 특약을 알았더라도 같다(판례).","c":"중","v":1},"공인노2024_33-24-2":{"w":"이행인수인은 채무자에게 채무를 대신 변제할 의무를 지므로 변제할 정당한 이익이 있는 사람이다. 그래서 자기 출연으로 변제하면 제481조에 따라 당연히 채권자를 대위한다(판례).","c":"중","v":1},"공인노2025_34-21-1":{"w":"사정변경에 따른 보증계약 해지는 채무액과 변제기가 특정되지 않은 계속적 보증에 인정된다. 이사 재직 중 채무액과 변제기가 특정된 회사 채무를 보증한 경우에는 이사를 사임해도 해지할 수 없다(판례).","c":"중","v":1},"공인노2025_34-22-3":{"w":"대항요건을 갖추지 않았어도 양수인은 채권을 이전받은 권리자이므로 그가 채무자를 상대로 한 재판상 청구는 제168조 제1호의 시효중단 사유가 된다(판례).","c":"중","v":1},"공인노2025_34-23-1":{"w":"제454조 제2항: 채무자와 인수인의 계약에 의한 채무인수에서 채권자의 승낙 또는 거절의 상대방은 채무자나 제3자(인수인)이다.","c":"상","v":1},"공인노2025_34-23-3":{"w":"채무를 인수하는 행위는 인수인이 그 채무의 존재를 인정하는 것이므로 시효중단 사유인 승인(제168조 제3호)이 된다. 그래서 인수채무의 소멸시효는 채무인수일부터 새로 진행한다(판례).","c":"중","v":1},"공인노2025_34-23-4":{"w":"채무자와 인수인의 계약에 의한 인수는 채권자의 승낙으로 효력이 생기는데(제454조 제1항) 채권자가 일단 승낙을 거절하면 인수는 확정적으로 효력을 잃는다. 그 뒤에 다시 승낙해도 효력이 생기지 않는다(판례).","c":"중","v":1},"공인노2025_34-23-5":{"w":"제453조 제2항은 이해관계 없는 제3자만 채무자의 의사에 반해 인수하지 못하게 한다. 보증인은 변제할 이해관계가 있는 사람이므로 채무자의 의사에 반해서도 채권자와 계약해 채무를 인수할 수 있다.","c":"상","v":1},"공인노2026_35-22-1":{"w":"제408조: 채무자가 여럿이면 특별한 의사표시가 없는 한 각자 균등한 비율로 의무를 부담한다(분할채무 원칙).","c":"상","v":1},"공인노2026_35-22-2":{"w":"여러 사람이 공동으로 남의 재산을 사용해 얻은 이익을 반환할 채무는 그 성질상 불가분채무다(판례). 그래서 각자 이득 전부를 반환할 의무가 있다.","c":"중","v":1},"공인노2026_35-22-3":{"w":"제411조가 불가분채무에 연대채무의 구상권 규정인 제425조를 준용한다. 그래서 출재로 공동면책시킨 불가분채무자는 다른 채무자의 부담부분에 대해 구상할 수 있다.","c":"상","v":1},"공인노2026_35-22-5":{"w":"제418조 제1항: 어느 연대채무자가 채권자에 대한 채권으로 상계한 때에는 채권은 모든 연대채무자의 이익을 위하여 소멸한다(상계의 절대효).","c":"상","v":1},"공인노2026_35-23-1":{"w":"장래 채권도 양도 당시 기본적 채권관계가 어느 정도 확정되어 권리를 특정할 수 있고 가까운 장래에 발생할 것이 상당히 기대되면 양도할 수 있다(판례).","c":"중","v":1},"공인노2026_35-23-2":{"w":"보증채권은 주채권에 수반하는 종된 채권이어서 주채권과 함께 이전한다. 주채권과 분리해 보증채권만 양도하기로 한 약정은 효력이 없다(판례).","c":"중","v":1},"공인노2026_35-23-4":{"w":"채권양도 통지는 양도 사실을 알리는 관념의 통지일 뿐 채무자의 재산을 처분하는 법률행위가 아니다. 그래서 양도행위 자체가 사해행위가 아니라면 통지만 따로 떼어 채권자취소권의 대상으로 삼을 수 없다(판례).","c":"중","v":1},"공인노2026_35-23-5":{"w":"양도통지는 양수인의 동의 없이 철회하지 못한다(제452조 제2항). 이에 따라 양도계약이 해제되어 양도인이 다시 채무자에게 대항하려면 양수인이 채무자에게 해제 사실을 통지해야 한다(판례).","c":"중","v":1},"공인노2019_28-70-1":{"w":"약정해제권 행사는 채무불이행을 전제로 하지 않으므로 특약이 없는 한 해제 효과로 손해배상을 청구할 수 없다(판례). 제551조의 손해배상은 채무불이행을 이유로 한 해제에 관한 것이다.","c":"중","v":1},"공인노2019_28-70-2":{"w":"제548조 제1항 단서의 제3자는 해제된 계약을 기초로 새 법률관계를 맺고 등기·인도 등 완전한 권리를 취득한 사람이다. 해제로 소멸하는 계약상 채권 자체를 양수한 사람은 이에 해당하지 않는다(판례).","c":"중","v":1},"공인노2019_28-70-3":{"w":"제548조 제2항: 해제로 원상회복할 때 반환할 금전에는 그 받은 날로부터 이자를 가하여야 한다.","c":"상","v":1},"공인노2019_28-70-4":{"w":"채무자가 미리 이행하지 않을 의사를 명백히 표시하면(이행거절) 채권자는 최고나 자기 채무의 이행제공 없이 곧바로 해제할 수 있다(제544조 단서, 판례).","c":"중","v":1},"공인노2022_31-69-1":{"w":"청약은 상대방 있는 의사표시지만 자동판매기 설치나 현상광고처럼 불특정 다수인에게도 할 수 있다(통설·판례). 승낙은 특정한 청약자에게 해야 한다.","c":"중","v":1},"공인노2022_31-69-2":{"w":"제532조: 청약자의 의사표시나 관습에 의하여 승낙의 통지가 필요하지 않은 경우에는 계약은 승낙의 의사표시로 인정되는 사실이 있는 때에 성립한다(의사실현).","c":"상","v":1},"공인노2022_31-69-3":{"w":"제111조 제2항: 의사표시자가 통지를 발송한 후 사망하거나 제한능력자가 되어도 의사표시의 효력에 영향을 미치지 아니한다.","c":"상","v":1},"공인노2022_31-69-5":{"w":"제533조: 당사자 사이에 동일한 내용의 청약이 상호교차된 경우에는 양 청약이 상대방에게 도달한 때에 계약이 성립한다.","c":"상","v":1},"공인노2022_31-70-2":{"w":"제3자를 위한 계약에서 수익의 의사표시를 한 제3자는 낙약자에게 직접 이행을 청구할 수 있고(제539조) 낙약자의 채무불이행으로 손해를 입으면 그 배상도 직접 청구할 수 있다(판례). 하자 있는 목적물로 생긴 손해도 같다.","c":"중","v":1},"공인노2024_33-26-2":{"w":"제529조: 승낙의 기간을 정하지 아니한 청약은 청약자가 상당한 기간 내에 승낙의 통지를 받지 못한 때에는 그 효력을 잃는다.","c":"상","v":1},"공인노2024_33-27-1":{"w":"제535조 제1항·제2항: 목적이 불능한 계약을 맺을 때 불능을 알았거나 알 수 있었던 사람은 상대방이 계약의 유효를 믿어 입은 손해(신뢰이익)를 배상해야 한다. 상대방이 불능을 알았거나 알 수 있었으면 적용되지 않으므로 상대방은 선의·무과실이어야 한다.","c":"상","v":1},"공인노2024_33-27-3":{"w":"제535조는 목적이 원시적으로 불능인 계약에 관한 규정이다. 의사 불합치로 계약이 아예 성립하지 않은 경우에는 이를 유추적용할 수 없다(판례).","c":"중","v":1},"공인노2024_33-27-4":{"w":"수량을 지정한 매매에서 면적이 모자라면 매수인은 제574조의 담보책임으로 대금 감액 등을 구할 수 있다. 이 경우 미달 부분이 원시적 불능이라며 제535조의 계약체결상 과실책임을 따로 물을 수는 없다(판례).","c":"중","v":1},"공인노2024_33-27-5":{"w":"계약 체결에 대한 정당한 기대를 갖게 해 놓고 상당한 이유 없이 교섭을 파기하면 신의칙에 반하는 위법행위로서 제750조의 불법행위가 된다(판례).","c":"중","v":1},"공인노2024_33-28-1":{"w":"동시이행관계에 있던 채무 하나가 이행불능으로 손해배상채무로 바뀌어도 채무의 동일성이 유지되므로 다른 채무와 여전히 동시이행관계에 있다(판례).","c":"중","v":1},"공인노2024_33-28-2":{"w":"선이행의무인 중도금 지급을 지체한 채 계약이 해제되지 않고 잔대금 지급기일이 오면 중도금과 그 지연손해금, 잔대금 지급의무가 매도인의 소유권이전의무와 동시이행관계가 된다(판례).","c":"중","v":1},"공인노2024_33-28-3":{"w":"제536조 제2항: 선이행의무자라도 상대방의 이행이 곤란할 현저한 사유가 있으면 상대방이 이행을 제공할 때까지 자기 채무의 이행을 거절할 수 있다(불안의 항변권).","c":"상","v":1},"공인노2024_33-28-4":{"w":"동시이행항변권이 있으면 그 존재 자체로 이행지체의 위법성이 없다. 그래서 이행기가 와도 상대방이 이행을 제공하기 전에는 지체책임을 지지 않는다(판례).","c":"중","v":1},"공인노2024_33-29-1":{"w":"제3자의 권리는 요약자와 낙약자 사이의 기본관계를 바탕으로 하므로 요약자는 낙약자의 채무불이행을 이유로 제3자의 동의 없이 계약을 해제할 수 있다(판례). 제541조가 막는 것은 당사자의 합의에 의한 변경·소멸이다.","c":"중","v":1},"공인노2024_33-29-2":{"w":"제542조: 채무자(낙약자)는 제539조의 계약에 기한 항변으로 그 계약의 이익을 받을 제3자에게 대항할 수 있다.","c":"상","v":1},"공인노2024_33-29-3":{"w":"계약 당사자 한쪽이 제3자에게 가진 채권에 관해 그 채무를 면제하기로 하는 계약도 제3자에게 이익을 주는 것이므로 제3자를 위한 계약에 준하는 것으로 유효하다(판례).","c":"중","v":1},"공인노2024_33-29-5":{"w":"채무자와 인수인 사이의 중첩적 채무인수계약은 채권자에게 인수인에 대한 새 채권을 취득하게 하는 것이므로 제3자를 위한 계약이다(판례). 채권자의 수익의 의사표시로 효력이 생긴다.","c":"중","v":1},"공인노2025_34-27-3":{"w":"중도금을 기일에 내지 않으면 최고 없이 해제된다는 특약이 있으면 중도금 미지급만으로 계약은 자동으로 해제된다(판례). 매도인의 이행제공이 필요한 잔금 지급 특약과 다르다.","c":"중","v":1},"공인노2025_34-28-1":{"w":"계약 체결 당시 이미 목적물이 멸실했으면 원시적 불능으로 계약이 무효다. 위험부담(제537조·제538조)은 유효한 계약 성립 뒤 후발적 불능이 생긴 경우의 문제다.","c":"중","v":1},"공인노2025_34-28-2":{"w":"체결 당시 목적물이 이미 멸실된 매매는 원시적 불능으로 무효이므로 매수인이 낸 대금은 법률상 원인이 없는 이득이 된다. 매수인은 제741조에 따라 반환을 청구할 수 있다.","c":"중","v":1},"공인노2025_34-28-3":{"w":"제535조 제2항에 따라 상대방이 불능을 알았거나 알 수 있었을 때에는 계약체결상 과실책임이 생기지 않는다. 과실로 멸실을 몰랐던 매수인은 알 수 있었던 사람이므로 이 책임을 물을 수 없다.","c":"상","v":1},"공인노2025_34-28-4":{"w":"제538조 제1항 후단: 채권자의 수령지체 중에 당사자 쌍방의 책임 없는 사유로 이행할 수 없게 된 때에도 채무자는 상대방의 이행을 청구할 수 있다. 그래서 매도인은 대금을 청구할 수 있다.","c":"상","v":1},"공인노2025_34-29-1":{"w":"계약 당사자 한쪽이 제3자에게 가진 채권에 관해 그 채무를 면제하도록 하는 합의도 제3자에게 이익을 주는 것이므로 제3자를 위한 계약에 준하는 것으로 유효하다(판례).","c":"중","v":1},"공인노2026_35-28-1":{"w":"채무자 甲의 책임 있는 사유로 특정물 인도가 불능이 되면 甲은 제390조에 따라 이행불능에 의한 손해배상책임을 진다.","c":"상","v":1},"공인노2026_35-28-2":{"w":"제546조: 채무자의 책임 있는 사유로 이행이 불능하게 된 때에는 채권자는 최고 없이 계약을 해제할 수 있다.","c":"상","v":1},"공인노2026_35-28-3":{"w":"제538조 제1항 전단: 쌍무계약에서 채무가 채권자의 책임 있는 사유로 이행할 수 없게 된 때에는 채무자는 상대방의 이행을 청구할 수 있다. 그래서 甲은 乙에게 대금을 청구할 수 있다.","c":"상","v":1},"공인노2026_35-28-5":{"w":"제537조: 쌍무계약에서 한쪽 채무가 쌍방의 책임 없는 사유로 이행할 수 없게 되면 채무자는 상대방의 이행을 청구하지 못한다(채무자 위험부담). 그래서 甲은 대금을 청구할 수 없다.","c":"상","v":1},"공인노2026_35-30-1":{"w":"법정해제권은 계약 목적 달성에 필요한 주된 채무의 불이행이 있어야 생긴다. 부수적 채무를 어긴 것만으로는 특별한 사정이 없는 한 계약을 해제할 수 없다(판례).","c":"중","v":1},"공인노2026_35-30-2":{"w":"제543조 제2항: 해지 또는 해제의 의사표시는 철회하지 못한다. 의사표시는 상대방에게 도달하면 효력이 생기므로(제111조 제1항) 도달 뒤에는 철회할 수 없다.","c":"상","v":1},"공인노2026_35-30-3":{"w":"해제와 함께 청구하는 손해배상(제551조)은 채무불이행으로 인한 것이므로 계약이 이행되었더라면 얻었을 이익, 곧 이행이익의 배상이 원칙이다(판례).","c":"중","v":1},"공인노2026_35-30-4":{"w":"최고를 하면서 기간 안에 이행하지 않으면 따로 해제 의사표시 없이 해제된다고 미리 밝혔다면 이는 정지조건부 해제의 의사표시다. 그래서 최고기간이 지나면 계약은 해제된다(판례).","c":"중","v":1},"공인노2017_26-73-3":{"w":"임대인은 목적물을 사용·수익에 필요한 상태로 유지할 의무가 있으므로(제623조) 수선 공사로 사용·수익에 지장이 생기면 임차인은 그 지장의 한도에서 차임 지급을 거절할 수 있다(판례).","c":"중","v":1},"공인노2019_28-71-1":{"w":"제682조 제1항: 수임인은 위임인의 승낙이나 부득이한 사유 없이 제3자로 하여금 자기에 갈음하여 위임사무를 처리하게 하지 못한다.","c":"상","v":1},"공인노2019_28-71-2":{"w":"제683조: 수임인은 위임인의 청구가 있는 때에는 위임사무의 처리상황을 보고하고 위임이 종료한 때에는 지체 없이 그 전말을 보고하여야 한다.","c":"상","v":1},"공인노2019_28-71-3":{"w":"위임은 각 당사자가 언제든지 해지할 수 있고(제689조 제1항) 손해배상은 부득이한 사유 없이 상대방에게 불리한 시기에 해지한 때에만 진다(같은 조 제2항). 그래서 해지했다고 해서 원칙적으로 배상의무가 생기지 않는다.","c":"상","v":1},"공인노2019_28-71-5":{"w":"제689조 제1항: 위임계약은 각 당사자가 언제든지 해지할 수 있다.","c":"상","v":1},"공인노2019_28-72-1":{"w":"통상의 임대차에서 임대인은 목적물을 사용·수익하게 할 의무를 질 뿐 임차인의 안전을 배려하거나 도난을 막을 보호의무까지 지지 않는다(판례). 숙박계약처럼 일시 사용을 위한 임대차와 다르다.","c":"중","v":1},"공인노2019_28-72-3":{"w":"임대인의 수선의무(제623조)는 파손이 임차인의 사용·수익을 방해할 정도일 때 생긴다. 별 비용 없이 고칠 수 있는 사소한 파손으로 사용·수익이 방해되지 않으면 수선의무가 없다(판례).","c":"중","v":1},"공인노2019_28-72-4":{"w":"임차인은 임차물을 선량한 관리자의 주의로 보존해 반환할 의무가 있다(제374조). 임차물이 화재로 멸실되어 반환이 불능이 되면 화재 원인이 불명이어도 임차인이 선관주의를 다했음을 증명해야 손해배상책임을 면한다(판례).","c":"중","v":1},"공인노2019_28-72-5":{"w":"제646조 제1항: 건물 기타 공작물의 임차인이 사용의 편익을 위해 임대인의 동의를 얻어 부속한 물건이 있으면 임대차 종료 시 임대인에게 그 부속물의 매수를 청구할 수 있다.","c":"상","v":1},"공인노2019_28-73-2":{"w":"제732조: 화해계약은 당사자 일방이 양보한 권리가 소멸되고 상대방이 화해로 인하여 그 권리를 취득하는 효력이 있다(창설적 효력).","c":"상","v":1},"공인노2019_28-73-3":{"w":"화해계약은 당사자가 서로 양보해 분쟁을 끝내기로 하는 계약이다(제731조). 채권자와 채무자가 남은 채무액을 계산하는 행위에는 서로 양보해 분쟁을 끝낸다는 요소가 없으므로 화해계약이 아니다(판례).","c":"중","v":1},"공인노2019_28-73-4":{"w":"제733조가 제한하는 것은 착오를 이유로 한 취소다. 상대방의 사기로 화해했다면 분쟁 대상에 관한 착오가 함께 있어도 제110조에 따라 사기를 이유로 취소할 수 있다(판례).","c":"중","v":1},"공인노2019_28-73-5":{"w":"화해는 당사자가 서로 양보해 분쟁을 끝내는 계약이므로(제731조) 당사자가 임의로 처분할 수 있는 법률관계만 대상이 된다. 친생자관계처럼 성질상 임의 처분이 안 되는 신분관계는 화해로 정할 수 없다(판례).","c":"중","v":1},"공인노2022_31-73-1":{"w":"제681조는 수임인에게 위임의 본지에 따라 선량한 관리자의 주의로 사무를 처리하게 하고 유상·무상을 구별하지 않는다. 그래서 무상수임인도 선관주의의무를 진다.","c":"상","v":1},"공인노2022_31-73-2":{"w":"제682조 제1항: 수임인은 위임인의 승낙이나 부득이한 사유 없이 제3자로 하여금 자기에 갈음하여 위임사무를 처리하게 하지 못한다. 반대로 부득이한 사유가 있으면 할 수 있다.","c":"상","v":1},"공인노2022_31-73-3":{"w":"위임은 원래 무상이지만(제686조 제1항) 변호사에게 소송사건을 맡기면서 보수를 명시하지 않았더라도 특별한 사정이 없는 한 응분의 보수를 지급하기로 하는 묵시적 약정이 있다고 본다(판례).","c":"중","v":1},"공인노2022_31-73-5":{"w":"제683조: 수임인은 위임이 종료한 때에는 지체 없이 그 전말을 위임인에게 보고하여야 한다.","c":"상","v":1},"공인노2024_33-32-1":{"w":"제564조 제1항: 매매의 일방예약은 상대방이 매매를 완결할 의사를 표시하는 때에 매매의 효력이 생긴다.","c":"상","v":1},"공인노2024_33-35-1":{"w":"도급은 일의 완성이 목적이고 누가 일을 하는지는 중요하지 않으므로 특약이 없으면 수급인은 이행대행자(하수급인 등)를 사용할 수 있다(판례). 수급인은 그 사람의 과실에 대해 제391조에 따라 책임진다.","c":"중","v":1},"공인노2024_33-35-2":{"w":"수급인 담보책임의 제척기간(제670조·제671조)은 재판상 청구를 위한 출소기간이 아니어서 그 기간 안에 재판 외에서 권리를 행사해도 된다(판례).","c":"중","v":1},"공인노2024_33-35-4":{"w":"제666조의 저당권설정청구권은 공사대금채권을 담보하기 위한 것이므로 공사대금채권이 양도되면 특별한 사정이 없는 한 양수인에게 함께 이전한다(판례).","c":"중","v":1},"공인노2024_33-35-5":{"w":"제673조의 해제는 도급인이 아무 이유 없이 해제할 수 있게 하는 대신 수급인의 손해를 모두 배상하게 하는 것이다. 그래서 그 배상에 수급인의 과실을 들어 과실상계나 손해배상예정액 감액을 주장할 수 없다(판례).","c":"중","v":1},"공인노2024_33-36-4":{"w":"제674조의7 제2항: 중대한 하자로 여행계약이 해지되면 여행주최자는 대금청구권을 잃지만 여행자가 실행된 여행으로 이익을 얻었으면 그 이익을 여행주최자에게 상환해야 한다.","c":"상","v":1},"공인노2024_33-37-1":{"w":"임대차 존속기간을 20년으로 제한하던 제651조는 헌법재판소 위헌결정 뒤 2016. 1. 6. 삭제되었다. 지금은 존속기간 상한이 없어 당사자가 임대차기간을 영구로 정하는 것도 허용된다(판례).","c":"중","v":1},"공인노2024_33-37-2":{"w":"임차인은 필요비를 지출하면 즉시 임대인에게 상환을 청구할 수 있다(제626조 제1항). 임대인의 필요비 상환의무와 임차인의 차임 지급의무는 서로 대응하므로 임차인은 필요비 한도에서 차임 지급을 거절할 수 있다(판례).","c":"중","v":1},"공인노2024_33-37-3":{"w":"제625조: 임대인이 임차인의 의사에 반하여 보존행위를 하는 경우 임차인이 이로 인하여 임차의 목적을 달성할 수 없는 때에는 계약을 해지할 수 있다.","c":"상","v":1},"공인노2024_33-37-5":{"w":"제629조: 임차인은 임대인의 동의 없이 임차권을 양도하거나 전대하지 못하고 이를 어기면 임대인은 계약을 해지할 수 있다. 다만 배신행위로 볼 수 없는 특별한 사정이 있으면 해지가 제한된다(판례).","c":"상","v":1},"공인노2025_34-34-1":{"w":"제565조의 해약금 해제는 당사자 일방이 이행에 착수하기 전까지만 할 수 있다. 여기서 일방에는 해제하려는 쪽도 포함되므로 중도금을 지급해 스스로 이행에 착수한 매수인은 매도인이 착수하지 않았어도 해약금 해제를 할 수 없다(판례).","c":"중","v":1},"공인노2025_34-36-1":{"w":"제643조가 준용하는 제283조의 매수청구권은 형성권이다. 행사하면 곧바로 임대인과 임차인 사이에 행사 당시 건물 시가를 대금으로 하는 매매계약이 맺어진 효과가 생긴다(판례).","c":"중","v":1},"공인노2025_34-36-3":{"w":"매수청구권 행사로 성립한 매매에서 乙의 건물 인도·소유권이전등기 의무와 甲의 대금지급 의무는 동시이행관계다. 乙이 자기 의무를 이행하거나 이행제공하지 않았다면 甲은 지체에 빠지지 않으므로 지연손해금을 청구할 수 없다(판례).","c":"중","v":1},"공인노2025_34-36-4":{"w":"제643조의 매수청구권은 건물이 현존하면 행사할 수 있다. 건물이 객관적으로 경제적 가치가 있는지 또는 임대인에게 소용이 있는지는 행사요건이 아니다(판례).","c":"중","v":1},"공인노2025_34-36-5":{"w":"乙은 동시이행항변권으로 건물 인도를 거부할 수 있지만 그 부지를 점유·사용해 얻는 차임 상당 이익은 법률상 원인 없는 이득이므로 甲에게 부당이득으로 반환해야 한다(판례).","c":"중","v":1},"공인노2025_34-38-1":{"w":"제703조 제2항: 조합의 출자는 금전 기타 재산 또는 노무로 할 수 있다.","c":"상","v":1},"공인노2025_34-38-3":{"w":"제706조 제3항: 조합의 통상사무는 각 조합원 또는 각 업무집행자가 전행할 수 있다. 다만 사무 완료 전에 다른 조합원이나 업무집행자가 이의하면 즉시 중지해야 한다.","c":"상","v":1},"공인노2025_34-38-4":{"w":"조합재산은 조합원 전원의 합유이므로(제704조) 조합원 1인만을 채무자로 한 가압류명령으로는 조합재산에 가압류집행을 할 수 없다(판례).","c":"중","v":1},"공인노2025_34-38-5":{"w":"조합계약은 단체적 성격이 있어 일반 계약처럼 해제해 원상회복을 구할 수 없다. 조합원은 탈퇴나 해산청구로 관계를 정리해야 한다(판례).","c":"중","v":1},"공인노2026_35-34-2":{"w":"기간의 정함이 없는 토지임대차에서 임대인의 해지통고로 임차권이 소멸한 경우에도 임차인은 제643조에 따라 지상물 매수를 청구할 수 있다(판례). 갱신청구 없이 바로 매수청구할 수 있다.","c":"중","v":1},"공인노2026_35-35-1":{"w":"제640조: 건물 기타 공작물의 임대차에서 임차인의 차임연체액이 2기의 차임액에 달하는 때에는 임대인은 계약을 해지할 수 있다.","c":"상","v":1},"공인노2026_35-35-2":{"w":"제619조 제3호: 처분의 능력 또는 권한 없는 자가 건물 기타 공작물을 임대하는 경우 그 기간은 3년을 넘지 못한다. 3년까지는 정할 수 있다.","c":"상","v":1},"공인노2026_35-35-4":{"w":"제630조 제1항: 임대인의 동의를 얻어 전대한 때에는 전차인은 직접 임대인에 대하여 의무를 부담한다.","c":"상","v":1},"공인노2026_35-35-5":{"w":"제639조 제2항: 묵시의 갱신이 된 경우 전 임대차에 대하여 제3자가 제공한 담보는 기간의 만료로 소멸한다.","c":"상","v":1},"공인노2017_26-74-1":{"w":"제741조의 이익은 재산이 늘어난 모든 경우를 말하므로 소유권 같은 물권뿐 아니라 채권을 취득한 것도 이익에 해당한다(통설·판례).","c":"중","v":1},"공인노2017_26-74-2":{"w":"제744조: 채무 없는 자가 착오로 변제한 경우에 그 변제가 도의관념에 적합한 때에는 그 반환을 청구하지 못한다.","c":"상","v":1},"공인노2017_26-74-3":{"w":"법률상 원인 없이 남의 건물을 점유해 사용하면 그 사용이익만큼 이득을 얻고 소유자는 같은 액수만큼 손해를 입으므로 차임 상당액을 부당이득으로 반환해야 한다(제741조, 판례).","c":"중","v":1},"공인노2017_26-74-4":{"w":"금전은 대체성이 있어 취득자가 소비했더라도 그만큼 다른 재산 지출을 면한 것이므로 현존이익이 있는 것으로 추정된다. 이익이 현존하지 않는다는 점은 반환청구를 받은 쪽이 증명해야 한다(판례).","c":"중","v":1},"공인노2019_28-75-5":{"w":"원물을 처분해 반환할 수 없으면 가액을 반환하는데(제747조 제1항) 그 가액은 특별한 사정이 없는 한 수익자가 처분하고 받은 대가다(판례).","c":"중","v":1},"공인노2022_31-74-5":{"w":"제741조는 부당이득 요건으로 이익을 얻고 「이로 인하여 타인에게 손해를 가한」 것을 요구한다. 손해를 입은 사람이 없으면 부당이득반환청구권은 성립하지 않는다.","c":"상","v":1},"공인노2024_33-38-1":{"w":"사무관리는 의무 없이 남의 사무를 처리할 때 성립한다(제734조). 제3자와의 약정에 따라 사무를 처리했다면 그 약정상 의무를 이행한 것이므로 원칙적으로 그 타인과의 관계에서 사무관리가 되지 않는다(판례).","c":"중","v":1},"공인노2024_33-38-2":{"w":"사무관리는 본인의 의사에 반하거나 본인에게 불리함이 명백하지 않아야 성립한다(제734조·제737조 단서 취지). 본인의 의사에 반하는 것이 명백하면 특별한 사정이 없는 한 사무관리가 성립하지 않는다(판례).","c":"중","v":1},"공인노2024_33-38-4":{"w":"사무관리로 제3자가 결과적으로 이익을 얻었더라도 그것은 본인에 대한 비용상환청구권 등 관리자의 권리가 따로 있어 생긴 반사적 이익이다. 그래서 관리자가 제3자에게 직접 부당이득반환을 청구할 수 없다(판례).","c":"중","v":1},"공인노2024_33-38-5":{"w":"사무관리 요건인 「타인을 위하여 처리하는 의사」는 관리자 자신의 이익을 위한 의사와 함께 있어도 된다(판례). 타인을 위한 의사가 오로지 있어야 하는 것은 아니다.","c":"중","v":1},"공인노2019_28-74-1":{"w":"제762조는 태아를 손해배상청구권에 관하여 이미 출생한 것으로 보지만 판례는 살아서 출생해야 권리능력을 소급해 취득한다고 본다(정지조건설). 모체 안에서 사망한 태아는 손해배상청구권을 갖지 못한다.","c":"중","v":1},"공인노2019_28-74-2":{"w":"제496조: 채무가 고의의 불법행위로 인한 것인 때에는 그 채무자는 상계로 채권자에게 대항하지 못한다.","c":"상","v":1},"공인노2019_28-74-3":{"w":"재산권 침해로 인한 정신적 고통은 재산적 손해가 배상되면 회복된다고 본다. 그래서 위자료는 재산적 손해 배상으로 회복할 수 없는 정신적 손해가 따로 있고 가해자가 그 사정을 알았거나 알 수 있었을 때에만 인정된다(제751조, 판례).","c":"중","v":1},"공인노2019_28-74-5":{"w":"책임능력 있는 미성년자의 불법행위에는 제755조가 적용되지 않는다. 다만 감독의무자의 의무위반과 손해 사이에 상당인과관계가 있으면 감독의무자도 제750조의 일반불법행위책임을 진다(판례).","c":"중","v":1},"공인노2025_34-40-1":{"w":"제760조 제3항의 방조는 과실로도 성립하지만 방조자에게 공동불법행위 책임을 지우려면 방조행위와 피해자의 손해 발생 사이에 상당인과관계가 있어야 한다(판례).","c":"중","v":1}};
